import type { BacklogTree } from './_types';

export const BACKLOG: BacklogTree =  {"epics":[{"folder":"EPIC-01-Acesso-e-Perfis","code":"EPIC-01","title":"Acesso e Perfis","pendente":false,"features":[{"file":"F02-Usuarios","code":"F01","title":"Usuários","description":"Cadastro de usuários do sistema TFD. Cada usuário tem um papel (que define permissões), pode ser ativado/desativado, e — para médicos — guarda CRM/UF/especialidade que viram snapshot nos pareceres emitidos.","meta":[{"key":"Tela","value":"`/sistema/usuarios` (listagem) · `/meu-perfil` (perfil próprio)"},{"key":"Drawer","value":"`UsuarioDrawer`"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/sistema/usuarios/page.tsx` · `src/app/sistema/usuarios/_UsuarioDrawer.tsx` · `src/app/meu-perfil/page.tsx`"},{"key":"Serviço","value":"`src/services/usuarios.service.ts`"},{"key":"Tabela","value":"`usuarios` (estende `auth.users` do Supabase)"}],"userStories":[{"id":"US-USR-01","title":"Listar usuários","story":"**Como** Administrador, **Quero** ver todos os usuários cadastrados em uma tabela, **Para que** eu gerencie acessos e perfis.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/sistema/usuarios/page.tsx`\n- Componentes compartilhados: `PageHeader`, `StatsRow`, `SortableHeader`, `tfd-table`\n- Serviço: `listarUsuarios({ search, papelFiltro, statusFiltro, page, pageSize })`"},{"title":"Layout","body":"- `PageHeader title=\"Usuários\" subtitle=\"Gestão de acessos ao sistema TFD\"`\n- Action: \"+ Novo usuário\" (em `<Can action=\"sys_usuarios.criar\">`)\n- `StatsRow`: Total de Usuários, Ativos, Médicos com CRM\n- Toolbar: busca + 2 selects (Papel, Status)"},{"title":"Critérios de aceite","body":"- [ ] Sidebar → \"Administrativo\" → \"Usuários\" → `/sistema/usuarios`\n- [ ] Header com title/subtitle\n- [ ] Busca placeholder \"Buscar por nome, email ou CPF\" (debounce 300ms)\n- [ ] Filtro de Papel: select com todos os papéis cadastrados + \"Todos\" (default)\n- [ ] Filtro de Status: \"Ativo\" (default) / \"Inativo\" / \"Todos\"\n- [ ] Tabela com colunas: Nome (sortable) · Email (sortable, mono) · CPF (mono) · Papel (badge colorido) · Status (badge) · Último login (sortable) · Ações (Pencil, toggle ativar/desativar)\n- [ ] Linha clicável → abre drawer de edição\n- [ ] Paginação 25 por página (10/25/50/100)\n- [ ] Estado vazio: \"Nenhum usuário encontrado\""},{"title":"Estados visuais","body":"- **Ativo**: badge verde\n- **Inativo**: badge cinza + linha levemente acinzentada"},{"title":"Side effects","body":"- Reset paginação ao trocar busca/filtro\n- Refetch após criar/editar/inativar"},{"title":"Regras de negócio","body":"- Apenas Admin acessa essa tela\n- Busca cobre `nome`, `email`, `cpf`\n- Default: ordenação por `nome` asc\n- Coluna \"Último login\" pode estar vazia se usuário nunca logou"},{"title":"Schema (banco)","body":"- Tabela `usuarios`: `id` (= auth.users.id), `nome_completo`, `email` (UNIQUE), `cpf` (UNIQUE), `telefone`, `papel_id` (FK), `medico_crm`, `medico_crm_uf`, `medico_especialidade`, `ativo`, `ultimo_login`, timestamps"},{"title":"Permissões","body":"- `sys_usuarios.visualizar` (Admin)"},{"title":"Dependências","body":"- [[F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]\n\n---"}],"criterios":["Sidebar → \"Administrativo\" → \"Usuários\" → `/sistema/usuarios`","Header com title/subtitle","Busca placeholder \"Buscar por nome, email ou CPF\" (debounce 300ms)","Filtro de Papel: select com todos os papéis cadastrados + \"Todos\" (default)","Filtro de Status: \"Ativo\" (default) / \"Inativo\" / \"Todos\"","Tabela com colunas: Nome (sortable) · Email (sortable, mono) · CPF (mono) · Papel (badge colorido) · Status (badge) · Último login (sortable) · Ações (Pencil, toggle ativar/desativar)","Linha clicável → abre drawer de edição","Paginação 25 por página (10/25/50/100)","Estado vazio: \"Nenhum usuário encontrado\""],"regras":["Apenas Admin acessa essa tela","Busca cobre `nome`, `email`, `cpf`","Default: ordenação por `nome` asc","Coluna \"Último login\" pode estar vazia se usuário nunca logou"],"dependencias":["[[F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]","--"]},{"id":"US-USR-02","title":"Cadastrar novo usuário","story":"**Como** Administrador, **Quero** cadastrar novo usuário com email, papel e dados pessoais, **Para que** ele possa acessar o sistema.","sections":[{"title":"Componentes do protótipo","body":"- Drawer: `UsuarioDrawer` (largura 560px)\n- LookupSelect para Papel (lista papéis ativos da tabela `papeis`)\n- Campos médicos aparecem condicionalmente\n- Serviço: `criarUsuario(payload)` — cria entry em `auth.users` + `usuarios` + dispara email"},{"title":"Campos do formulário","body":"| Campo                | Tipo         | Obrig.            | Validação                                | Mensagem                                  |\n|----------------------|--------------|-------------------|------------------------------------------|-------------------------------------------|\n| Nome completo        | text         | sim               | ≥ 3 caracteres                           | \"Informe o nome completo\"                 |\n| Email                | email        | sim               | formato + único + não pode ser temporário | \"Email inválido\" / \"Email já cadastrado\" |\n| CPF                  | text         | sim               | máscara + dígitos verificadores + único | \"CPF inválido\" / \"CPF já cadastrado\"     |\n| Telefone             | tel          | não               | máscara `(XX) XXXXX-XXXX`                | —                                          |\n| Papel                | LookupSelect | sim               | item ativo de `papeis`                  | \"Selecione um papel\"                      |\n| CRM                  | text         | se papel é médico | numérico + UF                            | \"Informe o CRM\"                           |\n| UF do CRM            | select       | se CRM preenchido | autocomplete UF                          | —                                          |\n| Especialidade médica | LookupSelect | se médico         | `especialidade_medica`                  | \"Selecione a especialidade\"               |"},{"title":"Critérios de aceite","body":"- [ ] Click \"+ Novo usuário\" → drawer 560px\n- [ ] Title: \"Novo usuário\"\n- [ ] Foco inicial no Nome\n- [ ] Email/CPF únicos: duplicidade mostra erro inline + bloqueia salvar\n- [ ] Quando o papel selecionado tem permissão `regulacao.emitir_parecer`: campos CRM, UF, Especialidade aparecem (e ficam obrigatórios)\n- [ ] Quando o papel muda para não-médico: campos CRM/UF/Especialidade somem e são limpos\n- [ ] Validação de email: formato `nome@dominio.tld`\n- [ ] CRM: numérico + UF (default UF do usuário logado)\n- [ ] \"Salvar\" → spinner → drawer fecha → toast verde \"Usuário criado. Email de primeiro acesso enviado para {email}\"\n- [ ] Erro: drawer permanece + toast vermelho com mensagem do Supabase\n- [ ] Cancel com mudanças → modal \"Descartar alterações?\""},{"title":"Estados visuais","body":"- **Médico flag ativa**: 3 campos extras aparecem com animação fade\n- **Saving**: spinner"},{"title":"Side effects no sucesso","body":"- INSERT em `auth.users` (via Supabase Admin API ou função SQL)\n- INSERT em `usuarios` com FK para `auth.users.id`\n- Dispara email com link de primeiro acesso (token expira em 7 dias)\n- Log de auditoria\n- Refetch da tabela"},{"title":"Regras de negócio","body":"- Novo usuário entra **ativo**\n- Senha NÃO é definida pelo admin — usuário define no primeiro acesso via link\n- Email é o login (não muda — para alterar, criar novo usuário)\n- CRM/UF/Especialidade são snapshot — usados em pareceres emitidos\n- Email único globalmente; CPF único globalmente"},{"title":"Schema (banco)","body":"- INSERT em `auth.users` (Supabase auth) + INSERT em `usuarios`\n- Trigger envia email automaticamente\n- Constraints UNIQUE em `email`, `cpf`"},{"title":"Permissões","body":"- `sys_usuarios.criar`"},{"title":"Auditoria","body":"- Log: `entity_type='usuario'`, `action='create'`, snapshot (sem senha)"},{"title":"Dependências","body":"- US-USR-01\n- [[F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]\n\n---"}],"criterios":["Click \"+ Novo usuário\" → drawer 560px","Title: \"Novo usuário\"","Foco inicial no Nome","Email/CPF únicos: duplicidade mostra erro inline + bloqueia salvar","Quando o papel selecionado tem permissão `regulacao.emitir_parecer`: campos CRM, UF, Especialidade aparecem (e ficam obrigatórios)","Quando o papel muda para não-médico: campos CRM/UF/Especialidade somem e são limpos","Validação de email: formato `nome@dominio.tld`","CRM: numérico + UF (default UF do usuário logado)","\"Salvar\" → spinner → drawer fecha → toast verde \"Usuário criado. Email de primeiro acesso enviado para {email}\"","Erro: drawer permanece + toast vermelho com mensagem do Supabase","Cancel com mudanças → modal \"Descartar alterações?\""],"regras":["Novo usuário entra **ativo**","Senha NÃO é definida pelo admin — usuário define no primeiro acesso via link","Email é o login (não muda — para alterar, criar novo usuário)","CRM/UF/Especialidade são snapshot — usados em pareceres emitidos","Email único globalmente; CPF único globalmente"],"dependencias":["US-USR-01","[[F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]","--"]},{"id":"US-USR-03","title":"Editar usuário existente","story":"**Como** Administrador, **Quero** atualizar dados de um usuário, **Para que** o cadastro fique em dia (mudar papel, atualizar telefone, etc.).","sections":[{"title":"Componentes do protótipo","body":"- Mesmo `UsuarioDrawer` em modo edit\n- Serviço: `atualizarUsuario(id, payload)`"},{"title":"Critérios de aceite","body":"- [ ] Lápis na linha → drawer \"Editar usuário\" com dados preenchidos\n- [ ] Email **NÃO editável** (readOnly + tooltip \"Email é o login, não pode ser alterado\")\n- [ ] CPF **NÃO editável**\n- [ ] Demais campos editáveis\n- [ ] Mudança de papel registra log especial \"Papel alterado de {X} para {Y}\"\n- [ ] Salvar → spinner → toast \"Usuário atualizado\" + warning amarelo se mudou papel: \"Usuário precisará fazer logout/login para aplicar mudança de papel\"\n- [ ] Cancel com mudanças → modal de confirmação"},{"title":"Estados visuais","body":"- Pristine / Dirty / Saving / Erro\n- **Mudança de papel**: warning amarelo no toast"},{"title":"Side effects","body":"- UPDATE em `usuarios`\n- Log com diff\n- (Se mudou papel) Invalida cache de permissões do usuário"},{"title":"Regras de negócio","body":"- Alterações vão para log de auditoria detalhado\n- Mudança de papel impacta permissões — usuário precisa relogar (warning explícito no toast)\n- Admin não pode editar próprio papel (proteção contra lock-out)"},{"title":"Schema (banco)","body":"- UPDATE em `usuarios`"},{"title":"Permissões","body":"- `sys_usuarios.editar`"},{"title":"Auditoria","body":"- Log: `action='update'`, diff por campo (com flag especial para mudança de papel)"},{"title":"Dependências","body":"- US-USR-02\n\n---"}],"criterios":["Lápis na linha → drawer \"Editar usuário\" com dados preenchidos","Email **NÃO editável** (readOnly + tooltip \"Email é o login, não pode ser alterado\")","CPF **NÃO editável**","Demais campos editáveis","Mudança de papel registra log especial \"Papel alterado de {X} para {Y}\"","Salvar → spinner → toast \"Usuário atualizado\" + warning amarelo se mudou papel: \"Usuário precisará fazer logout/login para aplicar mudança de papel\"","Cancel com mudanças → modal de confirmação"],"regras":["Alterações vão para log de auditoria detalhado","Mudança de papel impacta permissões — usuário precisa relogar (warning explícito no toast)","Admin não pode editar próprio papel (proteção contra lock-out)"],"dependencias":["US-USR-02","--"]},{"id":"US-USR-04","title":"Ativar / desativar usuário","story":"**Como** Administrador, **Quero** desativar usuários que saíram do TFD, **Para que** eles não consigam mais acessar o sistema.","sections":[{"title":"Componentes do protótipo","body":"- Toggle ou botão na linha (similar a US-CFG-05)\n- Modal de confirmação para desativação\n- Serviço: `toggleAtivoUsuario(id, ativo)`"},{"title":"Critérios de aceite","body":"- [ ] Linha ativa: botão \"Desativar\" (vermelho)\n- [ ] Linha inativa: botão \"Reativar\" (verde)\n- [ ] Desativar → modal \"Desativar usuário?\" + aviso \"Ele perderá acesso imediatamente; sessões ativas serão encerradas.\"\n- [ ] Confirma → toast \"Usuário desativado\"\n- [ ] Linha some (se filtro = Ativos) ou muda chip (se filtro = Todos)\n- [ ] Reativar → toast direto \"Usuário reativado\" (sem modal)\n- [ ] Usuário desativado tenta logar → mensagem \"Conta inativa — contate o administrador\"\n- [ ] Admin NÃO pode desativar a própria conta (botão disabled + tooltip \"Você não pode desativar sua própria conta\")"},{"title":"Estados visuais","body":"- **Desativando**: spinner\n- **Disabled (própria conta)**: cinza + tooltip"},{"title":"Side effects","body":"- UPDATE `set ativo = X` em `usuarios`\n- Se desativando: invalida sessões ativas do usuário (Supabase Admin: `signOut` de todas as sessões)\n- Log de auditoria"},{"title":"Regras de negócio","body":"- Sempre soft delete (nunca remove fisicamente)\n- Sessões ativas do usuário desativado são **invalidadas imediatamente** — próxima request derruba\n- Pareceres, observações e logs do usuário permanecem com snapshot original\n- Admin não pode desativar a si mesmo"},{"title":"Schema (banco)","body":"- UPDATE em `usuarios`"},{"title":"Permissões","body":"- `sys_usuarios.excluir`"},{"title":"Auditoria","body":"- Log: `action='deactivate'` / `action='reactivate'`"},{"title":"Dependências","body":"- US-USR-01\n\n---"}],"criterios":["Linha ativa: botão \"Desativar\" (vermelho)","Linha inativa: botão \"Reativar\" (verde)","Desativar → modal \"Desativar usuário?\" + aviso \"Ele perderá acesso imediatamente; sessões ativas serão encerradas.\"","Confirma → toast \"Usuário desativado\"","Linha some (se filtro = Ativos) ou muda chip (se filtro = Todos)","Reativar → toast direto \"Usuário reativado\" (sem modal)","Usuário desativado tenta logar → mensagem \"Conta inativa — contate o administrador\"","Admin NÃO pode desativar a própria conta (botão disabled + tooltip \"Você não pode desativar sua própria conta\")"],"regras":["Sempre soft delete (nunca remove fisicamente)","Sessões ativas do usuário desativado são **invalidadas imediatamente** — próxima request derruba","Pareceres, observações e logs do usuário permanecem com snapshot original","Admin não pode desativar a si mesmo"],"dependencias":["US-USR-01","--"]},{"id":"US-USR-05","title":"Editar meu próprio perfil","story":"**Como** qualquer usuário do sistema, **Quero** editar meus dados em \"Meu Perfil\", **Para que** correções (telefone, CRM, especialidade) sejam feitas sem depender do admin.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/meu-perfil/page.tsx`\n- Avatar no canto superior direito do header → menu dropdown → \"Meu Perfil\"\n- Serviços: `atualizarMeuPerfil(payload)`, `solicitarTrocaSenha()` em `usuarios.service`"},{"title":"Layout","body":"- `PageHeader title=\"Meu Perfil\"`\n- Card centralizado (max-width 640):\n  - Avatar grande (96px) com iniciais + botão \"Trocar foto\" (futuro, não MVP)\n  - Form em 2 colunas:\n    - **Identificação** (read-only): Nome + Email + CPF\n    - **Contato** (editável): Telefone\n    - **Profissional** (editável, se médico): CRM, UF, Especialidade\n  - Botão \"Salvar alterações\"\n  - Link \"Alterar senha\" → abre modal de redefinição"},{"title":"Critérios de aceite","body":"- [ ] Avatar do header → \"Meu Perfil\" → `/meu-perfil`\n- [ ] Tela mostra avatar grande + nome + email\n- [ ] Identificação read-only (Nome, Email, CPF — com cadeado e tooltip \"Apenas o admin pode alterar\")\n- [ ] Telefone editável\n- [ ] CRM/UF/Especialidade editáveis se o usuário tem papel médico\n- [ ] \"Salvar alterações\" → toast \"Perfil atualizado\" (com warning amarelo se mudou CRM/UF/Especialidade: \"Mudanças se aplicam apenas a pareceres futuros, não retroativos\")\n- [ ] Link \"Alterar senha\" → abre modal/fluxo de redefinição (envia email com link)"},{"title":"Estados visuais","body":"- **Pristine / Dirty**: botão Salvar enabled/disabled\n- **Saving**: spinner"},{"title":"Side effects","body":"- UPDATE em `usuarios` (campos editáveis)\n- Log de auditoria"},{"title":"Regras de negócio","body":"- Usuário NÃO pode mudar próprio papel (admin only)\n- Email é o login — só admin altera (criando novo usuário)\n- Mudança em CRM/UF/Especialidade impacta apenas pareceres futuros (não retroativo) — warning no toast\n- \"Alterar senha\" envia email com link (não permite definir senha direto na tela por questão de segurança)"},{"title":"Schema (banco)","body":"- UPDATE em `usuarios` (apenas campos permitidos)"},{"title":"Permissões","body":"- Qualquer usuário autenticado (acesso ao próprio perfil)"},{"title":"Auditoria","body":"- Log: `action='self_update'`, `user_id = entity_id` (auto-edit)"},{"title":"Dependências","body":"- US-USR-02"}],"criterios":["Avatar do header → \"Meu Perfil\" → `/meu-perfil`","Tela mostra avatar grande + nome + email","Identificação read-only (Nome, Email, CPF — com cadeado e tooltip \"Apenas o admin pode alterar\")","Telefone editável","CRM/UF/Especialidade editáveis se o usuário tem papel médico","\"Salvar alterações\" → toast \"Perfil atualizado\" (com warning amarelo se mudou CRM/UF/Especialidade: \"Mudanças se aplicam apenas a pareceres futuros, não retroativos\")","Link \"Alterar senha\" → abre modal/fluxo de redefinição (envia email com link)"],"regras":["Usuário NÃO pode mudar próprio papel (admin only)","Email é o login — só admin altera (criando novo usuário)","Mudança em CRM/UF/Especialidade impacta apenas pareceres futuros (não retroativo) — warning no toast","\"Alterar senha\" envia email com link (não permite definir senha direto na tela por questão de segurança)"],"dependencias":["US-USR-02"]},{"id":"US-AUT-01","title":"Tela de Login redesenhada com painel institucional 2-colunas","story":"**Como** Usuário do sistema, **Quero** entrar com um layout que reforce a identidade visual SES + TFD, **Para que** tenha confiança de que estou no sistema oficial.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/login/page.tsx`\n- Layout 2 colunas (grid `lg:grid-cols-2`)\n- Painel esquerdo institucional: gradient azul SES + ícones decorativos `ShieldCheck`, `HeartPulse`, `MapPin` (lucide-react)\n- Painel direito: formulário CPF + senha\n- Autenticação: RPC `get_email_by_cpf` no Supabase + `signInWithPassword`\n- Validação inline (CPF obrigatório, senha obrigatória) com mensagens de erro abaixo dos inputs"},{"title":"Layout","body":"- **Desktop (lg+)**: 2 colunas 50/50\n  - **Esquerda**: gradient `from-blue-700 via-blue-800 to-blue-900` ocupando altura total\n    - Logo SES no topo (canto superior esquerdo)\n    - Bloco central com texto de boas-vindas: \"Bem-vindo(a) ao Sistema TFD\" + subtítulo\n    - 3 cards decorativos com ícones: `ShieldCheck` (Acesso seguro), `HeartPulse` (Atendimento humanizado), `MapPin` (Cobertura estadual)\n    - Rodapé com créditos SES / governo\n  - **Direita**: fundo branco com card centralizado contendo logo TFD + form\n- **Mobile (<lg)**: 1 coluna, painel direito ocupa tela inteira, painel esquerdo oculto"},{"title":"Critérios de aceite","body":"- [ ] Layout 2 colunas em telas >= 1024px (lg)\n- [ ] Painel decorativo com gradient azul + 3 ícones lucide (`ShieldCheck`, `HeartPulse`, `MapPin`) e textos institucionais\n- [ ] Autenticação por CPF: o input aceita CPF (com ou sem máscara), faz RPC `get_email_by_cpf` e usa o email retornado em `signInWithPassword`\n- [ ] Validação de campos: CPF e senha obrigatórios, com mensagens de erro inline (vermelho) abaixo de cada input\n- [ ] Em mobile, exibe apenas o painel do formulário (1 coluna) e o painel decorativo é oculto via `hidden lg:flex`\n- [ ] Estados: loading no botão \"Entrar\" enquanto autentica; toast/inline error se CPF não autorizado ou senha incorreta"},{"title":"Regras de negócio","body":"- Autenticação não usa email direto: o usuário digita CPF e o sistema chama RPC `get_email_by_cpf(p_cpf text)` que devolve o email vinculado em `cpfs_autorizados`\n- Se o CPF não existir em `cpfs_autorizados`, retorna erro genérico (\"CPF ou senha inválidos\") sem revelar qual campo está errado\n- Layout responsivo: a partir de `lg` (1024px) usa 2 colunas; abaixo disso, apenas o form ocupa a viewport\n- Mensagem de erro genérica inline abaixo do form: nunca distinguir \"CPF inexistente\" de \"senha errada\" (segurança)"},{"title":"Estados visuais","body":"- **Idle**: form pronto para preenchimento\n- **Submitting**: botão \"Entrar\" com spinner + disabled\n- **Erro**: mensagem inline vermelha \"CPF ou senha inválidos\" abaixo do botão\n- **Sucesso**: redirect para `/` (dashboard)"},{"title":"Dependências","body":"- Tabela auxiliar `cpfs_autorizados`\n- RPC `get_email_by_cpf` no Supabase\n- US-USR-02 (cadastro de usuário cria entrada em `cpfs_autorizados`)\n\n---"}],"criterios":["Layout 2 colunas em telas >= 1024px (lg)","Painel decorativo com gradient azul + 3 ícones lucide (`ShieldCheck`, `HeartPulse`, `MapPin`) e textos institucionais","Autenticação por CPF: o input aceita CPF (com ou sem máscara), faz RPC `get_email_by_cpf` e usa o email retornado em `signInWithPassword`","Validação de campos com mensagens de erro inline (CPF e senha obrigatórios)"],"regras":["Autenticação via RPC `get_email_by_cpf` — usuário digita CPF, sistema resolve email vinculado em `cpfs_autorizados`","Layout responsivo: 2 colunas em `lg+`, 1 coluna em mobile (painel decorativo oculto via `hidden lg:flex`)","Mensagem de erro genérica inline (\"CPF ou senha inválidos\") — nunca revela qual campo falhou"],"dependencias":["Tabela `cpfs_autorizados`","RPC `get_email_by_cpf`","US-USR-02","--"]}]},{"file":"F03-Papeis-e-Permissoes","code":"F02","title":"Papéis e Permissões","description":"Gestão dos papéis (roles) do sistema e suas permissões por tela/ação. Cada usuário é vinculado a um papel; o papel define o que ele pode ver e fazer. Existem 6 papéis padrão (Admin Master, Atendente, Médico Regulador, Coord. Médica, Financeiro, Coord. Estadual) e o admin pode criar customizados.","meta":[{"key":"Tela","value":"`/sistema/papeis` (listagem) · `/sistema/papeis/[id]` (detalhe + matriz)"},{"key":"Drawer","value":"`PapelDrawer` (criar/editar nome/descrição)"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/sistema/papeis/page.tsx` · `src/app/sistema/papeis/[id]/page.tsx` · `src/app/sistema/papeis/_PapelDrawer.tsx`"},{"key":"Serviços","value":"`src/services/papeis.service.ts` (listarPapeis, criarPapel, atualizarPermissoes)"},{"key":"Componente Can","value":"`src/shared/auth/Can.tsx` (consumidor das permissões)"},{"key":"Provider","value":"`src/shared/auth/PermissionsProvider.tsx`"},{"key":"Tabelas","value":"`papeis` · `papel_permissoes` · `permissoes` (catálogo)"}],"userStories":[{"id":"US-PAP-01","title":"Listar papéis","story":"**Como** Administrador, **Quero** ver todos os papéis e quantos usuários estão em cada, **Para que** eu gerencie a estrutura de acessos do TFD.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/sistema/papeis/page.tsx`\n- Componentes compartilhados habituais\n- Serviço: `listarPapeis()` com counts de usuários e permissões"},{"title":"Layout","body":"- `PageHeader title=\"Papéis e Permissões\" subtitle=\"Gestão de perfis de acesso ao sistema\"`\n- Action: \"+ Novo papel\" (em `<Can action=\"sys_papeis.criar\">`)\n- Tabela sem filtros (papéis são poucos)"},{"title":"Critérios de aceite","body":"- [ ] Sidebar → \"Administrativo\" → \"Papéis\" → `/sistema/papeis`\n- [ ] Header + subtitle\n- [ ] Tabela com colunas: Nome (sortable, link) · Descrição · Tipo (badge \"Padrão\"/\"Customizado\") · Qtd. usuários (numérico, sortable) · Qtd. permissões (numérico) · Ações\n- [ ] Papéis padrão: badge cinza \"Padrão\" + ícone de cadeado pequeno\n- [ ] Papéis customizados: badge azul \"Customizado\"\n- [ ] Click no nome → `/sistema/papeis/[id]` (detalhe + matriz)\n- [ ] Lápis abre `PapelDrawer` (editar nome/descrição)\n- [ ] Lixeira: oculta para padrões; visível para customizados\n- [ ] Estado vazio: \"Nenhum papel cadastrado\" (raríssimo — sempre há os padrões)"},{"title":"Estados visuais","body":"- **Padrão**: badge cinza + ícone cadeado\n- **Customizado**: badge azul + lápis e lixeira visíveis"},{"title":"Regras de negócio","body":"- 6 papéis padrão criados via seed:\n  1. Admin Master\n  2. Administrador\n  3. Atendente TFD\n  4. Médico Regulador\n  5. Coordenação Médica\n  6. Coordenação Estadual\n  7. Financeiro\n- Papéis padrão NÃO podem ser **excluídos** nem ter o **nome alterado** (mas suas permissões podem ser ajustadas)\n- Apenas Admin Master e Administrador acessam essa tela"},{"title":"Schema (banco)","body":"- Tabela `papeis`: `id`, `nome` (UNIQUE), `descricao`, `tipo` (`padrao`/`customizado`), `created_at`\n- Tabela `permissoes` (catálogo): `id`, `codigo` (ex.: `pacientes.criar`), `modulo`, `acao`, `descricao`\n- Tabela `papel_permissoes`: `id`, `papel_id`, `permissao_id` (N:N)"},{"title":"Permissões","body":"- `sys_papeis.visualizar`"},{"title":"Dependências","body":"- [[F02-Usuarios|F02 — Usuários]]\n\n---"}],"criterios":["Sidebar → \"Administrativo\" → \"Papéis\" → `/sistema/papeis`","Header + subtitle","Tabela com colunas: Nome (sortable, link) · Descrição · Tipo (badge \"Padrão\"/\"Customizado\") · Qtd. usuários (numérico, sortable) · Qtd. permissões (numérico) · Ações","Papéis padrão: badge cinza \"Padrão\" + ícone de cadeado pequeno","Papéis customizados: badge azul \"Customizado\"","Click no nome → `/sistema/papeis/[id]` (detalhe + matriz)","Lápis abre `PapelDrawer` (editar nome/descrição)","Lixeira: oculta para padrões; visível para customizados","Estado vazio: \"Nenhum papel cadastrado\" (raríssimo — sempre há os padrões)"],"regras":["6 papéis padrão criados via seed:","Papéis padrão NÃO podem ser **excluídos** nem ter o **nome alterado** (mas suas permissões podem ser ajustadas)","Apenas Admin Master e Administrador acessam essa tela"],"dependencias":["[[F02-Usuarios|F02 — Usuários]]","--"]},{"id":"US-PAP-02","title":"Criar novo papel customizado","story":"**Como** Administrador, **Quero** criar um papel customizado com permissões específicas, **Para que** eu cubra perfis fora do padrão (Auditor Externo, Estagiário, Suporte).","sections":[{"title":"Componentes do protótipo","body":"- Drawer: `PapelDrawer` (largura 480px)\n- Serviço: `criarPapel({ nome, descricao })`"},{"title":"Campos do formulário","body":"| Campo     | Tipo     | Obrig. | Validação                       | Mensagem                          |\n|-----------|----------|--------|---------------------------------|-----------------------------------|\n| Nome      | text     | sim    | ≥ 3 caracteres, único           | \"Já existe um papel com este nome\" |\n| Descrição | textarea | não    | ≤ 200 caracteres                | —                                  |"},{"title":"Critérios de aceite","body":"- [ ] Click \"+ Novo papel\" → drawer 480px\n- [ ] Title: \"Novo papel\"\n- [ ] Subtitle: \"Defina nome e descrição. As permissões são configuradas no próximo passo.\"\n- [ ] Foco inicial no Nome\n- [ ] Nome único (case-insensitive) → erro inline\n- [ ] \"Salvar\" → cria papel SEM permissões → drawer fecha → toast verde \"Papel criado. Configure as permissões abaixo.\" → navega para `/sistema/papeis/{id}` (detalhe)"},{"title":"Estados visuais","body":"- Pristine / Dirty / Saving / Erro"},{"title":"Side effects","body":"- INSERT em `papeis` com `tipo='customizado'`\n- Log de auditoria\n- Redirect para detalhe do papel (matriz de permissões)"},{"title":"Regras de negócio","body":"- Nome único entre papéis (case-insensitive)\n- Papel novo nasce sem nenhuma permissão (admin atribui depois)\n- Tipo é sempre `customizado` (papéis padrão são apenas via seed)"},{"title":"Schema (banco)","body":"- INSERT em `papeis`"},{"title":"Permissões","body":"- `sys_papeis.criar`"},{"title":"Auditoria","body":"- Log: `entity_type='papel'`, `action='create'`"},{"title":"Dependências","body":"- US-PAP-01\n\n---"}],"criterios":["Click \"+ Novo papel\" → drawer 480px","Title: \"Novo papel\"","Subtitle: \"Defina nome e descrição. As permissões são configuradas no próximo passo.\"","Foco inicial no Nome","Nome único (case-insensitive) → erro inline","\"Salvar\" → cria papel SEM permissões → drawer fecha → toast verde \"Papel criado. Configure as permissões abaixo.\" → navega para `/sistema/papeis/{id}` (detalhe)"],"regras":["Nome único entre papéis (case-insensitive)","Papel novo nasce sem nenhuma permissão (admin atribui depois)","Tipo é sempre `customizado` (papéis padrão são apenas via seed)"],"dependencias":["US-PAP-01","--"]},{"id":"US-PAP-03","title":"Editar permissões de um papel (matriz)","story":"**Como** Administrador, **Quero** marcar/desmarcar permissões de um papel em uma matriz, **Para que** eu controle precisamente o que cada perfil consegue fazer.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/sistema/papeis/[id]/page.tsx`\n- Componente `MatrizPermissoes` (definido inline na página)\n- Catálogo de permissões: lido de `permissoes` (constante no banco) agrupado por `modulo`\n- Serviços: `atualizarPermissoes(papelId, codigosAtivos)`, `togglePermissao(papelId, codigo, ativo)`\n- Banner persistente quando há mudanças não-aplicadas (autosave)"},{"title":"Layout","body":"- Header da página:\n  - Title: nome do papel + chip de tipo + Qtd. usuários + Qtd. permissões\n  - Botão \"Editar nome/descrição\" (abre `PapelDrawer`)\n- Banner âmbar no topo (sticky): \"Usuários deste papel precisarão fazer logout/login para aplicar as mudanças\" — visível sempre que há `dirty`\n- Matriz organizada por **módulos** (8 seções):\n  - Solicitações\n  - Pacientes\n  - Unidades de Saúde\n  - Regionais\n  - Regulação\n  - Financeiro\n  - Configurações\n  - Administrativo\n- Cada seção:\n  - Header com nome + 2 botões: \"Marcar todas\" / \"Desmarcar todas\"\n  - Lista de ações com checkboxes:\n    - Ex.: `pacientes.visualizar`, `pacientes.criar`, `pacientes.editar`, `pacientes.excluir`, `pacientes.dados_bancarios`"},{"title":"Critérios de aceite","body":"- [ ] Header do papel com nome + tipo + contadores\n- [ ] Banner âmbar persistente (autosave em ação): \"Permissão atualizada\" (toast discreto) + \"Usuários precisarão relogar\"\n- [ ] Cada checkbox marca/desmarca direto (sem botão \"Salvar global\")\n- [ ] **Autosave** com debounce de 500ms após o último click\n- [ ] Toast pequeno \"Permissão atualizada\" no canto inferior direito a cada save\n- [ ] Botão \"Marcar todas da seção\" → marca todos os checkboxes do módulo\n- [ ] Botão \"Desmarcar todas da seção\" → desmarca todos\n- [ ] Permissões inconsistentes (ex.: `criar` sem `visualizar`) mostram warning amarelo discreto ao lado: \"⚠ Sugestão: requer 'visualizar'\" — mas não bloqueia\n- [ ] Papel padrão Admin Master tem todas as permissões marcadas e desabilitadas (não pode mudar)\n- [ ] Loading: skeleton da matriz enquanto carrega permissões"},{"title":"Estados visuais","body":"- **Pristine**: checkboxes refletem estado salvo\n- **Salvando**: spinner pequeno ao lado do checkbox em transição\n- **Erro**: toast vermelho + checkbox volta ao estado anterior\n- **Admin Master**: todos os checkboxes verdes + readonly + texto \"Admin Master tem todas as permissões por padrão\""},{"title":"Side effects","body":"- Cada toggle dispara UPDATE em `papel_permissoes` (INSERT ou DELETE)\n- Log de auditoria por mudança (uma entrada por toggle)\n- Invalida cache de permissões dos usuários daquele papel (eles veem mudança após relogar)"},{"title":"Regras de negócio","body":"- Estrutura de permissões é **fixa no código** (definida pelos devs em `permissoes` seed) — admin só marca/desmarca, não cria novas\n- Mudanças refletem na próxima requisição autenticada do usuário (após cache TTL ou logout/login)\n- Permissões inválidas (ex.: criar sem visualizar) são **alertadas mas não bloqueadas** — admin decide\n- Admin Master é um papel especial — tem todas as permissões automaticamente, não pode ser alterado"},{"title":"Schema (banco)","body":"- INSERT em `papel_permissoes`: `{ papel_id, permissao_id }`\n- DELETE para remover\n- Trigger ou função SQL pode validar consistência (não bloqueante)"},{"title":"Permissões","body":"- `sys_papeis.editar`\n- `sys_papeis.gerenciar_admin_master` (só Admin Master pode editar outro Admin Master)"},{"title":"Auditoria","body":"- Log: `entity_type='papel_permissao'`, `action='grant'` / `action='revoke'`, com código da permissão"},{"title":"Dependências","body":"- US-PAP-01\n\n---"}],"criterios":["Header do papel com nome + tipo + contadores","Banner âmbar persistente (autosave em ação): \"Permissão atualizada\" (toast discreto) + \"Usuários precisarão relogar\"","Cada checkbox marca/desmarca direto (sem botão \"Salvar global\")","**Autosave** com debounce de 500ms após o último click","Toast pequeno \"Permissão atualizada\" no canto inferior direito a cada save","Botão \"Marcar todas da seção\" → marca todos os checkboxes do módulo","Botão \"Desmarcar todas da seção\" → desmarca todos","Permissões inconsistentes (ex.: `criar` sem `visualizar`) mostram warning amarelo discreto ao lado: \"⚠ Sugestão: requer 'visualizar'\" — mas não bloqueia","Papel padrão Admin Master tem todas as permissões marcadas e desabilitadas (não pode mudar)","Loading: skeleton da matriz enquanto carrega permissões"],"regras":["Estrutura de permissões é **fixa no código** (definida pelos devs em `permissoes` seed) — admin só marca/desmarca, não cria novas","Mudanças refletem na próxima requisição autenticada do usuário (após cache TTL ou logout/login)","Permissões inválidas (ex.: criar sem visualizar) são **alertadas mas não bloqueadas** — admin decide","Admin Master é um papel especial — tem todas as permissões automaticamente, não pode ser alterado"],"dependencias":["US-PAP-01","--"]},{"id":"US-PAP-04","title":"Excluir papel customizado","story":"**Como** Administrador, **Quero** excluir um papel customizado que não é mais usado, **Para que** a lista de papéis fique enxuta.","sections":[{"title":"Componentes do protótipo","body":"- Modal de confirmação\n- Serviço: `excluirPapel(id)` (verifica usuários vinculados primeiro)"},{"title":"Critérios de aceite","body":"- [ ] Lixeira só visível em papéis customizados\n- [ ] Click → modal \"Excluir papel?\" com nome em destaque\n- [ ] Modal verifica usuários vinculados:\n  - Se há usuários: mostra \"Há {N} usuários neste papel. Migre-os para outro papel antes de excluir.\" + lista resumida dos primeiros 5 + botão \"Excluir\" desabilitado + link \"Ver usuários deste papel\"\n  - Sem usuários: aviso simples \"Esta ação é permanente. As permissões associadas serão removidas.\"\n- [ ] Sem vinculados → confirma → spinner → modal fecha → toast \"Papel excluído\" → linha some\n- [ ] Erro: modal continua + toast vermelho"},{"title":"Estados visuais","body":"- **Com usuários**: botão Excluir disabled + lista de usuários\n- **Sem usuários**: botão Excluir vermelho ativo\n- **Excluindo**: spinner"},{"title":"Side effects","body":"- HARD DELETE em `papeis` + cascata DELETE em `papel_permissoes`\n- Log de auditoria com snapshot do papel e suas permissões"},{"title":"Regras de negócio","body":"- **Hard delete** (papel sai do banco) — diferente de outros casos que são soft delete\n- Justificativa: papel customizado não é referenciado em snapshots históricos (papéis em snapshots usam apenas o nome, não o id)\n- Papéis padrão não têm lixeira (ocultos da UI)\n- Não é possível excluir se há usuários vinculados (migrar primeiro)"},{"title":"Schema (banco)","body":"- DELETE em `papeis` com `tipo = 'customizado'`\n- Cascata em `papel_permissoes`"},{"title":"Permissões","body":"- `sys_papeis.excluir`"},{"title":"Auditoria","body":"- Log: `action='delete'`, snapshot do papel + permissões removidas"},{"title":"Dependências","body":"- US-PAP-01\n- US-USR-03 (para migrar usuários)"}],"criterios":["Lixeira só visível em papéis customizados","Click → modal \"Excluir papel?\" com nome em destaque","Modal verifica usuários vinculados:","Se há usuários: mostra \"Há {N} usuários neste papel. Migre-os para outro papel antes de excluir.\" + lista resumida dos primeiros 5 + botão \"Excluir\" desabilitado + link \"Ver usuários deste papel\"","Sem usuários: aviso simples \"Esta ação é permanente. As permissões associadas serão removidas.\"","Sem vinculados → confirma → spinner → modal fecha → toast \"Papel excluído\" → linha some","Erro: modal continua + toast vermelho"],"regras":["**Hard delete** (papel sai do banco) — diferente de outros casos que são soft delete","Justificativa: papel customizado não é referenciado em snapshots históricos (papéis em snapshots usam apenas o nome, não o id)","Papéis padrão não têm lixeira (ocultos da UI)","Não é possível excluir se há usuários vinculados (migrar primeiro)"],"dependencias":["US-PAP-01","US-USR-03 (para migrar usuários)"]},{"id":"US-PAP-05","title":"Catálogo `acoes_catalogo` para nomes humanos das ações","story":"**Como** Administrador, **Quero** ver nomes humanos legíveis (com descrição) ao configurar permissões, **Para que** eu não precise decifrar códigos snake_case na matriz de permissões.","sections":[{"title":"Componentes do protótipo","body":"- Migration: `supabase/migrations/00058_permissoes_remap_prototipo.sql` (cria a tabela de forma idempotente)\n- Tabela: `acoes_catalogo` com colunas `tela text`, `acao text`, `nome_humano text`, `descricao text`, `ordem int`\n- PK composta: `(tela, acao)`\n- Consumidor: `MatrizPermissoes` em `src/app/sistema/papeis/[id]/page.tsx` faz JOIN com `acoes_catalogo` para exibir nome humano + tooltip com descrição"},{"title":"Schema da tabela","body":"```sql\ncreate table if not exists public.acoes_catalogo (\n  tela text not null,\n  acao text not null,\n  nome_humano text not null,\n  descricao text,\n  ordem int not null default 0,\n  primary key (tela, acao)\n);\n```\n- Idempotente: a migration usa `create table if not exists` + `insert ... on conflict (tela, acao) do update set ...` para popular o catálogo"},{"title":"Critérios de aceite","body":"- [ ] Tabela `acoes_catalogo` criada com PK `(tela, acao)`\n- [ ] Toda permissão exibida na matriz (`MatrizPermissoes`) tem `nome_humano` legível (ex.: \"Gerenciar dados bancários\" em vez de `gerenciar_dados_bancarios`)\n- [ ] Tooltip ao passar o mouse mostra a `descricao` da ação\n- [ ] Ações ordenadas por `ordem` dentro de cada tela (módulo)\n- [ ] Migration é idempotente — roda múltiplas vezes sem erro"},{"title":"Componentes que leem da tabela","body":"- `src/app/sistema/papeis/[id]/page.tsx` (matriz de permissões)\n- `src/services/papeis.service.ts` (carregamento das ações disponíveis agrupadas por tela)\n- Componente `Can` (`src/shared/auth/Can.tsx`) continua usando o código `tela.acao` — apenas a apresentação ganha nome humano"},{"title":"Regras de negócio","body":"- O catálogo é fonte da verdade para **rotulagem** — não substitui o catálogo de permissões em si\n- Quando uma nova ação aparece no protótipo, ela deve ser adicionada à migration para receber `nome_humano + descricao`\n- Ordem padrão: visualizar (10) → criar (20) → editar (30) → excluir (40) → ações específicas (50+)"},{"title":"Dependências","body":"- US-PAP-03 (matriz de permissões)\n- Migration `00058_permissoes_remap_prototipo.sql`\n\n---"}],"criterios":["Tabela `acoes_catalogo` criada com PK composta `(tela, acao)` e colunas `nome_humano`, `descricao`, `ordem`","Matriz de permissões exibe `nome_humano` em vez do código snake_case","Tooltip ao passar o mouse mostra a `descricao` da ação","Ações ordenadas por `ordem` dentro de cada módulo/tela","Migration idempotente (roda múltiplas vezes sem erro)"],"regras":["Catálogo é fonte da verdade para **rotulagem** — não substitui o catálogo de permissões em si","Nova ação no protótipo precisa de entrada na migration para receber `nome_humano + descricao`","Convenção de ordem: visualizar (10) → criar (20) → editar (30) → excluir (40) → ações específicas (50+)"],"dependencias":["US-PAP-03","Migration `00058_permissoes_remap_prototipo.sql`","--"]},{"id":"US-PAP-06","title":"Remapeamento de ações refletindo todo o protótipo","story":"**Como** Administrador, **Quero** que a matriz de permissões reflita todas as ações reais do sistema (dados bancários, anexos por contexto, relatório de gestão, vínculos, etc.), **Para que** eu possa conceder acesso granular sem que ações fiquem invisíveis na matriz.","sections":[{"title":"Componentes do protótipo","body":"- Migration: `supabase/migrations/00058_permissoes_remap_prototipo.sql`\n- Cria 2 telas novas: `backlog` e `design_system` (módulo **Documentação**)\n- Adiciona ações em 14 telas existentes, refletindo o que o protótipo realmente faz\n- INSERT...SELECT garante que **Admin Master** recebe automaticamente todas as ações novas"},{"title":"Telas novas (módulo Documentação)","body":"- **`backlog`** — visualizar a árvore de backlog em `/backlog`\n- **`design_system`** — visualizar referência visual em `/design-system`"},{"title":"Ações adicionadas por tela","body":"- **pacientes**: `gerenciar_dados_bancarios`, `gerenciar_acompanhantes`, `exportar_prontuario`\n- **unidades_saude**: `inativar`, `ver_solicitacoes_vinculadas`\n- **regionais_saude**: `inativar`, `gerenciar_municipios`\n- **relatorios**: `exportar`, `imprimir`, `ver_financeiro`, `ver_faturamento`, `ver_bpa`, `ver_gestao`\n- **regulacao**: `emitir_parecer`, `editar_parecer`, `aplicar_carimbo`, `registrar_tentativa`, `registrar_agendamento`, `anexar`\n- **financeiro**: `registrar_passagem`, `editar_passagem`, `cancelar_passagem`, `reembolsar_passagem`, `registrar_ajuda_custo`, `editar_ajuda_custo`, `aprovar_ajuda_custo`, `registrar_adicional`, `selecionar_conta_bancaria`, `criar_conta_bancaria_inline`, `encaminhar_financeiro`, `anexar`\n- **solicitacoes**: `enviar_setor`, `encerrar`, `devolver_regulacao`, `reabrir`\n- **tramitacao**: `enviar_setor`, `encaminhar_financeiro`, `devolver_regulacao`, `marcar_resolvida`\n- **sys_configuracoes**: `gerenciar_tabelas_auxiliares`, `gerenciar_vinculo`, `gerenciar_bancos`\n- **sys_usuarios**: `ativar_desativar`"},{"title":"Critérios de aceite","body":"- [ ] Migration `00058_permissoes_remap_prototipo.sql` aplicada com sucesso\n- [ ] Matriz de permissões exibe as 2 telas novas (`backlog`, `design_system`) no módulo **Documentação**\n- [ ] Todas as ações listadas acima aparecem nas suas respectivas telas, com `nome_humano` legível (via `acoes_catalogo`)\n- [ ] Papel **Admin Master** tem todas as ações novas marcadas automaticamente (via INSERT...SELECT na migration)\n- [ ] Papéis customizados existentes não são afetados — admin precisa marcar as ações novas manualmente\n- [ ] Migration é idempotente: roda em ambiente que já tem o catálogo antigo sem duplicar nem perder permissões existentes"},{"title":"Regras de negócio","body":"- Admin Master recebe **toda** ação nova automaticamente (INSERT...SELECT em `papel_permissoes`)\n- Papéis customizados **não** são tocados — equipe administrativa precisa marcar as ações novas conscientemente\n- Cada ação nova segue convenção `tela.acao` (ex.: `pacientes.gerenciar_dados_bancarios`)\n- Anexos por contexto (`regulacao.anexar`, `financeiro.anexar`) são ações distintas por tela, não uma permissão global"},{"title":"Schema (banco)","body":"- INSERTs em `acoes_catalogo` para cada nova ação (`tela, acao, nome_humano, descricao, ordem`)\n- INSERT...SELECT em `papel_permissoes` para o papel Admin Master\n- `on conflict do nothing` em todos os INSERTs para idempotência"},{"title":"Dependências","body":"- US-PAP-05 (catálogo `acoes_catalogo`)\n- US-PAC-07 (dados bancários pool por paciente)\n- US-REL-04 (relatório de gestão)\n- US-UNI-06 / US-UNI-07 (vínculos com unidades)\n- US-DSN-02 (anexos por contexto)\n- Migration `00058_permissoes_remap_prototipo.sql`\n\n---"}],"criterios":["Migration `00058_permissoes_remap_prototipo.sql` aplicada — adiciona 2 telas novas (`backlog`, `design_system`) e ações em 14 telas existentes","Matriz exibe todas as ações novas com `nome_humano` via `acoes_catalogo`","Admin Master recebe todas as ações novas automaticamente (INSERT...SELECT)","Papéis customizados não são afetados — admin marca novas ações manualmente","Migration idempotente (não duplica nem perde permissões existentes)"],"regras":["Admin Master recebe toda ação nova automaticamente; papéis customizados precisam de marcação manual","Convenção `tela.acao` mantida (ex.: `pacientes.gerenciar_dados_bancarios`)","Anexos são ações distintas por contexto (`regulacao.anexar`, `financeiro.anexar`) — não há permissão global de anexos"],"dependencias":["US-PAP-05","US-PAC-07","US-REL-04","US-UNI-06","US-UNI-07","US-DSN-02","Migration `00058_permissoes_remap_prototipo.sql`","--"]}]},{"file":"F04-Logs-Auditoria","code":"F03","title":"Logs de Auditoria","description":"Tela de logs imutáveis de tudo que acontece no sistema. Filtros por usuário, ação, período e entidade. Cada entrada pode ser expandida para ver detalhes incluindo IP, agente, e diff (campo a campo) quando aplicável.","meta":[{"key":"Tela","value":"`/sistema/logs`"},{"key":"Drawer/Modal","value":"`LogDetailDrawer`"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/sistema/logs/page.tsx` · `src/app/sistema/logs/_LogDetailDrawer.tsx`"},{"key":"Serviço","value":"`src/services/audit-logs.service.ts`"},{"key":"Tabela","value":"`audit_logs` (insert-only, sem updates)"}],"userStories":[{"id":"US-LOG-01","title":"Listar logs","story":"**Como** Administrador ou Coordenação Estadual, **Quero** ver os eventos do sistema em ordem cronológica, **Para que** eu acompanhe o que aconteceu em qualquer registro.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/sistema/logs/page.tsx`\n- Componentes compartilhados habituais\n- `LogActionBadge` (badge colorido por tipo de ação)\n- Serviço: `listarLogs({ filters, page, pageSize })`"},{"title":"Layout","body":"- `PageHeader title=\"Logs de auditoria\" subtitle=\"Histórico imutável de ações no sistema\"`\n- Toolbar com filtros (US-LOG-02)\n- Tabela de logs"},{"title":"Cores dos badges de Ação","body":"| Ação                        | Cor        |\n|-----------------------------|------------|\n| Criar (`create`)            | verde      |\n| Editar (`update`)           | azul       |\n| Excluir (`delete`)          | vermelho   |\n| Tramitar (`send_to_*`)      | violeta    |\n| Devolver (`devolver`)       | laranja    |\n| Parecer (`parecer_*`)       | verde-azulado |\n| Login (`login_success/fail`)| cinza      |\n| Inativar (`deactivate`)     | cinza      |\n| Reativar (`reactivate`)     | verde      |"},{"title":"Critérios de aceite","body":"- [ ] Sidebar → \"Administrativo\" → \"Logs\" → `/sistema/logs`\n- [ ] Header + subtitle\n- [ ] Tabela com colunas: Data/Hora (mono, sortable) · Usuário (nome + email pequeno abaixo) · Perfil (badge cinza) · Ação (badge colorido) · Entidade (link clicável) · Descrição (truncate) · Detalhe (botão \"Ver\")\n- [ ] Ordenação default: `created_at` desc (mais recente em cima)\n- [ ] Paginação 50 por página (default maior porque logs são muitos): 25/50/100/200\n- [ ] Estado vazio após filtros: \"Nenhum log para os filtros aplicados\"\n- [ ] Estado vazio sem filtros (raro): \"Nenhum log registrado ainda\"\n- [ ] Hover na linha: destaque sutil cinza\n- [ ] Tooltip na entidade quando muito longa"},{"title":"Estados visuais","body":"- **Loading**: skeleton 8 linhas\n- **Empty**: ícone + mensagem\n- **Erro**: toast vermelho"},{"title":"Side effects","body":"- Click na entidade (link) → abre o registro relacionado em nova aba\n- Click em \"Ver\" → abre `LogDetailDrawer` (US-LOG-03)"},{"title":"Regras de negócio","body":"- Logs são **imutáveis** — não há editar nem excluir\n- Apenas Admin e Coordenação Estadual acessam\n- Cada ação no sistema (criar/editar/excluir registros, tramitação, parecer, login, mudança de papel) gera 1 entrada de log\n- Logs são append-only no banco (sem DELETE permitido)"},{"title":"Schema (banco)","body":"- Tabela `audit_logs`:\n  - `id` (uuid)\n  - `created_at` (timestamp, índice)\n  - `usuario_id` (FK, nullable se ação anônima/sistema)\n  - `usuario_nome` (snapshot)\n  - `usuario_perfil` (snapshot)\n  - `acao` (enum)\n  - `entidade_tipo` (string, ex.: `paciente`, `solicitacao`, `parecer`)\n  - `entidade_id` (uuid do registro afetado)\n  - `entidade_label` (string descritivo, ex.: \"TFD-N-2026/000131\")\n  - `descricao` (text resumido)\n  - `diff` (jsonb: `{ campo: { antes, depois } }`)\n  - `metadata` (jsonb: IP, user_agent, etc.)\n- Índices: `created_at DESC`, `usuario_id`, `entidade_tipo + entidade_id`, `acao`"},{"title":"Permissões","body":"- `sys_logs.visualizar` (Admin + Coord Estadual)"},{"title":"Dependências","body":"- [[F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]\n\n---"}],"criterios":["Sidebar → \"Administrativo\" → \"Logs\" → `/sistema/logs`","Header + subtitle","Tabela com colunas: Data/Hora (mono, sortable) · Usuário (nome + email pequeno abaixo) · Perfil (badge cinza) · Ação (badge colorido) · Entidade (link clicável) · Descrição (truncate) · Detalhe (botão \"Ver\")","Ordenação default: `created_at` desc (mais recente em cima)","Paginação 50 por página (default maior porque logs são muitos): 25/50/100/200","Estado vazio após filtros: \"Nenhum log para os filtros aplicados\"","Estado vazio sem filtros (raro): \"Nenhum log registrado ainda\"","Hover na linha: destaque sutil cinza","Tooltip na entidade quando muito longa"],"regras":["Logs são **imutáveis** — não há editar nem excluir","Apenas Admin e Coordenação Estadual acessam","Cada ação no sistema (criar/editar/excluir registros, tramitação, parecer, login, mudança de papel) gera 1 entrada de log","Logs são append-only no banco (sem DELETE permitido)"],"dependencias":["[[F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]","--"]},{"id":"US-LOG-02","title":"Filtrar por usuário, ação ou período","story":"**Como** Auditor, **Quero** filtrar logs por critérios específicos, **Para que** eu reconstrua o que aconteceu em um caso/data/usuário.","sections":[{"title":"Componentes do protótipo","body":"- Toolbar com 5 filtros + busca livre\n- DateRangePicker (componente compartilhado a criar ou usar `react-day-picker`)\n- AutocompleteUsuario (consulta `usuarios.service`)\n- Chips de filtros ativos acima da tabela"},{"title":"Layout dos filtros","body":"- Toolbar horizontal:\n  - Autocomplete \"Usuário...\" (busca por nome/email)\n  - Multi-select \"Tipo de ação\" (Criar/Editar/Excluir/Tramitar/Parecer/Login/Outros)\n  - DateRangePicker \"Período\" (de / até)\n  - Select \"Entidade\" (Solicitação/Paciente/Usuário/Unidade/Regional/Papel/Parecer/...)\n  - Campo \"Texto livre\" (busca em descrição)\n- Botão \"Limpar filtros\" à direita\n- Linha abaixo: chips dos filtros ativos com X para remover individualmente"},{"title":"Critérios de aceite","body":"- [ ] Filtro de usuário: autocomplete com lista de usuários (busca por nome ou email)\n- [ ] Filtro de ação: multi-select (checkboxes) com tipos coloridos\n- [ ] Filtro de período: date range picker (de / até), default últimos 7 dias\n- [ ] Filtro de entidade: select com tipos do sistema\n- [ ] Filtro de texto livre: busca em `descricao` e `entidade_label` (debounce 300ms)\n- [ ] Botão \"Limpar filtros\" reseta tudo para default\n- [ ] Filtros combinam com AND lógico\n- [ ] Tabela atualiza ao aplicar filtro (debounce 300ms para texto, imediato para selects/datas)\n- [ ] Chips dos filtros ativos visíveis acima da tabela; click no X remove individualmente\n- [ ] Mudar filtro reseta paginação para página 1"},{"title":"Estados visuais","body":"- **Filtros ativos**: chips visíveis\n- **Sem filtros**: chips área vazia"},{"title":"Regras de negócio","body":"- Período máximo de consulta: **90 dias** (query muito pesada além disso)\n- Para períodos maiores, exportar via Relatório (fora deste escopo, EPIC-07)\n- Texto livre busca em `descricao` e `entidade_label` com ILIKE\n- Combinações de filtros sempre AND"},{"title":"Schema (banco)","body":"- Query usa índices em `created_at` e `usuario_id`\n- Filter por entidade: `eq('entidade_tipo', X)`\n- Filter por período: `gte('created_at', from) + lte('created_at', to)`\n- Filter por texto: `or('descricao.ilike.%X%, entidade_label.ilike.%X%')`"},{"title":"Permissões","body":"- Mesma da listagem (`sys_logs.visualizar`)"},{"title":"Dependências","body":"- US-LOG-01\n\n---"}],"criterios":["Filtro de usuário: autocomplete com lista de usuários (busca por nome ou email)","Filtro de ação: multi-select (checkboxes) com tipos coloridos","Filtro de período: date range picker (de / até), default últimos 7 dias","Filtro de entidade: select com tipos do sistema","Filtro de texto livre: busca em `descricao` e `entidade_label` (debounce 300ms)","Botão \"Limpar filtros\" reseta tudo para default","Filtros combinam com AND lógico","Tabela atualiza ao aplicar filtro (debounce 300ms para texto, imediato para selects/datas)","Chips dos filtros ativos visíveis acima da tabela; click no X remove individualmente","Mudar filtro reseta paginação para página 1"],"regras":["Período máximo de consulta: **90 dias** (query muito pesada além disso)","Para períodos maiores, exportar via Relatório (fora deste escopo, EPIC-07)","Texto livre busca em `descricao` e `entidade_label` com ILIKE","Combinações de filtros sempre AND"],"dependencias":["US-LOG-01","--"]},{"id":"US-LOG-03","title":"Visualizar detalhe com antes/depois","story":"**Como** Auditor, **Quero** abrir o detalhe de um log de edição e ver o que mudou, **Para que** eu entenda exatamente o que foi alterado.","sections":[{"title":"Componentes do protótipo","body":"- Drawer/Modal: `LogDetailDrawer` (largura 560px)\n- Componente `DiffTable` (tabela campo / antes / depois)\n- Serviço: `buscarLog(id)`"},{"title":"Layout do drawer","body":"- Title: \"Log #{id curto}\"\n- Subtitle: data/hora completa\n- Seções:\n  1. **Quem**: usuário (nome + email + papel + chip do perfil) + IP + agente do navegador\n  2. **O que**: ação (badge) + entidade afetada (link clicável → abre registro)\n  3. **Detalhes**: campo `descricao` (texto livre)\n  4. **Diff** (quando `acao = 'update'`): tabela `Campo / Valor anterior / Valor novo`\n  5. **Snapshot completo** (quando `acao = 'create'` ou `'delete'`): JSON formatado ou tabela de campos\n  6. **Tramitação** (quando `acao = 'send_to_*'` ou `'devolver'`): origem → destino + observação completa"},{"title":"Critérios de aceite","body":"- [ ] Click em \"Ver\" na coluna Detalhe → drawer/modal abre\n- [ ] Title com ID curto do log (primeiros 8 chars do UUID)\n- [ ] Subtitle: data/hora completa formatada `dd/mm/aaaa às HH:MM:SS`\n- [ ] Seção \"Quem\": avatar do usuário + nome + email + chip do perfil + IP + agente (truncado, tooltip completo)\n- [ ] Seção \"O que\": badge colorido da ação + ícone + nome legível da entidade (link)\n- [ ] Click no link da entidade → abre o registro em nova aba (ex.: `/pacientes/{id}`)\n- [ ] Seção \"Detalhes\" mostra a descrição em texto rico (suporta quebras de linha)\n- [ ] **Diff** (apenas em edição):\n  - Tabela com 3 colunas: Campo / Antes / Depois\n  - Campos sem mudança não aparecem\n  - Valores formatados (datas DD/MM/AAAA, valores monetários R$, etc.)\n  - Strings longas truncadas com tooltip\n- [ ] **Snapshot** (criação): todos os campos do registro no momento da criação (tabela compacta key-value)\n- [ ] **Snapshot** (exclusão): todos os campos do registro no momento da exclusão + mensagem em vermelho \"Registro excluído\"\n- [ ] **Tramitação**: card visual com origem → seta → destino + observação completa\n- [ ] **Parecer**: mostra decisão e observação resumida + link \"Ver parecer completo\" → abre `/parecer/{id}`\n- [ ] **Login**: mostra apenas timestamp + IP + sucesso/falha (sem diff)\n- [ ] Botão \"Fechar\" no rodapé"},{"title":"Estados visuais","body":"- Loading do drawer: spinner central\n- Erro de fetch: mensagem \"Log não encontrado\""},{"title":"Regras de negócio","body":"- Sistema armazena diff (antes/depois) por campo quando a ação é Editar (entrada `diff` no banco já tem o JSON)\n- Logs de criação não têm \"valor anterior\" — só valores criados\n- Logs de exclusão mostram snapshot completo no momento da exclusão (para auditoria de recuperação)\n- Logs de tramitação mostram origem + destino + observação\n- Logs de login não têm campos alterados — só timestamp + IP + sucesso/falha\n- Logs de Parecer mostram decisão e observação resumida; link abre o parecer completo\n- Snapshot completo é grande — UI usa accordion ou tabela colapsável"},{"title":"Schema (banco)","body":"- SELECT em `audit_logs` por id\n- Campo `diff` (jsonb) já estruturado para renderização\n- Campo `metadata` (jsonb) contém IP, user_agent"},{"title":"Permissões","body":"- `sys_logs.visualizar`"},{"title":"Acessibilidade","body":"- Drawer com `role=\"dialog\"`, `aria-modal`, foco trap, Esc fecha"},{"title":"Dependências","body":"- US-LOG-01"}],"criterios":["Click em \"Ver\" na coluna Detalhe → drawer/modal abre","Title com ID curto do log (primeiros 8 chars do UUID)","Subtitle: data/hora completa formatada `dd/mm/aaaa às HH:MM:SS`","Seção \"Quem\": avatar do usuário + nome + email + chip do perfil + IP + agente (truncado, tooltip completo)","Seção \"O que\": badge colorido da ação + ícone + nome legível da entidade (link)","Click no link da entidade → abre o registro em nova aba (ex.: `/pacientes/{id}`)","Seção \"Detalhes\" mostra a descrição em texto rico (suporta quebras de linha)","**Diff** (apenas em edição):","Tabela com 3 colunas: Campo / Antes / Depois","Campos sem mudança não aparecem","Valores formatados (datas DD/MM/AAAA, valores monetários R$, etc.)","Strings longas truncadas com tooltip","**Snapshot** (criação): todos os campos do registro no momento da criação (tabela compacta key-value)","**Snapshot** (exclusão): todos os campos do registro no momento da exclusão + mensagem em vermelho \"Registro excluído\"","**Tramitação**: card visual com origem → seta → destino + observação completa","**Parecer**: mostra decisão e observação resumida + link \"Ver parecer completo\" → abre `/parecer/{id}`","**Login**: mostra apenas timestamp + IP + sucesso/falha (sem diff)","Botão \"Fechar\" no rodapé"],"regras":["Sistema armazena diff (antes/depois) por campo quando a ação é Editar (entrada `diff` no banco já tem o JSON)","Logs de criação não têm \"valor anterior\" — só valores criados","Logs de exclusão mostram snapshot completo no momento da exclusão (para auditoria de recuperação)","Logs de tramitação mostram origem + destino + observação","Logs de login não têm campos alterados — só timestamp + IP + sucesso/falha","Logs de Parecer mostram decisão e observação resumida; link abre o parecer completo","Snapshot completo é grande — UI usa accordion ou tabela colapsável"],"dependencias":["US-LOG-01"]}]}]},{"folder":"EPIC-02-Cadastros-Base","code":"EPIC-02","title":"Cadastros Base (Unidades, Regionais, Tabelas Auxiliares)","pendente":false,"features":[{"file":"F02-Unidades-Saude","code":"F01","title":"Unidades de Saúde","description":"Cadastro das unidades de saúde de destino (hospitais, ambulatórios, clínicas) onde os pacientes serão atendidos. CNES é o identificador único nacional e o sistema oferece auto-preenchimento de campos a partir dele.","meta":[{"key":"Tela","value":"`/unidades-saude` (listagem) · `/unidades-saude/[id]` (detalhe)"},{"key":"Drawer","value":"`UnidadeDrawer` (cadastro/edição)"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/unidades-saude/page.tsx` · `src/app/unidades-saude/_UnidadeDrawer.tsx` · `src/app/unidades-saude/[id]/page.tsx`"},{"key":"Serviço","value":"`src/services/unidades-saude.service.ts`"},{"key":"Tabela","value":"`unidades_saude`"}],"userStories":[{"id":"US-UNI-01","title":"Listar unidades de saúde","story":"**Como** Atendente TFD, Regulação ou Coordenação, **Quero** ver todas as unidades de saúde em uma tabela, **Para que** eu encontre rapidamente uma unidade para vincular em tentativas de agendamento ou consultas.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/unidades-saude/page.tsx`\n- Sidebar: item \"Unidades de Saúde\" (ícone `Building2`, grupo CADASTROS)\n- Mesmos componentes compartilhados de F01 (`PageHeader`, `StatsRow`, `SortableHeader`, `Pagination`, `Skeleton`, `tfd-table`)\n- Serviço: `listarUnidadesSaude({ search, ativa, page, pageSize })`"},{"title":"Layout","body":"- `PageHeader title=\"Unidades de Saúde\" subtitle=\"Gerenciamento de unidades de saúde de destino TFD\"`\n- Action: botão \"+ Nova Unidade\" (`tfd-btn-primary`, Plus 16px), envolto em `<Can action=\"unidades_saude.criar\">`\n- `StatsRow` com 2 cards: Total de Unidades, Unidades Ativas\n- Toolbar: caixa de busca branca (mesmo padrão de F01)"},{"title":"Critérios de aceite","body":"- [ ] Sidebar → \"Unidades de Saúde\" → navega para `/unidades-saude`\n- [ ] Header com title/subtitle conforme acima\n- [ ] Botão \"+ Nova Unidade\" só para `unidades_saude.criar`\n- [ ] Campo de busca placeholder \"Buscar por nome ou CNES...\" (debounce 300ms)\n- [ ] Tabela com colunas: Nome (sortable) · CNES (sortable, `hidden md:table-cell`, mono) · Tipo (sortable + filtrável por checkbox, `hidden lg:table-cell`) · Município (sortable, `hidden xl:table-cell`) · Telefone (`hidden md:table-cell`) · Ações (largura 100px)\n- [ ] Linha clicável → navega para `/unidades-saude/[id]`\n- [ ] Ícones na coluna Ações: `Pencil` (editar) e `Trash2` (inativar) — só visíveis se permitido\n- [ ] Paginação 25 por página (10/25/50/100)\n- [ ] Estado vazio: `XCircle 32px` + \"Nenhuma unidade encontrada\"\n- [ ] Skeleton 6 linhas durante carga"},{"title":"Estados visuais","body":"- **Loading**: skeleton\n- **Empty**: ícone + texto\n- **Erro**: toast vermelho"},{"title":"Side effects","body":"- Mudança de filtro/busca reseta página para 1\n- Refetch após cada criar/editar/inativar"},{"title":"Regras de negócio","body":"- Lista todas as unidades ativas por default (filtro `ativa = true`)\n- CNES é o Cadastro Nacional de Estabelecimentos de Saúde (7 dígitos)\n- Busca cobre `nome` e `cnes`\n- Filtro por Tipo: usa lookup `tipo_unidade` (Hospital, Ambulatório, Clínica, etc.)\n- Ordenação default: `nome` asc\n- Perfis com `unidades_saude.visualizar` acessam"},{"title":"Schema (banco)","body":"- Tabela `unidades_saude`: `id`, `nome`, `cnes` (UNIQUE), `tipo`, `cep`, `logradouro`, `numero`, `bairro`, `municipio`, `uf`, `telefone`, `email`, `responsavel`, `ativa`, `created_at`, `updated_at`\n- Constraint UNIQUE em `cnes`"},{"title":"Permissões","body":"- `unidades_saude.visualizar` — acessar tela\n- `unidades_saude.criar`, `unidades_saude.editar`, `unidades_saude.excluir`"},{"title":"Dependências","body":"- [[../EPIC-04-Configuracoes-Administrativo/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]\n\n---"}],"criterios":["Sidebar → \"Unidades de Saúde\" → navega para `/unidades-saude`","Header com title/subtitle conforme acima","Botão \"+ Nova Unidade\" só para `unidades_saude.criar`","Campo de busca placeholder \"Buscar por nome ou CNES...\" (debounce 300ms)","Tabela com colunas: Nome (sortable) · CNES (sortable, `hidden md:table-cell`, mono) · Tipo (sortable + filtrável por checkbox, `hidden lg:table-cell`) · Município (sortable, `hidden xl:table-cell`) · Telefone (`hidden md:table-cell`) · Ações (largura 100px)","Linha clicável → navega para `/unidades-saude/[id]`","Ícones na coluna Ações: `Pencil` (editar) e `Trash2` (inativar) — só visíveis se permitido","Paginação 25 por página (10/25/50/100)","Estado vazio: `XCircle 32px` + \"Nenhuma unidade encontrada\"","Skeleton 6 linhas durante carga"],"regras":["Lista todas as unidades ativas por default (filtro `ativa = true`)","CNES é o Cadastro Nacional de Estabelecimentos de Saúde (7 dígitos)","Busca cobre `nome` e `cnes`","Filtro por Tipo: usa lookup `tipo_unidade` (Hospital, Ambulatório, Clínica, etc.)","Ordenação default: `nome` asc","Perfis com `unidades_saude.visualizar` acessam"],"dependencias":["[[../EPIC-04-Configuracoes-Administrativo/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]","--"]},{"id":"US-UNI-02","title":"Cadastrar nova unidade","story":"**Como** Coordenação Estadual ou Administrador, **Quero** cadastrar uma nova unidade de saúde de destino, **Para que** o TFD possa direcionar pacientes para ela.","sections":[{"title":"Componentes do protótipo","body":"- Drawer: `src/app/unidades-saude/_UnidadeDrawer.tsx` (largura 640px)\n- Auto-preenchimento por CNES: hook `useCnesAutofill` (consulta API de CNES nacional)\n- LookupSelect categoria `tipo_unidade`\n- Componente `CepAutofill` (igual ao usado em pacientes)\n- Serviço: `criarUnidadeSaude(InsertDTO)` em `unidades-saude.service.ts`"},{"title":"Layout do drawer","body":"- Title: \"Nova Unidade\" + subtitle \"Preencha os dados para cadastrar\"\n- 3 seções:\n  1. **Dados da Unidade** (Nome + CNES + Tipo)\n  2. **Endereço** (CEP + Logradouro + Número + Bairro + Município + UF)\n  3. **Contato** (Telefone + E-mail + Responsável)\n- Footer: \"Cancelar\" + \"Cadastrar Unidade\""},{"title":"Campos do formulário","body":"| Campo       | Tipo         | Obrig. | Validação                          | Mensagem                                                        |\n|-------------|--------------|--------|------------------------------------|-----------------------------------------------------------------|\n| Nome        | text         | sim    | ≥ 3 caracteres                     | \"Informe o nome da unidade\"                                     |\n| CNES        | text         | sim    | 7 dígitos numéricos + único        | \"CNES inválido\" / \"CNES já cadastrado em outra unidade\"         |\n| Tipo        | LookupSelect | não    | item de `tipo_unidade`             | —                                                                |\n| CEP         | text         | não    | 8 dígitos; auto-preenche endereço  | \"CEP não encontrado\" (silenciosa)                               |\n| Logradouro  | text         | não    | —                                  | —                                                                |\n| Número      | text         | não    | —                                  | —                                                                |\n| Bairro      | text         | não    | —                                  | —                                                                |\n| Município   | text         | sim    | autocomplete IBGE                  | \"Selecione o município\"                                         |\n| UF          | text         | sim    | autocomplete UF (default MA)       | —                                                                |\n| Telefone    | tel          | não    | máscara `(XX) XXXXX-XXXX`          | —                                                                |\n| E-mail      | email        | não    | formato válido                     | \"E-mail inválido\"                                               |\n| Responsável | text         | não    | livre                              | —                                                                |"},{"title":"Critérios de aceite","body":"- [ ] Click \"+ Nova Unidade\" → drawer abre da direita, 640px\n- [ ] Foco inicial no campo Nome\n- [ ] CNES: ao digitar 7 dígitos, ícone de spinner aparece + sistema consulta API CNES nacional\n- [ ] CNES válido + dados encontrados → preenche automaticamente Nome, Tipo, Endereço, Telefone (campos ficam editáveis)\n- [ ] CNES com dígitos inválidos → erro inline \"CNES inválido\" + botão Salvar disabled\n- [ ] CNES já existente na base → erro inline \"CNES já cadastrado em outra unidade\"\n- [ ] Texto auxiliar abaixo do CNES quando não editando: \"Ao digitar 7 dígitos, os dados serão preenchidos automaticamente.\"\n- [ ] CEP completo (8 dígitos) → spinner + preenche logradouro/bairro/município/UF\n- [ ] Submit com obrigatórios em branco → erros inline + toast vermelho\n- [ ] \"Cadastrar Unidade\" → spinner + drawer fecha → toast \"Unidade cadastrada — {nome}\" → tabela recarrega\n- [ ] \"Cancelar\" com mudanças → modal \"Descartar alterações?\""},{"title":"Estados visuais","body":"- **CNES loading**: spinner pequeno absoluto à direita do input\n- **CNES inválido/duplicado**: borda vermelha + texto vermelho abaixo\n- **Saving**: botão spinner + inputs disabled"},{"title":"Side effects","body":"- INSERT em `unidades_saude` com `ativa = true`\n- Log em `audit_logs` (action: `create`)"},{"title":"Regras de negócio","body":"- CNES é único globalmente (constraint)\n- Nova unidade entra ativa por default\n- Tipo vem da tabela auxiliar `tipo_unidade` (configurável em /sistema/configuracoes)\n- UF default \"MA\" (facilita cadastro local; outras UFs também permitidas)\n- Perfis com `unidades_saude.criar` veem o botão"},{"title":"Schema (banco)","body":"- INSERT em `unidades_saude`\n- FK opcional: `tipo` referencia código de `tabelas_auxiliares` categoria `tipo_unidade`\n- Constraint UNIQUE em `cnes`"},{"title":"Permissões","body":"- `unidades_saude.criar`"},{"title":"Auditoria","body":"- Log: `entity_type='unidade_saude'`, `action='create'`, snapshot do registro"},{"title":"Acessibilidade","body":"- Drawer com `role=\"dialog\"`, `aria-modal=\"true\"`, `aria-labelledby`\n- Foco trap; Esc fecha"},{"title":"Dependências","body":"- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (categoria `tipo_unidade`)\n- API externa de CNES (mock no protótipo)\n\n---"}],"criterios":["Click \"+ Nova Unidade\" → drawer abre da direita, 640px","Foco inicial no campo Nome","CNES: ao digitar 7 dígitos, ícone de spinner aparece + sistema consulta API CNES nacional","CNES válido + dados encontrados → preenche automaticamente Nome, Tipo, Endereço, Telefone (campos ficam editáveis)","CNES com dígitos inválidos → erro inline \"CNES inválido\" + botão Salvar disabled","CNES já existente na base → erro inline \"CNES já cadastrado em outra unidade\"","Texto auxiliar abaixo do CNES quando não editando: \"Ao digitar 7 dígitos, os dados serão preenchidos automaticamente.\"","CEP completo (8 dígitos) → spinner + preenche logradouro/bairro/município/UF","Submit com obrigatórios em branco → erros inline + toast vermelho","\"Cadastrar Unidade\" → spinner + drawer fecha → toast \"Unidade cadastrada — {nome}\" → tabela recarrega","\"Cancelar\" com mudanças → modal \"Descartar alterações?\""],"regras":["CNES é único globalmente (constraint)","Nova unidade entra ativa por default","Tipo vem da tabela auxiliar `tipo_unidade` (configurável em /sistema/configuracoes)","UF default \"MA\" (facilita cadastro local; outras UFs também permitidas)","Perfis com `unidades_saude.criar` veem o botão"],"dependencias":["[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (categoria `tipo_unidade`)","API externa de CNES (mock no protótipo)","--"]},{"id":"US-UNI-03","title":"Editar unidade existente","story":"**Como** Coordenação Estadual ou Administrador, **Quero** atualizar dados de uma unidade já cadastrada, **Para que** mantenha as informações em dia (endereço, telefone, responsável).","sections":[{"title":"Componentes do protótipo","body":"- Mesmo drawer da US-UNI-02 em modo \"Editar\"\n- Serviço: `atualizarUnidadeSaude(id, UpdateDTO)`"},{"title":"Layout","body":"- Igual ao drawer de cadastro, com:\n  - Title: \"Editar Unidade\"\n  - Subtitle: \"Atualize os dados da unidade\"\n  - Campos preenchidos com valores atuais\n  - CNES é **editável** (diferente do CPF do paciente) — mas mudar para um CNES existente em outra unidade bloqueia\n  - Botão final: \"Salvar Alterações\""},{"title":"Critérios de aceite","body":"- [ ] Click no lápis → drawer abre em modo edição\n- [ ] Todos os campos preenchidos com valores atuais\n- [ ] CNES editável; ao mudar e digitar 7 dígitos, valida duplicidade\n- [ ] CNES duplicado em outra unidade → erro inline + botão disabled\n- [ ] Botão \"Salvar Alterações\" começa disabled (até houver mudança)\n- [ ] Qualquer alteração habilita o botão\n- [ ] Save → spinner → drawer fecha → toast \"Unidade atualizada\" → linha atualiza\n- [ ] Cancel com mudanças → modal de confirmação"},{"title":"Estados visuais","body":"- **Pristine / Dirty / Saving / Erro**: idem F01-US-PAC-03"},{"title":"Side effects","body":"- UPDATE em `unidades_saude`\n- Log em `audit_logs` com diff campo a campo"},{"title":"Regras de negócio","body":"- Alterações geram log de auditoria detalhado\n- Perfis com `unidades_saude.editar` veem o lápis"},{"title":"Schema (banco)","body":"- UPDATE em `unidades_saude`\n- `updated_at` atualizado por trigger"},{"title":"Permissões","body":"- `unidades_saude.editar`"},{"title":"Auditoria","body":"- Log: `entity_type='unidade_saude'`, `action='update'`, diff por campo"},{"title":"Dependências","body":"- US-UNI-02\n\n---"}],"criterios":["Click no lápis → drawer abre em modo edição","Todos os campos preenchidos com valores atuais","CNES editável; ao mudar e digitar 7 dígitos, valida duplicidade","CNES duplicado em outra unidade → erro inline + botão disabled","Botão \"Salvar Alterações\" começa disabled (até houver mudança)","Qualquer alteração habilita o botão","Save → spinner → drawer fecha → toast \"Unidade atualizada\" → linha atualiza","Cancel com mudanças → modal de confirmação"],"regras":["Alterações geram log de auditoria detalhado","Perfis com `unidades_saude.editar` veem o lápis"],"dependencias":["US-UNI-02","--"]},{"id":"US-UNI-04","title":"Ver detalhe da unidade","story":"**Como** qualquer usuário autorizado, **Quero** abrir uma tela com todos os dados da unidade e seu histórico de uso, **Para que** eu tenha contexto antes de tentar agendar um paciente lá.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/unidades-saude/[id]/page.tsx`\n- `Section` reutilizável (similar à do detalhe do paciente)\n- Serviços: `buscarUnidadeSaude(id)`, `listarTentativasPorUnidade(id)`"},{"title":"Layout (sections empilhadas)","body":"1. Header: Nome + CNES + UF + botões \"Voltar\" e \"Editar\"\n2. **Dados da Unidade** (`Building2`): Nome, CNES, Tipo\n3. **Endereço** (`MapPin`): CEP, Logradouro, Número, Bairro, Município, UF\n4. **Contato** (`Phone`): Telefone, E-mail, Responsável\n5. **Histórico de Tentativas** (`History`): lista das tentativas de agendamento envolvendo essa unidade"},{"title":"Critérios de aceite","body":"- [ ] Click no nome da unidade → `/unidades-saude/[id]`\n- [ ] Header com nome (16px, 600) + CNES (mono 12px) abaixo + chip de status (Ativa/Inativa)\n- [ ] Botão \"Voltar\" respeita `?from=`\n- [ ] Botão \"Editar\" abre drawer da US-UNI-03 (desabilitado para perfis sem permissão)\n- [ ] Card \"Endereço\" formata: \"{logradouro}, {número} — {bairro}\\n{município}/{uf} — CEP {cep}\"\n- [ ] Card \"Histórico de Tentativas\" lista até 50 entradas mais recentes: data, número da solicitação (link), desfecho (badge)\n- [ ] Estado vazio Histórico: \"Esta unidade ainda não foi acionada em nenhuma tentativa.\""},{"title":"Estados visuais","body":"- Loading: skeletons em cada section\n- Não encontrado: mensagem + botão Voltar"},{"title":"Side effects","body":"- Navegação propaga `?from=unidades_saude`"},{"title":"Regras de negócio","body":"- Detalhe é read-only (edição via drawer)\n- Histórico inclui tentativas de qualquer desfecho (pendente, agendamento_confirmado, negou, etc.)\n- Unidade inativa tem chip cinza + badge \"Inativa\" no header"},{"title":"Schema (banco)","body":"- `select('*').eq('id', id).single()` em `unidades_saude`\n- `select('*').eq('unidade_id', id)` em `tentativas_agendamento`"},{"title":"Permissões","body":"- `unidades_saude.visualizar`"},{"title":"Dependências","body":"- US-UNI-01\n\n---"}],"criterios":["Click no nome da unidade → `/unidades-saude/[id]`","Header com nome (16px, 600) + CNES (mono 12px) abaixo + chip de status (Ativa/Inativa)","Botão \"Voltar\" respeita `?from=`","Botão \"Editar\" abre drawer da US-UNI-03 (desabilitado para perfis sem permissão)","Card \"Endereço\" formata: \"{logradouro}, {número} — {bairro}\\n{município}/{uf} — CEP {cep}\"","Card \"Histórico de Tentativas\" lista até 50 entradas mais recentes: data, número da solicitação (link), desfecho (badge)","Estado vazio Histórico: \"Esta unidade ainda não foi acionada em nenhuma tentativa.\""],"regras":["Detalhe é read-only (edição via drawer)","Histórico inclui tentativas de qualquer desfecho (pendente, agendamento_confirmado, negou, etc.)","Unidade inativa tem chip cinza + badge \"Inativa\" no header"],"dependencias":["US-UNI-01","--"]},{"id":"US-UNI-05","title":"Inativar / reativar unidade","story":"**Como** Coordenação Estadual ou Administrador, **Quero** inativar uma unidade que não está mais ativa para receber pacientes, **Para que** ela não apareça mais em selects/autocompletes.","sections":[{"title":"Componentes do protótipo","body":"- Modal de confirmação (componente compartilhado)\n- Serviço: `toggleAtivoUnidade(id, ativa)` em `unidades-saude.service.ts`"},{"title":"Layout","body":"- **Modal \"Inativar unidade?\"**:\n  - Body: nome da unidade em negrito + texto \"A unidade não poderá ser usada em novas tentativas. Tentativas e agendamentos antigos permanecem intactos.\"\n  - Footer: \"Cancelar\" + \"Inativar\" (vermelho)\n- Linhas de unidades inativas: ícone de lixeira é substituído pelo ícone `RotateCcw` (reativar)"},{"title":"Critérios de aceite","body":"- [ ] Click no `Trash2` → modal abre\n- [ ] Modal mostra nome da unidade em destaque\n- [ ] \"Inativar\" (vermelho) → spinner → modal fecha → toast \"Unidade inativada\"\n- [ ] Linha some da tabela (se filtro = Ativas) ou muda chip para \"Inativa\" (se filtro = Todas)\n- [ ] Click no `RotateCcw` em linha inativa → reativa direto sem modal → toast \"Unidade reativada\"\n- [ ] \"Cancelar\" / Esc → modal fecha sem ação"},{"title":"Estados visuais","body":"- **Inativando**: spinner no botão\n- **Erro**: toast vermelho"},{"title":"Side effects","body":"- UPDATE em `unidades_saude`: `set ativa = false` (ou `true` para reativar)\n- Log de auditoria"},{"title":"Regras de negócio","body":"- **Não é hard delete** — apenas toggle do campo `ativa`\n- Unidade inativa não aparece em autocompletes de \"Nova Tentativa\" nem \"Selecionar unidade\" no drawer de solicitação\n- Tentativas antigas que apontam para unidade inativa permanecem intactas (snapshot do nome no momento)\n- Unidade pode ser reativada a qualquer momento sem perda de histórico\n- Perfis com `unidades_saude.excluir` veem o botão"},{"title":"Schema (banco)","body":"- UPDATE em `unidades_saude`: `set ativa = X, updated_at = now()`"},{"title":"Permissões","body":"- `unidades_saude.excluir` (apesar do nome, usa para inativar)"},{"title":"Auditoria","body":"- Log: `entity_type='unidade_saude'`, `action='deactivate'` ou `action='reactivate'`"},{"title":"Dependências","body":"- US-UNI-01"}],"criterios":["Click no `Trash2` → modal abre","Modal mostra nome da unidade em destaque","\"Inativar\" (vermelho) → spinner → modal fecha → toast \"Unidade inativada\"","Linha some da tabela (se filtro = Ativas) ou muda chip para \"Inativa\" (se filtro = Todas)","Click no `RotateCcw` em linha inativa → reativa direto sem modal → toast \"Unidade reativada\"","\"Cancelar\" / Esc → modal fecha sem ação"],"regras":["**Não é hard delete** — apenas toggle do campo `ativa`","Unidade inativa não aparece em autocompletes de \"Nova Tentativa\" nem \"Selecionar unidade\" no drawer de solicitação","Tentativas antigas que apontam para unidade inativa permanecem intactas (snapshot do nome no momento)","Unidade pode ser reativada a qualquer momento sem perda de histórico","Perfis com `unidades_saude.excluir` veem o botão"],"dependencias":["US-UNI-01"]},{"id":"US-UNI-06","title":"Listar solicitações vinculadas à unidade (origem do laudo + destino de agendamento)","story":"**Como** Atendente TFD, Regulação ou Coordenação, **Quero** ver na tela de detalhe da unidade todas as solicitações vinculadas a ela — tanto as que tiveram o laudo emitido nesta unidade quanto as que foram agendadas para esta unidade — **Para que** eu entenda o uso real da unidade nos dois papéis e possa apoiar relatórios e tomada de decisão.","criterios":["A tela `/unidades-saude/[id]` lista todas as solicitações em que a unidade aparece como origem do laudo (`solicitacoes.origem_laudo_unidade_id`) e/ou como destino do agendamento (`agendamentos.unidade_destino_id`).","Solicitações que estão vinculadas pelos dois caminhos aparecem uma única vez na lista (deduplicadas) trazendo os dois vínculos consolidados.","O service retorna `{ solicitacao, vinculos: VinculoSolicitacaoUnidade[] }` com vínculos do tipo `origem_laudo` e/ou `destino_agendamento`.","Cada card/linha exibe os badges correspondentes (ver US-UNI-07) e o status da solicitação.","KpiBar no topo mostra 5 colunas em UMA única linha (sem quebra em telas estreitas): Total de Solicitações · Origem do Laudo · Destino Agendamento · Em Andamento · Concluídas."],"regras":["A busca é feita em paralelo nas duas pontas (laudo de origem e agendamento de destino) e os resultados são deduplicados por `solicitacao_id`.","Quando a mesma unidade é simultaneamente origem do laudo E destino do agendamento da mesma solicitação, o vínculo agregado contém os dois tipos.","Os KPIs \"Origem do Laudo\" e \"Destino Agendamento\" contam vínculos (não solicitações), portanto uma solicitação com os dois papéis soma 1 em cada KPI.","O KPI \"Total de Solicitações\" conta solicitações únicas (após deduplicação).","O grid dos KPIs usa `grid-template-columns: repeat(5, minmax(0, 1fr))` inline — não pode usar utilitários `grid-cols-*` que quebram em breakpoints."],"dependencias":["US-UNI-04 Ver detalhe da unidade","Migration `00057` (coluna `solicitacoes.origem_laudo_unidade_id`)","Coluna `agendamentos.unidade_destino_id`","Service `src/services/unidades-saude.service.ts::listarSolicitacoesPorUnidade`"],"sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/unidades-saude/[id]/page.tsx`\n- Service: `src/services/unidades-saude.service.ts::listarSolicitacoesPorUnidade` — agora busca em paralelo `solicitacoes` (por `origem_laudo_unidade_id`) + `agendamentos` (por `unidade_destino_id`) e deduplica.\n- Tipo: `VinculoSolicitacaoUnidade = { tipo: \"origem_laudo\" | \"destino_agendamento\"; ... }`\n- KpiBar inline (5 colunas) na própria página."},{"title":"Layout","body":"- KpiBar no topo, **uma única linha** com 5 colunas iguais (grid inline `repeat(5, minmax(0, 1fr))`).\n- Tabela/cards de solicitações abaixo, cada item com os badges do tipo de vínculo (ver US-UNI-07).\n- Estado vazio: \"Nenhuma solicitação vinculada a esta unidade\"."},{"title":"Schema (banco)","body":"- `solicitacoes.origem_laudo_unidade_id` → FK `unidades_saude.id` (migration 00057).\n- `agendamentos.unidade_destino_id` → FK `unidades_saude.id`.\n- Query em paralelo nas duas pontas; dedupe por `solicitacao_id` no service."},{"title":"Side effects","body":"- Seed populado: **107 solicitações com `origem_laudo_unidade_id`** + **107 agendamentos** com `unidade_destino_id`, cobrindo **23 unidades distintas**, sendo **34 com sobreposição** (a mesma unidade aparece como origem do laudo E destino do agendamento na mesma solicitação) — usado para validar a dedupe e os badges combinados."},{"title":"Regras de negócio","body":"- Vínculos retornados podem ser de tipo `origem_laudo`, `destino_agendamento` ou ambos.\n- KPI \"Origem do Laudo\" e KPI \"Destino Agendamento\" contam vínculos, não solicitações.\n- KPI \"Total\" conta solicitações deduplicadas.\n- KPI \"Em Andamento\" e \"Concluídas\" agregam por status final da solicitação."}]},{"id":"US-UNI-07","title":"Tag de tipo de vínculo Solicitação ↔ Unidade (Origem do Laudo / Destino de Agendamento)","story":"**Como** Atendente TFD, Regulação ou Coordenação, **Quero** identificar visualmente, em cada solicitação vinculada a uma unidade, por qual caminho ela está vinculada (laudo emitido ali e/ou agendamento marcado para lá), **Para que** eu interprete relatórios de uso da unidade com clareza e diferencie os dois papéis sem precisar abrir cada solicitação.","criterios":["Cada solicitação listada na tela `/unidades-saude/[id]` exibe um ou dois badges: `ORIGEM DO LAUDO` (índigo) e/ou `DESTINO DE AGENDAMENTO` (verde).","Quando a mesma solicitação está vinculada pelos dois caminhos, os dois badges aparecem juntos lado a lado (mesma linha).","O mesmo padrão de badges é aplicado nos chips clicáveis de unidades dentro do histórico de solicitações do paciente (ver US-PAC-09).","O badge `ORIGEM DO LAUDO` usa paleta índigo (texto escuro, fundo claro); `DESTINO DE AGENDAMENTO` usa paleta verde — diferenciação acessível mesmo em monocromia.","Os badges seguem o tipo `VinculoSolicitacaoUnidade.tipo` retornado pelo service."],"regras":["Existem exatamente 2 tipos de vínculo Solicitação ↔ Unidade: `origem_laudo` e `destino_agendamento`. Nenhum outro tipo deve aparecer na UI.","A regra de \"2 badges juntos\" só ocorre quando a mesma unidade é simultaneamente origem do laudo E destino do agendamento da mesma solicitação.","A diferenciação por tipo é a base para os KPIs separados (US-UNI-06) e para futuros relatórios de uso de unidade por papel.","Os badges são informativos — não permitem ação inline; o clique navega para o detalhe da solicitação."],"dependencias":["US-UNI-04 Ver detalhe da unidade","US-UNI-06 Listar solicitações vinculadas à unidade","US-PAC-09 Histórico de solicitações exibe unidades vinculadas com tag","Service `src/services/unidades-saude.service.ts::listarSolicitacoesPorUnidade` (retorna `vinculos[]`)"],"sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/unidades-saude/[id]/page.tsx` (lista interna).\n- Página: `src/app/pacientes/[id]/page.tsx` (chips de unidade nos cards do histórico).\n- Service: `src/services/unidades-saude.service.ts` — define `VinculoSolicitacaoUnidade`.\n- Service: `src/services/pacientes.service.ts::historicoProcessos` — passa a trazer `origem_laudo_unidade` + `agendamentos.unidades_destino`."},{"title":"Layout","body":"- Badge `ORIGEM DO LAUDO`: pill índigo (fundo `indigo-50`, texto `indigo-700`).\n- Badge `DESTINO DE AGENDAMENTO`: pill verde (fundo `green-50`, texto `green-700`).\n- Quando aparecem juntos, ficam lado a lado com gap pequeno.\n- Em `/pacientes/[id]`, os chips de unidades carregam o badge correspondente e são clicáveis (abrem `/unidades-saude/[id]` em nova aba)."},{"title":"Schema (banco)","body":"- `solicitacoes.origem_laudo_unidade_id` → FK `unidades_saude.id` → vínculo `origem_laudo`.\n- `agendamentos.unidade_destino_id` → FK `unidades_saude.id` → vínculo `destino_agendamento`.\n- Não há tabela própria de \"vínculo\"; o tipo é derivado da fonte de origem do join."},{"title":"Side effects","body":"- Seed: 107 solicitações com origem do laudo + 107 agendamentos com unidade de destino, cobrindo 23 unidades distintas, 34 das quais com sobreposição (mesma unidade nos 2 papéis na mesma solicitação) — cenário ideal para validar badges combinados."},{"title":"Regras de negócio","body":"- O tipo do vínculo determina cor/texto do badge e o KPI somado.\n- Badges combinados sinalizam casos especiais para relatórios futuros (ex.: solicitações em que o atendimento começou e terminou na mesma unidade)."}]}]},{"file":"F03-Regionais-Saude","code":"F02","title":"Regionais de Saúde","description":"Cadastro das Unidades Regionais de Saúde (URS) do Maranhão e dos municípios vinculados a cada regional. A regional determina a região geográfica (Norte/Sul/Leste/Oeste/Central) e quais municípios o atendente vê na sua área.","meta":[{"key":"Tela","value":"`/regionais-saude` (listagem) · `/regionais-saude/[id]` (detalhe)"},{"key":"Drawer","value":"`RegionalDrawer` (cadastro/edição)"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/regionais-saude/page.tsx` · `src/app/regionais-saude/_RegionalDrawer.tsx` · `src/app/regionais-saude/[id]/page.tsx`"},{"key":"Serviço","value":"`src/services/regionais-saude.service.ts`"},{"key":"Tabelas","value":"`regionais_saude` · `regional_saude_municipios`"}],"userStories":[{"id":"US-REG-01","title":"Listar regionais de saúde","story":"**Como** Coordenação Estadual ou Administrador, **Quero** ver todas as regionais cadastradas em uma tabela, **Para que** eu entenda a divisão geográfica do TFD no estado.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/regionais-saude/page.tsx`\n- Sidebar: item \"Regionais\" (ícone `MapPin`)\n- Componentes compartilhados: `PageHeader`, `StatsRow`, `SortableHeader`, `Pagination`, `tfd-table`\n- Serviço: `listarRegionais({ search, page, pageSize })`"},{"title":"Layout","body":"- `PageHeader title=\"Regionais\" subtitle=\"Unidades Regionais de Saúde (URS) do estado do Maranhão\"`\n- Action: \"+ Nova Regional\" (`tfd-btn-primary`), em `<Can action=\"regionais_saude.criar\">`\n- `StatsRow`: Total de Regionais, Regionais Ativas\n- Toolbar: busca padrão"},{"title":"Critérios de aceite","body":"- [ ] Sidebar → \"Regionais\" → `/regionais-saude`\n- [ ] Header exatamente como acima\n- [ ] Campo de busca placeholder \"Buscar por nome, código ou sede...\" (debounce 300ms)\n- [ ] Tabela com colunas: Código (sortable + filtrável, mono) · Nome (sortable) · Sede (sortable + filtrável, `hidden md:table-cell`) · Região (sortable + filtrável, `hidden md:table-cell`) · Telefone (sortable, `hidden lg:table-cell`) · E-mail (sortable, `hidden lg:table-cell`) · Ações (largura 100px)\n- [ ] Linha clicável → `/regionais-saude/[id]`\n- [ ] Paginação 25 por página (10/25/50/100)\n- [ ] Estado vazio: `XCircle` + \"Nenhuma regional encontrada\"\n- [ ] Skeleton 6 linhas durante carga"},{"title":"Estados visuais","body":"- Loading / Empty / Erro: idem F01/F02"},{"title":"Side effects","body":"- Refetch após criar/editar/excluir"},{"title":"Regras de negócio","body":"- Lista todas as regionais ativas\n- Busca cobre `codigo`, `nome`, `municipio_sede`\n- Filtros por Sede e Região via dropdown de checkboxes\n- Cada regional pertence a uma única região do MA (Norte/Sul/Leste/Oeste/Central)\n- Perfis com `regionais_saude.visualizar` acessam"},{"title":"Schema (banco)","body":"- Tabela `regionais_saude`: `id`, `codigo` (UNIQUE), `nome`, `municipio_sede`, `regiao_id`, telefones, emails, endereço, `ativa`, timestamps\n- FK `regiao_id` → `tabelas_auxiliares` categoria `_regioes`\n- Tabela `regional_saude_municipios` (relacionamento N:1 — município pertence a 1 regional)"},{"title":"Permissões","body":"- `regionais_saude.visualizar`, `regionais_saude.criar`, `regionais_saude.editar`, `regionais_saude.excluir`"},{"title":"Dependências","body":"- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (categoria `_regioes`)\n\n---"}],"criterios":["Sidebar → \"Regionais\" → `/regionais-saude`","Header exatamente como acima","Campo de busca placeholder \"Buscar por nome, código ou sede...\" (debounce 300ms)","Tabela com colunas: Código (sortable + filtrável, mono) · Nome (sortable) · Sede (sortable + filtrável, `hidden md:table-cell`) · Região (sortable + filtrável, `hidden md:table-cell`) · Telefone (sortable, `hidden lg:table-cell`) · E-mail (sortable, `hidden lg:table-cell`) · Ações (largura 100px)","Linha clicável → `/regionais-saude/[id]`","Paginação 25 por página (10/25/50/100)","Estado vazio: `XCircle` + \"Nenhuma regional encontrada\"","Skeleton 6 linhas durante carga"],"regras":["Lista todas as regionais ativas","Busca cobre `codigo`, `nome`, `municipio_sede`","Filtros por Sede e Região via dropdown de checkboxes","Cada regional pertence a uma única região do MA (Norte/Sul/Leste/Oeste/Central)","Perfis com `regionais_saude.visualizar` acessam"],"dependencias":["[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (categoria `_regioes`)","--"]},{"id":"US-REG-02","title":"Cadastrar nova regional","story":"**Como** Coordenação Estadual ou Administrador, **Quero** cadastrar uma nova regional de saúde, **Para que** novos municípios possam ser vinculados a ela.","sections":[{"title":"Componentes do protótipo","body":"- Drawer: `src/app/regionais-saude/_RegionalDrawer.tsx` (largura 680px)\n- LookupSelect categoria `_regioes`\n- Autocomplete de município sede (consulta `municipios`)\n- CepAutofill para endereço\n- Serviço: `criarRegional(InsertDTO)`"},{"title":"Layout do drawer","body":"- Title: \"Nova Regional\" + subtitle \"Preencha os dados para cadastrar\"\n- 3 seções:\n  1. **Dados Gerais** (Código + Município Sede + Nome + Região)\n  2. **Endereço** (CEP + Logradouro + Número + Bairro + Município)\n  3. **Contato** (Telefone 1 + Telefone 2 + E-mail Institucional + E-mail Secundário)\n- Footer: \"Cancelar\" + \"Cadastrar Regional\""},{"title":"Campos do formulário","body":"| Campo                | Tipo         | Obrig. | Validação                                       | Mensagem                                                    |\n|----------------------|--------------|--------|-------------------------------------------------|-------------------------------------------------------------|\n| Código               | text         | sim    | máx 10 caracteres, único, MAIÚSCULAS+hífen     | \"Código inválido\" / \"Código já cadastrado\"                  |\n| Município Sede       | autocomplete | não    | item da tabela `municipios`                     | —                                                            |\n| Nome                 | text         | sim    | ≥ 3 caracteres, único                           | \"Informe o nome\" / \"Nome já cadastrado\"                     |\n| Região               | LookupSelect | não    | item ativo de `_regioes`                        | —                                                            |\n| CEP                  | text         | não    | 8 dígitos; auto-preenche                        | —                                                            |\n| Logradouro/Núm./Bairro | text       | não    | livres                                          | —                                                            |\n| Município (endereço) | text         | não    | autocomplete IBGE                               | —                                                            |\n| Telefone 1           | tel          | não    | máscara `(XX) XXXX-XXXX`                        | —                                                            |\n| Telefone 2           | tel          | não    | máscara `(XX) XXXX-XXXX`                        | —                                                            |\n| E-mail Institucional | email        | não    | formato válido                                  | \"E-mail inválido\"                                           |\n| E-mail Secundário    | email        | não    | formato válido                                  | \"E-mail inválido\"                                           |"},{"title":"Critérios de aceite","body":"- [ ] Click \"+ Nova Regional\" → drawer 680px da direita\n- [ ] Foco inicial no campo Código\n- [ ] Código com placeholder \"Ex.: URS-CXS\"\n- [ ] Código duplicado → erro inline \"Código já cadastrado\"\n- [ ] Nome duplicado (case-insensitive) → erro inline\n- [ ] Município Sede com autocomplete: digita → lista de sugestões com IBGE code\n- [ ] Mudar Município Sede não vincula automaticamente — vínculo é separado (US-REG-05)\n- [ ] CEP completo → auto-preenche logradouro/bairro/município\n- [ ] \"Cadastrar Regional\" → spinner → drawer fecha → toast \"Regional cadastrada\" → tabela atualiza\n- [ ] \"Cancelar\" com mudanças → modal \"Descartar alterações?\""},{"title":"Estados visuais","body":"- Saving / Erro: padrões já estabelecidos"},{"title":"Side effects","body":"- INSERT em `regionais_saude`\n- Log de auditoria"},{"title":"Regras de negócio","body":"- Nome único entre regionais (case-insensitive)\n- Código único (formato livre, sugestão URS-XXX)\n- Município Sede é apenas referência visual — não cria vínculo automático na `regional_saude_municipios`\n- Região vem da tabela auxiliar `_regioes`\n- Nova regional entra ativa por default"},{"title":"Schema (banco)","body":"- INSERT em `regionais_saude`\n- Constraints UNIQUE: `codigo`, `nome`"},{"title":"Permissões","body":"- `regionais_saude.criar`"},{"title":"Auditoria","body":"- Log: `entity_type='regional_saude'`, `action='create'`"},{"title":"Dependências","body":"- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]]\n\n---"}],"criterios":["Click \"+ Nova Regional\" → drawer 680px da direita","Foco inicial no campo Código","Código com placeholder \"Ex.: URS-CXS\"","Código duplicado → erro inline \"Código já cadastrado\"","Nome duplicado (case-insensitive) → erro inline","Município Sede com autocomplete: digita → lista de sugestões com IBGE code","Mudar Município Sede não vincula automaticamente — vínculo é separado (US-REG-05)","CEP completo → auto-preenche logradouro/bairro/município","\"Cadastrar Regional\" → spinner → drawer fecha → toast \"Regional cadastrada\" → tabela atualiza","\"Cancelar\" com mudanças → modal \"Descartar alterações?\""],"regras":["Nome único entre regionais (case-insensitive)","Código único (formato livre, sugestão URS-XXX)","Município Sede é apenas referência visual — não cria vínculo automático na `regional_saude_municipios`","Região vem da tabela auxiliar `_regioes`","Nova regional entra ativa por default"],"dependencias":["[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]]","--"]},{"id":"US-REG-03","title":"Editar regional existente","story":"**Como** Coordenação Estadual, **Quero** atualizar dados de uma regional, **Para que** correções (nome, sede, contato, região) fiquem refletidas no sistema.","sections":[{"title":"Componentes do protótipo","body":"- Mesmo drawer da US-REG-02 em modo \"Editar\"\n- Serviço: `atualizarRegional(id, UpdateDTO)`"},{"title":"Critérios de aceite","body":"- [ ] Lápis → drawer \"Editar Regional\" com dados preenchidos\n- [ ] Código é editável (com confirmação adicional caso mude)\n- [ ] Botão \"Salvar Alterações\" começa disabled\n- [ ] Mudança em Região (lookup) dispara warning informativo: \"Mudar a região atualiza os municípios e pacientes vinculados em cascata.\"\n- [ ] Save → spinner → drawer fecha → toast \"Regional atualizada\"\n- [ ] Cancel com mudanças → modal de confirmação"},{"title":"Estados visuais","body":"- Pristine / Dirty / Saving / Erro"},{"title":"Side effects","body":"- UPDATE em `regionais_saude`\n- Se `regiao_id` muda, **cascata**: atualiza `regiao_id` em todos os municípios vinculados → propaga para pacientes\n- Log de auditoria"},{"title":"Regras de negócio","body":"- Mudar nome ou código gera log de auditoria detalhado\n- Mudar região impacta municípios e pacientes vinculados (cascata)"},{"title":"Schema (banco)","body":"- UPDATE em `regionais_saude`\n- Trigger ou função RPC para cascata de região"},{"title":"Permissões","body":"- `regionais_saude.editar`"},{"title":"Auditoria","body":"- Log: `action='update'`, diff por campo"},{"title":"Dependências","body":"- US-REG-02\n\n---"}],"criterios":["Lápis → drawer \"Editar Regional\" com dados preenchidos","Código é editável (com confirmação adicional caso mude)","Botão \"Salvar Alterações\" começa disabled","Mudança em Região (lookup) dispara warning informativo: \"Mudar a região atualiza os municípios e pacientes vinculados em cascata.\"","Save → spinner → drawer fecha → toast \"Regional atualizada\"","Cancel com mudanças → modal de confirmação"],"regras":["Mudar nome ou código gera log de auditoria detalhado","Mudar região impacta municípios e pacientes vinculados (cascata)"],"dependencias":["US-REG-02","--"]},{"id":"US-REG-04","title":"Ver detalhe da regional","story":"**Como** Coordenação ou Atendente, **Quero** abrir o detalhe da regional e ver todos os municípios vinculados, **Para que** eu entenda o alcance daquela regional.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/regionais-saude/[id]/page.tsx`\n- `StatsRow` no detalhe (3 cards)\n- Section \"Municípios Vinculados\" + botão \"Gerenciar Municípios\" (abre subdrawer/modal)\n- Serviços: `buscarRegional(id)`, `listarMunicipiosDaRegional(id)`, `contarPacientesPorRegional(id)`"},{"title":"Layout (sections empilhadas)","body":"- Header: Nome + código (mono) + região + botões \"Voltar\" e \"Editar\"\n- `StatsRow` no detalhe: Municípios (count), Pacientes (count), Municípios com Pacientes (count)\n- **Section \"Municípios Vinculados\"** (`MapPin`):\n  - Header da section tem contagem + botão \"⚙ Gerenciar Municípios\"\n  - Lista de cards com: nome do município · código IBGE (mono) · qtd de pacientes daquele município\n- **Section \"Contato\"** (`Phone`): telefones e e-mails"},{"title":"Critérios de aceite","body":"- [ ] Click no nome da regional → `/regionais-saude/[id]`\n- [ ] Header com Nome + chip de código (mono) + chip de região\n- [ ] Botão \"Voltar\" respeita `?from=`\n- [ ] StatsRow do detalhe mostra os 3 contadores (Municípios, Pacientes, Municípios c/ Pacientes)\n- [ ] Cards de município ordenados alfabeticamente\n- [ ] Click no card de município (futuro) → navega para `/pacientes?municipio=X`\n- [ ] Botão \"Gerenciar Municípios\" abre subdrawer/modal de vincular/desvincular (US-REG-05)\n- [ ] Estado vazio de municípios: \"Nenhum município vinculado ainda. Clique em 'Gerenciar Municípios' para começar.\""},{"title":"Estados visuais","body":"- Loading: `DetailPageSkeleton` + skeleton list\n- Não encontrado: mensagem + Voltar"},{"title":"Regras de negócio","body":"- Detalhe é read-only (edição via drawer)\n- Estatísticas calculadas em tempo real (count nas tabelas relacionadas)\n- Município com 0 pacientes ainda aparece na lista (só não conta no \"Municípios com Pacientes\")"},{"title":"Schema (banco)","body":"- `select('*, regiao(*)').eq('id', id).single()` em `regionais_saude`\n- `select('*, municipio:municipios(*)').eq('regional_id', id)` em `regional_saude_municipios`\n- COUNT em `pacientes` por `municipio_residencia_id`"},{"title":"Permissões","body":"- `regionais_saude.visualizar`"},{"title":"Dependências","body":"- US-REG-01, US-REG-05\n\n---"}],"criterios":["Click no nome da regional → `/regionais-saude/[id]`","Header com Nome + chip de código (mono) + chip de região","Botão \"Voltar\" respeita `?from=`","StatsRow do detalhe mostra os 3 contadores (Municípios, Pacientes, Municípios c/ Pacientes)","Cards de município ordenados alfabeticamente","Click no card de município (futuro) → navega para `/pacientes?municipio=X`","Botão \"Gerenciar Municípios\" abre subdrawer/modal de vincular/desvincular (US-REG-05)","Estado vazio de municípios: \"Nenhum município vinculado ainda. Clique em 'Gerenciar Municípios' para começar.\""],"regras":["Detalhe é read-only (edição via drawer)","Estatísticas calculadas em tempo real (count nas tabelas relacionadas)","Município com 0 pacientes ainda aparece na lista (só não conta no \"Municípios com Pacientes\")"],"dependencias":["US-REG-01, US-REG-05","--"]},{"id":"US-REG-05","title":"Vincular / desvincular municípios à regional","story":"**Como** Coordenação Estadual, **Quero** vincular um município à regional ou remover esse vínculo, **Para que** o atendente da regional veja só os pacientes/solicitações da sua área.","sections":[{"title":"Componentes do protótipo","body":"- Subdrawer/Modal \"Gerenciar Municípios\" — abre a partir do detalhe da regional\n- Autocomplete de municípios (consulta `municipios` filtrando MA + não vinculados a outra regional, ou com indicador)\n- Serviço: `vincularMunicipio(regionalId, municipioId)`, `desvincularMunicipio(regionalId, municipioId)`"},{"title":"Layout do modal","body":"- Largura: 560px\n- Header: \"Gerenciar Municípios — {nome da regional}\"\n- Body:\n  - Campo de autocomplete \"Adicionar município...\" (com indicador para itens já vinculados a outras regionais)\n  - Lista de municípios atualmente vinculados (com ✕ para desvincular)\n- Footer: \"Fechar\""},{"title":"Critérios de aceite","body":"- [ ] Click \"Gerenciar Municípios\" → modal abre\n- [ ] Autocomplete mostra todos os municípios do MA; itens já vinculados a outra regional aparecem com badge cinza \"vinculado a {OutraRegional}\" (clicáveis ainda)\n- [ ] Selecionar município já vinculado a outra → modal de confirmação \"Este município está vinculado à {regional X}. Deseja transferir?\" → confirmar = desvincula da anterior + vincula aqui\n- [ ] Selecionar município livre → vincula direto + toast \"Município vinculado\"\n- [ ] Cada município na lista vinculada tem ícone ✕ → click → modal \"Desvincular município?\" com aviso \"Pacientes deste município ficarão sem regional até serem vinculados novamente.\"\n- [ ] Confirma desvincular → toast \"Município desvinculado\" + sai da lista\n- [ ] Fechar modal: foco volta para botão \"Gerenciar Municípios\""},{"title":"Estados visuais","body":"- **Vinculando/Desvinculando**: spinner pequeno no item\n- **Erro**: toast vermelho"},{"title":"Side effects","body":"- INSERT/DELETE em `regional_saude_municipios`\n- Cascata: pacientes do município passam a ter `regional_id` da nova regional (ou null se desvinculado)\n- Log de auditoria por operação"},{"title":"Regras de negócio","body":"- Um município pertence a **no máximo 1 regional** (constraint UNIQUE em `municipio_id`)\n- Vincular município já vinculado a outra → trigger modal de transferência\n- Pacientes herdam regional via município de origem\n- Apenas perfis com `regionais_saude.vincular_municipios` alteram vínculos"},{"title":"Schema (banco)","body":"- Tabela `regional_saude_municipios`:\n  - `id`, `regional_id` (FK), `municipio_id` (FK, UNIQUE)\n- Constraint: cada município só pode estar em 1 regional"},{"title":"Permissões","body":"- `regionais_saude.vincular_municipios`"},{"title":"Auditoria","body":"- Log: `entity_type='regional_municipio'`, `action='link'` / `action='unlink'` / `action='transfer'`\n- Em transferência: registra origem + destino"},{"title":"Dependências","body":"- US-REG-04"}],"criterios":["Click \"Gerenciar Municípios\" → modal abre","Autocomplete mostra todos os municípios do MA; itens já vinculados a outra regional aparecem com badge cinza \"vinculado a {OutraRegional}\" (clicáveis ainda)","Selecionar município já vinculado a outra → modal de confirmação \"Este município está vinculado à {regional X}. Deseja transferir?\" → confirmar = desvincula da anterior + vincula aqui","Selecionar município livre → vincula direto + toast \"Município vinculado\"","Cada município na lista vinculada tem ícone ✕ → click → modal \"Desvincular município?\" com aviso \"Pacientes deste município ficarão sem regional até serem vinculados novamente.\"","Confirma desvincular → toast \"Município desvinculado\" + sai da lista","Fechar modal: foco volta para botão \"Gerenciar Municípios\""],"regras":["Um município pertence a **no máximo 1 regional** (constraint UNIQUE em `municipio_id`)","Vincular município já vinculado a outra → trigger modal de transferência","Pacientes herdam regional via município de origem","Apenas perfis com `regionais_saude.vincular_municipios` alteram vínculos"],"dependencias":["US-REG-04"]}]},{"file":"F01-Cadastros-Mestres","code":"F03","title":"Cadastros Mestres (Tabelas Auxiliares)","description":"Tela única de Configurações onde o administrador mantém as tabelas auxiliares do sistema: tipos de procedimento, tipos de documento, vínculos de acompanhante, motivos de encerramento, tipos de despesa, bancos, companhias de transporte, regiões do MA. Organizada em 5 seções por área (Clínico, Pacientes, Transporte, Financeiro, Sistema).","meta":[{"key":"Tela","value":"`/sistema/configuracoes`"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/sistema/configuracoes/page.tsx`"},{"key":"Serviço","value":"`src/services/tabelas-auxiliares.service.ts` (listarPorCategoria, criarItemAuxiliar, etc.)"},{"key":"Tabelas","value":"`tabelas_auxiliares` (chave-valor por categoria) · `companhias_transporte` · `regioes_maranhao`"}],"userStories":[{"id":"US-CFG-01","title":"Navegar entre seções e categorias","story":"**Como** Administrador, **Quero** navegar pelas categorias de cadastros mestres organizadas por área, **Para que** eu encontre rapidamente a tabela que preciso manter.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/sistema/configuracoes/page.tsx`\n- Constante `SECOES` (linha ~86) define 5 seções com ícone + categorias\n- Layout 2 colunas: sidebar à esquerda + painel à direita\n- Sidebar: `BookmarkPanel` (definido inline) com seções colapsáveis"},{"title":"Configuração das seções (do código)","body":"| Seção                      | Ícone        | Categorias                                                              |\n|----------------------------|--------------|-------------------------------------------------------------------------|\n| Clínico                    | Stethoscope  | `tipo_procedimento`, `tipo_documento`                                   |\n| Pacientes e Acompanhantes  | Users        | `vinculo_acompanhante`                                                  |\n| Transporte                 | Plane        | `_companhias` (Companhias de Transporte)                                |\n| Financeiro e Permanência   | DollarSign   | `motivo_encerramento`, `tipo_despesa`, `banco`                          |\n| Sistema e Acesso           | Settings     | `_regioes` (Regiões do Maranhão)                                        |"},{"title":"Layout","body":"- `PageHeader title=\"Configurações\" subtitle=\"Cadastros mestres e parâmetros do sistema\"`\n- Grid 2 colunas: 280px sidebar + 1fr painel\n- Sidebar:\n  - 5 grupos com header de seção (ícone + título 11px uppercase tracking)\n  - Cada categoria como item clicável:\n    - Nome (14px)\n    - Descrição abaixo (11px cinza)\n    - Background `var(--tfd-blue-50)` quando ativa, borda azul à esquerda\n- Painel: conteúdo da categoria ativa (tabela de itens)"},{"title":"Critérios de aceite","body":"- [ ] Sidebar → \"Configurações\" → `/sistema/configuracoes`\n- [ ] Header + subtitle conforme acima\n- [ ] Layout 2 colunas (responsivo: stack em mobile)\n- [ ] 5 seções com ícone listadas conforme acima\n- [ ] Cada categoria mostra nome + descrição curta abaixo (cinza)\n- [ ] Categoria ativa: fundo azul claro + borda azul à esquerda\n- [ ] Default: primeira categoria da primeira seção (`tipo_procedimento`)\n- [ ] Apenas perfis com `sys_configuracoes.visualizar` acessam a rota\n- [ ] Click em categoria → muda painel à direita (sem reload de página)"},{"title":"Estados visuais","body":"- **Categoria ativa**: borda azul + fundo azul claro + nome em negrito\n- **Hover**: fundo cinza claro"},{"title":"Regras de negócio","body":"- Categorias correspondem ao campo `categoria` em `tabelas_auxiliares` (string key)\n- Companhias e Regiões usam tabelas próprias (prefixo `_` no código indica que não vão para `tabelas_auxiliares`)\n- Lista de seções é fixa no código (não administrável)"},{"title":"Schema (banco)","body":"- Tabela `tabelas_auxiliares`: `id`, `categoria`, `codigo`, `nome`, `descricao`, `ordem`, `ativo`, timestamps\n- Tabela `companhias_transporte`: dedicada para companhias com campo `modal`\n- Tabela `regioes_maranhao`: dedicada para regiões com campo `zona`"},{"title":"Permissões","body":"- `sys_configuracoes.visualizar` (guard)"},{"title":"Dependências","body":"- [[F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]\n\n---"}],"criterios":["Sidebar → \"Configurações\" → `/sistema/configuracoes`","Header + subtitle conforme acima","Layout 2 colunas (responsivo: stack em mobile)","5 seções com ícone listadas conforme acima","Cada categoria mostra nome + descrição curta abaixo (cinza)","Categoria ativa: fundo azul claro + borda azul à esquerda","Default: primeira categoria da primeira seção (`tipo_procedimento`)","Apenas perfis com `sys_configuracoes.visualizar` acessam a rota","Click em categoria → muda painel à direita (sem reload de página)"],"regras":["Categorias correspondem ao campo `categoria` em `tabelas_auxiliares` (string key)","Companhias e Regiões usam tabelas próprias (prefixo `_` no código indica que não vão para `tabelas_auxiliares`)","Lista de seções é fixa no código (não administrável)"],"dependencias":["[[F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]","--"]},{"id":"US-CFG-02","title":"Listar itens de uma categoria","story":"**Como** Administrador, **Quero** ver todos os itens cadastrados em uma categoria, **Para que** eu tenha visão do que está disponível para o sistema.","sections":[{"title":"Componentes do protótipo","body":"- Painel à direita renderiza tabela\n- Componente `LookupSelect` consumidor das listas (em outras telas)\n- Serviço: `listarPorCategoria(categoria)`"},{"title":"Layout do painel","body":"- Header do painel: título da categoria (16px, 600) + descrição (12px cinza) + botão \"+ Cadastrar\" à direita\n- Tabela `tfd-table` com colunas:\n  - Nome (sortable)\n  - Código (mono, 12px)\n  - Ordem (numérico, sortable)\n  - Status (badge verde \"Ativo\" / cinza \"Inativo\")\n  - Ações (Editar lápis, Inativar lixeira)\n- Companhias (`_companhias`) tem coluna extra: Modal (Aéreo/Terrestre/Fluvial)\n- Regiões (`_regioes`) tem coluna extra: Zona (Norte/Sul/Leste/Oeste/Central)\n- Bancos tem coluna extra: Código do banco (3 dígitos)"},{"title":"Critérios de aceite","body":"- [ ] Painel mostra título da categoria + descrição + botão \"+ Cadastrar\"\n- [ ] Tabela com colunas Nome · Código · Ordem · Status · Ações\n- [ ] Ordenação default: `nome` asc\n- [ ] Linhas de itens inativos: chip cinza \"Inativo\" na coluna Status\n- [ ] Estado vazio: \"Nenhum item cadastrado. Use '+ Cadastrar' para adicionar.\"\n- [ ] Companhias: coluna extra \"Modal\" com chip colorido por tipo\n- [ ] Regiões: coluna extra \"Zona\"\n- [ ] Bancos: coluna extra \"Código do banco\"\n- [ ] Ações condicionais à permissão (`sys_configuracoes.editar`)"},{"title":"Estados visuais","body":"- **Ativo**: badge verde\n- **Inativo**: badge cinza (linha levemente acinzentada)"},{"title":"Regras de negócio","body":"- Itens inativos aparecem na listagem (com badge), mas NÃO aparecem em selects/autocompletes consumidores\n- Ordenação padrão por `nome` asc\n- Coluna \"Ordem\" controla a ordem em que itens aparecem nos selects (admin pode reordenar)"},{"title":"Schema (banco)","body":"- `select('*').eq('categoria', categoria).order('ordem')` ou similar\n- Companhias/Regiões: tabelas próprias"},{"title":"Permissões","body":"- `sys_configuracoes.visualizar`"},{"title":"Dependências","body":"- US-CFG-01\n\n---"}],"criterios":["Painel mostra título da categoria + descrição + botão \"+ Cadastrar\"","Tabela com colunas Nome · Código · Ordem · Status · Ações","Ordenação default: `nome` asc","Linhas de itens inativos: chip cinza \"Inativo\" na coluna Status","Estado vazio: \"Nenhum item cadastrado. Use '+ Cadastrar' para adicionar.\"","Companhias: coluna extra \"Modal\" com chip colorido por tipo","Regiões: coluna extra \"Zona\"","Bancos: coluna extra \"Código do banco\"","Ações condicionais à permissão (`sys_configuracoes.editar`)"],"regras":["Itens inativos aparecem na listagem (com badge), mas NÃO aparecem em selects/autocompletes consumidores","Ordenação padrão por `nome` asc","Coluna \"Ordem\" controla a ordem em que itens aparecem nos selects (admin pode reordenar)"],"dependencias":["US-CFG-01","--"]},{"id":"US-CFG-03","title":"Cadastrar novo item","story":"**Como** Administrador, **Quero** cadastrar um novo item na categoria selecionada, **Para que** ele fique disponível nos selects do sistema (drawers de cadastro, edição etc.).","sections":[{"title":"Componentes do protótipo","body":"- Mini-form inline no painel (não drawer) — alternativa para categorias simples\n- Drawer dedicado para Companhias e Regiões (`CompanhiaDrawer`, `RegiaoDrawer`)\n- Serviços: `criarItemAuxiliar(payload)`, `criarCompanhia(payload)`, `criarRegiao(payload)`"},{"title":"Layout do mini-form","body":"- Aparece como card no topo do painel (acima da tabela) ou expande a row\n- Campos básicos: Nome (obrigatório), Código (auto-gerado, editável), Ordem (numérico, opcional)\n- Botões: \"Cancelar\" + \"Salvar\""},{"title":"Layout do drawer (companhias / regiões)","body":"- Largura 480px\n- Campos básicos + específicos:\n  - Companhias: Nome + Código + Modal (select: Aéreo/Terrestre/Fluvial) + Ordem\n  - Regiões: Nome + Código + Zona (select: Norte/Sul/Leste/Oeste/Central) + Ordem"},{"title":"Campos do formulário","body":"| Campo  | Tipo   | Obrig. | Validação                                       | Mensagem                                  |\n|--------|--------|--------|-------------------------------------------------|-------------------------------------------|\n| Nome   | text   | sim    | ≥ 2 caracteres; único na categoria              | \"Já existe um item com este nome\"         |\n| Código | text   | sim    | auto-gerado a partir do nome; único na categoria | \"Código já em uso\"                       |\n| Ordem  | number | não    | inteiro ≥ 0                                     | —                                          |\n| Modal  | select | sim    | (só companhias) Aéreo/Terrestre/Fluvial         | \"Selecione o modal\"                       |\n| Zona   | select | sim    | (só regiões) Norte/Sul/Leste/Oeste/Central     | \"Selecione a zona\"                        |\n| Código banco | number | sim | (só bancos) 3 dígitos numéricos                | \"Código do banco deve ter 3 dígitos\"      |"},{"title":"Critérios de aceite","body":"- [ ] Click \"+ Cadastrar\" → abre mini-form inline (ou drawer)\n- [ ] Código é auto-gerado a partir do Nome: uppercase + sem acento + espaços → underscore\n  - Ex.: \"Cônjuge\" → `CONJUGE`, \"Centro Hospitalar\" → `CENTRO_HOSPITALAR`\n- [ ] Código gerado é editável manualmente\n- [ ] Nome único dentro da categoria (case-insensitive) → erro inline se duplicado\n- [ ] Companhias: campo \"Modal\" obrigatório (select)\n- [ ] Regiões: campo \"Zona\" obrigatório (select)\n- [ ] Bancos: campo \"Código do banco\" obrigatório (3 dígitos numéricos)\n- [ ] \"Salvar\" → toast verde \"Item cadastrado\" + nova linha na tabela\n- [ ] \"Cancelar\" → fecha sem salvar"},{"title":"Estados visuais","body":"- **Form aberto**: padding visual + foco no campo Nome\n- **Saving**: spinner no botão Salvar"},{"title":"Side effects","body":"- INSERT em `tabelas_auxiliares` (categorias simples) ou tabela própria (companhias/regiões)\n- `ativo = true` default\n- Log de auditoria"},{"title":"Regras de negócio","body":"- Item criado entra ativo por default\n- Código único globalmente na categoria (constraint)\n- Após criar, item já é selecionável em qualquer select consumidor (refetch automático via cache key)"},{"title":"Schema (banco)","body":"- INSERT em `tabelas_auxiliares` com `categoria`, `codigo`, `nome`, `descricao`, `ordem`, `ativo`\n- Constraint UNIQUE em `(categoria, codigo)`"},{"title":"Permissões","body":"- `sys_configuracoes.editar`"},{"title":"Auditoria","body":"- Log: `entity_type='tabela_auxiliar'` (ou específico), `action='create'`"},{"title":"Dependências","body":"- US-CFG-02\n\n---"}],"criterios":["Click \"+ Cadastrar\" → abre mini-form inline (ou drawer)","Código é auto-gerado a partir do Nome: uppercase + sem acento + espaços → underscore","Ex.: \"Cônjuge\" → `CONJUGE`, \"Centro Hospitalar\" → `CENTRO_HOSPITALAR`","Código gerado é editável manualmente","Nome único dentro da categoria (case-insensitive) → erro inline se duplicado","Companhias: campo \"Modal\" obrigatório (select)","Regiões: campo \"Zona\" obrigatório (select)","Bancos: campo \"Código do banco\" obrigatório (3 dígitos numéricos)","\"Salvar\" → toast verde \"Item cadastrado\" + nova linha na tabela","\"Cancelar\" → fecha sem salvar"],"regras":["Item criado entra ativo por default","Código único globalmente na categoria (constraint)","Após criar, item já é selecionável em qualquer select consumidor (refetch automático via cache key)"],"dependencias":["US-CFG-02","--"]},{"id":"US-CFG-04","title":"Editar item existente","story":"**Como** Administrador, **Quero** corrigir nome ou código de um item, **Para que** erros de digitação ou padronização sejam ajustados.","sections":[{"title":"Componentes do protótipo","body":"- Mesmo mini-form inline (ou drawer para companhias/regiões), em modo edit\n- Serviço: `atualizarItemAuxiliar(id, payload)`\n- Modal de confirmação para mudança de código (uso especial)"},{"title":"Critérios de aceite","body":"- [ ] Lápis na linha → form aparece com dados preenchidos (ou drawer)\n- [ ] Campos Nome e Código editáveis\n- [ ] Tentativa de mudar o **Código**: dispara modal de confirmação \"Alterar código pode afetar dados antigos que referenciam este item. O sistema não propaga a mudança automaticamente. Confirmar?\"\n- [ ] Confirmar mudança de código → procede\n- [ ] Cancelar mudança → volta ao código original\n- [ ] Salvar → toast verde \"Item atualizado\" + linha atualiza\n- [ ] Cancel → fecha sem salvar"},{"title":"Estados visuais","body":"- **Pristine / Dirty**: botão Salvar enabled/disabled\n- **Saving**: spinner"},{"title":"Side effects","body":"- UPDATE em `tabelas_auxiliares` (ou tabela específica)\n- Log com diff\n- Refetch automático nos consumidores"},{"title":"Regras de negócio","body":"- Mudar o **Código** NÃO propaga em registros antigos:\n  - Ex.: solicitações antigas com `tipo_documento = LAUDO_MEDICO` continuam com esse código mesmo se você renomear para `LAUDO`\n  - Para evitar quebra, sistema mostra modal de confirmação extra\n- Alterações registram log de auditoria detalhado"},{"title":"Schema (banco)","body":"- UPDATE em `tabelas_auxiliares`\n- Trigger atualiza `updated_at`"},{"title":"Permissões","body":"- `sys_configuracoes.editar`"},{"title":"Auditoria","body":"- Log: `action='update'`, diff por campo"},{"title":"Dependências","body":"- US-CFG-02\n\n---"}],"criterios":["Lápis na linha → form aparece com dados preenchidos (ou drawer)","Campos Nome e Código editáveis","Tentativa de mudar o **Código**: dispara modal de confirmação \"Alterar código pode afetar dados antigos que referenciam este item. O sistema não propaga a mudança automaticamente. Confirmar?\"","Confirmar mudança de código → procede","Cancelar mudança → volta ao código original","Salvar → toast verde \"Item atualizado\" + linha atualiza","Cancel → fecha sem salvar"],"regras":["Mudar o **Código** NÃO propaga em registros antigos:","Ex.: solicitações antigas com `tipo_documento = LAUDO_MEDICO` continuam com esse código mesmo se você renomear para `LAUDO`","Para evitar quebra, sistema mostra modal de confirmação extra","Alterações registram log de auditoria detalhado"],"dependencias":["US-CFG-02","--"]},{"id":"US-CFG-05","title":"Inativar / reativar item","story":"**Como** Administrador, **Quero** inativar um item que não deve mais ser selecionado, **Para que** ele suma dos selects sem perder histórico de uso.","sections":[{"title":"Componentes do protótipo","body":"- Toggle ou botão \"Inativar / Reativar\" na linha\n- Modal de confirmação para inativação\n- Reativação direta (sem modal)\n- Serviço: `toggleAtivoItem(id, ativo)`"},{"title":"Critérios de aceite","body":"- [ ] Linha ativa: ícone `Slash` ou botão \"Inativar\" (cor vermelha)\n- [ ] Linha inativa: ícone `RotateCcw` ou botão \"Reativar\" (cor verde)\n- [ ] Click \"Inativar\" → modal \"Inativar item?\" com nome em destaque + aviso \"Este item não aparecerá mais em novos cadastros, mas continuará válido em registros antigos.\"\n- [ ] Confirma → toast \"Item inativado\" + linha atualiza (badge muda)\n- [ ] Click \"Reativar\" → toast direto \"Item reativado\" (sem modal)\n- [ ] Item inativo continua aparecendo na tabela com badge \"Inativo\""},{"title":"Estados visuais","body":"- **Inativando**: spinner no ícone\n- **Após inativar**: badge cinza, ícone troca para \"Reativar\""},{"title":"Side effects","body":"- UPDATE no campo `ativo` da `tabelas_auxiliares`\n- Refetch nos consumidores (cache invalidado)\n- Log de auditoria"},{"title":"Regras de negócio","body":"- **Não há hard delete** em tabelas auxiliares — apenas inativação\n- Item inativo é **filtrado fora** em todos os consumidores (drawers, selects, autocompletes via `useLookup`)\n- Item inativo **permanece** nos registros que já o utilizaram (não quebra histórico)\n- Reativação pode acontecer a qualquer momento"},{"title":"Schema (banco)","body":"- UPDATE `set ativo = X` em `tabelas_auxiliares` (ou específica)"},{"title":"Permissões","body":"- `sys_configuracoes.editar`"},{"title":"Auditoria","body":"- Log: `action='deactivate'` / `action='reactivate'`"},{"title":"Dependências","body":"- US-CFG-02"}],"criterios":["Linha ativa: ícone `Slash` ou botão \"Inativar\" (cor vermelha)","Linha inativa: ícone `RotateCcw` ou botão \"Reativar\" (cor verde)","Click \"Inativar\" → modal \"Inativar item?\" com nome em destaque + aviso \"Este item não aparecerá mais em novos cadastros, mas continuará válido em registros antigos.\"","Confirma → toast \"Item inativado\" + linha atualiza (badge muda)","Click \"Reativar\" → toast direto \"Item reativado\" (sem modal)","Item inativo continua aparecendo na tabela com badge \"Inativo\""],"regras":["**Não há hard delete** em tabelas auxiliares — apenas inativação","Item inativo é **filtrado fora** em todos os consumidores (drawers, selects, autocompletes via `useLookup`)","Item inativo **permanece** nos registros que já o utilizaram (não quebra histórico)","Reativação pode acontecer a qualquer momento"],"dependencias":["US-CFG-02"]},{"id":"US-CFG-06","title":"Tabela auxiliar \"Vínculo\" unificada","story":"**Como** Administrador, **Quero** uma única tabela auxiliar de Vínculo (usada por acompanhantes E por titulares de conta bancária), **Para que** eu não precise manter duas listas idênticas em /sistema/configuracoes.","sections":[{"title":"Componentes do protótipo","body":"- Tela `/sistema/configuracoes`\n- Migration `00057_unificacao_vinculo.sql`"},{"title":"Critérios de aceite (visuais)","body":"- [ ] Label da seção em /sistema/configuracoes é \"Vínculo\" (antes: \"Vínculos de Acompanhante\")\n- [ ] Lista inclui o item \"Próprio paciente\"\n- [ ] Label \"Regiões do Maranhão\" foi renomeada para \"Região\" (o sistema vai atender outros estados)"},{"title":"Regras de negócio","body":"- Categoria `vinculo_acompanhante` foi descontinuada; categoria oficial é `vinculo`\n- Tabela `vinculo` é consumida em: drawer de acompanhante (PacienteDrawer), drawer de conta bancária (DadosBancariosDrawer), select de titular em Ajuda de Custo\n- Item \"Próprio paciente\" foi adicionado para cobrir contas em nome do próprio paciente"},{"title":"Schema (banco)","body":"- Migration `00057_unificacao_vinculo.sql` renomeia / consolida `vinculo_acompanhante` → `vinculo`\n- Tabela auxiliar única consultada por `listarItensTabelaAuxiliar(vinculo)`"},{"title":"Dependências","body":"- [[../EPIC-01-Cadastros-Fundamentais/F01-Pacientes#US-PAC-07|US-PAC-07 — Pool de contas bancárias do paciente]]\n\n---"}],"criterios":["Label da seção em /sistema/configuracoes é \"Vínculo\" (antes: \"Vínculos de Acompanhante\")","Lista inclui o item \"Próprio paciente\"","Label \"Regiões do Maranhão\" foi renomeada para \"Região\" (o sistema vai atender outros estados)"],"regras":["Categoria `vinculo_acompanhante` foi descontinuada; categoria oficial é `vinculo`","Tabela `vinculo` é consumida em: drawer de acompanhante (PacienteDrawer), drawer de conta bancária (DadosBancariosDrawer), select de titular em Ajuda de Custo","Item \"Próprio paciente\" foi adicionado para cobrir contas em nome do próprio paciente"],"dependencias":["[[../EPIC-01-Cadastros-Fundamentais/F01-Pacientes#US-PAC-07|US-PAC-07]] — Pool de contas bancárias do paciente","--"]}]}]},{"folder":"EPIC-03-Pacientes","code":"EPIC-03","title":"Pacientes","pendente":false,"features":[{"file":"F01-Pacientes","code":"F01","title":"Listagem e CRUD de Pacientes","description":"Cadastro completo de pacientes do TFD. A página de Pacientes lista todos os pacientes, permite buscar, criar, editar, ver detalhe e excluir. Também guarda dados bancários para ajuda de custo, acompanhantes e histórico de solicitações.","meta":[{"key":"Tela","value":"`/pacientes` (listagem) · `/pacientes/[id]` (detalhe) · `/pacientes/[id]/prontuario` (prontuário)"},{"key":"Drawer","value":"`PacienteDrawer` (cadastro/edição) · `AcompanhanteDrawer` (subdrawer)"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/pacientes/page.tsx` · `src/app/pacientes/_PacienteDrawer.tsx` · `src/app/pacientes/[id]/page.tsx` · `src/app/pacientes/_DadosBancariosDrawer.tsx`"},{"key":"Serviço","value":"`src/services/pacientes.service.ts` · `src/services/acompanhantes.service.ts` · `src/services/dados-bancarios.service.ts`"},{"key":"Tabela","value":"`pacientes` (Supabase)"}],"userStories":[{"id":"US-PAC-01","title":"Listar pacientes","story":"**Como** Atendente TFD ou Coordenação Estadual, **Quero** ver todos os pacientes cadastrados em uma tabela com busca e paginação, **Para que** eu encontre rapidamente um paciente quando precisar consultar ou referenciar em solicitações.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/pacientes/page.tsx`\n- Tabela compartilhada: `tfd-table` (classes em `globals.css`)\n- Header: `@/shared/components/page-header/PageHeader`\n- StatsRow: `@/shared/components/stats-row/StatsRow`\n- Cabeçalho ordenável: `SortableHeader` em `@/shared/components/sort-th/SortTh`\n- Paginação: `@/shared/components/pagination/Pagination`\n- Skeleton: `@/components/ui/skeleton`\n- Serviço: `listarPacientes({ search, page, pageSize })` em `pacientes.service.ts`"},{"title":"Layout","body":"- `PageHeader title=\"Pacientes\" subtitle=\"Gerenciamento de pacientes TFD\"`\n  - Action no canto direito: botão `tfd-btn tfd-btn-primary` \"Novo Paciente\" (ícone `Plus`, 16px), envolto em `<Can action=\"pacientes.criar\">`\n- `StatsRow` com 3 cards: Total de Pacientes, Pacientes Ativos, Com Processo Ativo (último mostra \"—\" enquanto não há query consolidada)\n- Toolbar: caixa de busca branca (`border-radius: 8`, altura 36px, min-width 280) com ícone `Search 14px` cinza `#9CA3AF` à esquerda\n- Container da tabela: `div.tfd-table-wrap` com overflow-x auto + `table.tfd-table`"},{"title":"Critérios de aceite (visuais)","body":"- [ ] Item da sidebar \"Pacientes\" (grupo CADASTROS, ícone `Contact`) navega para `/pacientes`\n- [ ] Header mostra título e subtítulo exatamente como acima\n- [ ] Botão \"+ Novo Paciente\" só aparece para perfis com `pacientes.criar`\n- [ ] Campo de busca tem placeholder \"Buscar por nome, CPF ou CNS...\" (debounce 300ms)\n- [ ] Tabela mostra colunas, na ordem: Nome (sortable) · CPF (sortable, `hidden md:table-cell`) · CNS (sortable, `hidden lg:table-cell`) · Município (sortable + filtrável, `hidden lg:table-cell`) · Telefone (`hidden md:table-cell`) · Data Cadastro (sortable, `hidden md:table-cell`) · Ações (largura fixa 100px)\n- [ ] Coluna Município tem filtro de checkbox (multi-select dos municípios existentes na base)\n- [ ] Linhas têm hover discreto (`#F8FAFC`)\n- [ ] Clica em Nome ou ícone \"olho\" → navega para `/pacientes/[id]`\n- [ ] Ícone lápis (`Pencil 14px`, cor `var(--tfd-primary-500)`) abre drawer de edição\n- [ ] Ícone lixeira (`Trash2 14px`, cor `var(--tfd-status-danger)`) abre modal de exclusão\n- [ ] Paginação no rodapé: \"Mostrando X-Y de Z\" + controles (primeira / anterior / 1 2 3 ... / próxima / última) + seletor 10/25/50/100 (default 25)\n- [ ] Estado vazio (sem pacientes na base): ícone `XCircle 32px` cinza + texto \"Nenhum paciente encontrado\" (centralizado, padding 12)\n- [ ] Estado vazio com busca: mesma estrutura, sem mensagem específica de busca (basta o `XCircle` cinza)\n- [ ] Skeleton enquanto carrega: 6 linhas, cada coluna com `<Skeleton className=\"h-4 w-XX\">` (Nome 48, demais 28, Ações 16 alinhado à direita)"},{"title":"Estados visuais","body":"- **Loading**: skeleton de 6 linhas\n- **Empty**: `XCircle 32px` + \"Nenhum paciente encontrado\"\n- **Erro de fetch**: toast vermelho via `useToast()` (\"Erro ao carregar pacientes\" + mensagem do erro)"},{"title":"Interações & teclado","body":"- Tab navega entre busca → cabeçalhos sortable → ações\n- Enter no campo de busca não submete (busca é reativa)\n- Click no cabeçalho da coluna sortable alterna asc/desc/sem-ordem\n- Click no header de Município abre dropdown de checkboxes (`SortableHeader` com `filterOptions`)"},{"title":"Side effects","body":"- Mudança de busca/filtro reseta página para 1\n- Toast verde \"Paciente cadastrado\" / \"Paciente atualizado\" / \"Paciente excluído\" após cada operação (já é responsabilidade das outras USs, mas a tabela escuta e refaz fetch)"},{"title":"Regras de negócio","body":"- Lista todos os pacientes ativos (`ativo = true`) por default\n- Busca é case-insensitive, ignora acentuação, cobre `nome_completo`, `cpf` (com ou sem máscara), `cns`\n- Ordenação padrão: `nome_completo` asc\n- Cabeçalhos clicáveis: 1º clique asc, 2º desc, 3º remove (volta para default)\n- Apenas 1 coluna ordenada por vez\n- Paginação client-side se cabe em uma página; senão usa `range` no Supabase (server-side)\n- Perfis com permissão `pacientes.visualizar` podem acessar (guard de rota + `Can` no botão)"},{"title":"Schema (banco)","body":"- Tabela `pacientes` (todas as colunas em `database.types.ts`)\n- Colunas principais retornadas no `select('*')`: `id`, `nome_completo`, `cpf`, `cns`, `sexo`, `data_nascimento`, `telefone_celular`, `telefone_fixo`, `email`, `municipio`, `uf`, `ativo`, `created_at`\n- Filtro `eq('ativo', true)` na query\n- Ordenação default: `order('nome_completo', { ascending: true })`\n- Busca usa `or('nome_completo.ilike.%X%, cpf.ilike.%X%, cns.ilike.%X%')`\n- Paginação: `range(offset, offset + size - 1)` + `select('*', { count: 'exact' })`"},{"title":"Permissões","body":"- `pacientes.visualizar` — necessário para acessar a tela (guard de rota)\n- `pacientes.criar` — controla visibilidade do botão \"Novo Paciente\" via `<Can action>`\n- `pacientes.editar` — controla visibilidade do lápis\n- `pacientes.excluir` — controla visibilidade da lixeira"},{"title":"Acessibilidade","body":"- Tabela com `<thead>` semântico e cabeçalhos como `<th>`\n- Botões de ação têm `title` (tooltip) descritivo\n- Ícones decorativos têm `aria-hidden`\n- Foco visível em busca, headers sortable e ações da linha"},{"title":"Dependências","body":"- [[../EPIC-04-Configuracoes-Administrativo/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]] (permissão `pacientes.visualizar`)\n\n---"}],"criterios":["Item da sidebar \"Pacientes\" (grupo CADASTROS, ícone `Contact`) navega para `/pacientes`","Header mostra título e subtítulo exatamente como acima","Botão \"+ Novo Paciente\" só aparece para perfis com `pacientes.criar`","Campo de busca tem placeholder \"Buscar por nome, CPF ou CNS...\" (debounce 300ms)","Tabela mostra colunas, na ordem: Nome (sortable) · CPF (sortable, `hidden md:table-cell`) · CNS (sortable, `hidden lg:table-cell`) · Município (sortable + filtrável, `hidden lg:table-cell`) · Telefone (`hidden md:table-cell`) · Data Cadastro (sortable, `hidden md:table-cell`) · Ações (largura fixa 100px)","Coluna Município tem filtro de checkbox (multi-select dos municípios existentes na base)","Linhas têm hover discreto (`#F8FAFC`)","Clica em Nome ou ícone \"olho\" → navega para `/pacientes/[id]`","Ícone lápis (`Pencil 14px`, cor `var(--tfd-primary-500)`) abre drawer de edição","Ícone lixeira (`Trash2 14px`, cor `var(--tfd-status-danger)`) abre modal de exclusão","Paginação no rodapé: \"Mostrando X-Y de Z\" + controles (primeira / anterior / 1 2 3 ... / próxima / última) + seletor 10/25/50/100 (default 25)","Estado vazio (sem pacientes na base): ícone `XCircle 32px` cinza + texto \"Nenhum paciente encontrado\" (centralizado, padding 12)","Estado vazio com busca: mesma estrutura, sem mensagem específica de busca (basta o `XCircle` cinza)","Skeleton enquanto carrega: 6 linhas, cada coluna com `<Skeleton className=\"h-4 w-XX\">` (Nome 48, demais 28, Ações 16 alinhado à direita)"],"regras":["Lista todos os pacientes ativos (`ativo = true`) por default","Busca é case-insensitive, ignora acentuação, cobre `nome_completo`, `cpf` (com ou sem máscara), `cns`","Ordenação padrão: `nome_completo` asc","Cabeçalhos clicáveis: 1º clique asc, 2º desc, 3º remove (volta para default)","Apenas 1 coluna ordenada por vez","Paginação client-side se cabe em uma página; senão usa `range` no Supabase (server-side)","Perfis com permissão `pacientes.visualizar` podem acessar (guard de rota + `Can` no botão)"],"dependencias":["[[../EPIC-04-Configuracoes-Administrativo/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]] (permissão `pacientes.visualizar`)","--"]},{"id":"US-PAC-02","title":"Cadastrar novo paciente","story":"**Como** Atendente TFD, **Quero** cadastrar um novo paciente preenchendo um drawer lateral, **Para que** o paciente fique disponível para ser usado em uma solicitação TFD.","sections":[{"title":"Componentes do protótipo","body":"- Drawer: `src/app/pacientes/_PacienteDrawer.tsx`\n- Drawer base: `@/shared/components/drawer/Drawer` (largura `640px`)\n- Campo: `@/shared/components/drawer/FormField` (label + hint + slot do input)\n- Input padrão: classe `tfd-input` em `globals.css`\n- Auto-preenchimento de CEP: componente `CepAutofill` (preenche logradouro/bairro/município/UF via ViaCEP)\n- Máscaras: `maskCPF`, `maskCNS`, `maskPhone` em `@/shared/pipes/formatters`\n- Cálculo de idade: `calcularIdade` em `@/shared/utils/idade`\n- Serviço: `criarPaciente(InsertDTO)` em `pacientes.service.ts`\n- Toast: `useToast()` de `@/shared/components/toast/Toast`"},{"title":"Layout do drawer","body":"- Cabeçalho: title \"Novo Paciente\" + subtitle \"Preencha os dados para cadastrar um novo paciente\"\n- 2 seções, separadas por `<hr className=\"tfd-divider\" />`:\n  1. **Dados Pessoais** (CPF + Nome + CNS + Nascimento/Sexo + Telefones + Email + Outros contatos)\n  2. **Endereço** (CEP com auto-preenchimento + Logradouro + Número + Bairro + Município + UF)\n- Footer: botões \"Cancelar\" (`tfd-btn-secondary`) e \"Cadastrar Paciente\" (`tfd-btn-primary`, disabled enquanto saving)"},{"title":"Campos do formulário","body":"| Campo               | Tipo       | Obrig. | Máscara              | Validação                                     | Mensagem de erro                                       |\n|---------------------|------------|--------|----------------------|-----------------------------------------------|--------------------------------------------------------|\n| CPF                 | text       | sim    | `XXX.XXX.XXX-XX`     | 11 dígitos + algoritmo Receita Federal       | \"CPF inválido\"                                         |\n|                     |            |        |                      | único na base                                  | \"Já existe paciente com este CPF\"                      |\n| Nome completo       | text       | sim    | —                    | ≥ 3 caracteres                                | \"Informe o nome completo\"                              |\n| CNS (Cartão SUS)    | text       | não    | `000 0000 0000 0000` | 15 dígitos numéricos                          | \"CNS inválido\"                                         |\n| Data de nascimento  | date       | sim    | nativa do browser    | não pode ser futura, ≥ 1900                   | \"Data de nascimento inválida\"                          |\n| Sexo                | select     | sim    | —                    | `MASCULINO` / `FEMININO` / `OUTRO`            | \"Selecione o sexo\"                                     |\n| Telefone celular    | tel        | (1)    | `(XX) XXXXX-XXXX`    | 11 dígitos                                    | \"Telefone inválido\"                                    |\n| Telefone fixo       | tel        | (1)    | `(XX) XXXX-XXXX`     | 10 dígitos                                    | \"Telefone inválido\"                                    |\n| E-mail              | email      | não    | —                    | formato `nome@dominio.tld`                    | \"E-mail inválido\"                                      |\n| Outros contatos     | textarea   | não    | —                    | ≤ 500 caracteres                              | —                                                      |\n| CEP                 | text       | não    | `XXXXX-XXX`          | 8 dígitos; consulta ViaCEP ao completar       | \"CEP não encontrado\" (silenciosa, só não preenche)     |\n| Logradouro          | text       | não    | —                    | auto-preenchido pelo CEP, editável            | —                                                      |\n| Número              | text       | não    | —                    | ≤ 20 caracteres                               | —                                                      |\n| Bairro              | text       | não    | —                    | auto-preenchido, editável                     | —                                                      |\n| Município           | text       | sim    | —                    | autocomplete de municípios IBGE-MA            | \"Selecione um município\"                               |\n| UF                  | text       | sim    | —                    | autocomplete UF                               | —                                                      |\n\n(1) **Ao menos um dos telefones é obrigatório** (celular OU fixo). Hint visível: \"ao menos um obrigatório\"."},{"title":"Critérios de aceite (visuais)","body":"- [ ] Clica \"+ Novo Paciente\" → drawer abre da direita, largura `640px`, animado em 200ms\n- [ ] Foco automático no campo CPF ao abrir\n- [ ] Campo CPF aparece com `fontWeight: 600, fontSize: 15` (destaque visual de campo-chave)\n- [ ] Ao digitar 11 dígitos válidos no CPF, sistema consulta paciente existente em paralelo (debounce 400ms)\n- [ ] CPF duplicado → erro inline \"Já existe paciente com este CPF\" + botão \"Salvar\" desabilitado\n- [ ] CPF com dígitos verificadores inválidos → erro inline \"CPF inválido\"\n- [ ] Hint do campo Telefone celular: \"ao menos um obrigatório\"\n- [ ] CEP completo (8 dígitos) → spinner aparece + após resposta, logradouro/bairro/município/UF são preenchidos (editáveis depois)\n- [ ] Ao falhar a consulta ViaCEP, drawer não bloqueia — usuário preenche manualmente\n- [ ] Campos obrigatórios em branco no submit: erro inline em cada campo + toast vermelho \"Verifique os campos obrigatórios\"\n- [ ] \"Cadastrar Paciente\" → durante o save: botão mostra spinner + texto \"Salvando...\" + drawer fica `aria-busy=\"true\"`\n- [ ] Sucesso → drawer fecha → toast verde \"Paciente cadastrado — {nome}\" → tabela recarrega (paciente aparece na lista respeitando ordem/filtro atual)\n- [ ] \"Cancelar\" com qualquer campo preenchido → modal \"Descartar alterações?\" (botões \"Continuar editando\" / \"Descartar\")\n- [ ] \"Cancelar\" sem preenchimento → drawer fecha direto\n- [ ] Esc no drawer tem o mesmo comportamento de \"Cancelar\""},{"title":"Estados visuais","body":"- **Saving**: botão com spinner, todos os inputs `disabled`\n- **Erro de servidor**: drawer permanece aberto + toast vermelho \"Erro ao cadastrar paciente\" + mensagem técnica do Supabase\n- **CEP loading**: spinner pequeno ao lado do campo CEP"},{"title":"Interações & teclado","body":"- Tab navega na ordem dos campos (CPF → Nome → CNS → Nascimento → Sexo → ...)\n- Enter no último campo do form não submete automaticamente (submit é manual no botão)\n- Esc no drawer = Cancelar (com confirmação se sujou)"},{"title":"Side effects no sucesso","body":"- INSERT em `pacientes` com `ativo = true`\n- Log em `audit_logs` (entity_type: `paciente`, action: `create`, user_id, snapshot do registro)\n- Toast verde, fechamento do drawer, refresh da tabela"},{"title":"Regras de negócio","body":"- CPF é único no sistema (constraint UNIQUE no banco)\n- CNS é único quando preenchido (constraint UNIQUE parcial — só valida quando `cns IS NOT NULL`)\n- Nome da mãe deixou de ser campo do drawer (campo legado removido)\n- Sexo no BD usa `MASCULINO` / `FEMININO` / `OUTRO`\n- Município alimenta automaticamente a Regional do paciente via tabela auxiliar `regional_saude_municipios`\n- Zona regional (Norte/Sul/Leste/Oeste/Centro) é derivada da regional, não cadastrada no paciente\n- Validação de CPF: formato + dígitos verificadores (algoritmo da Receita Federal)\n- Validação client-side antes do submit; o backend valida novamente (defense in depth)"},{"title":"Schema (banco)","body":"- INSERT em `pacientes`:\n  - `id` (uuid, gerado pelo banco)\n  - `cpf` (string, único)\n  - `cns` (string, opcional, único parcial)\n  - `nome_completo` (string)\n  - `sexo` (enum `Sexo`)\n  - `data_nascimento` (date)\n  - `telefone_celular`, `telefone_fixo`, `email` (nullable)\n  - `logradouro`, `numero`, `bairro`, `cep`, `municipio`, `uf` (strings)\n  - `municipio_residencia_id` (FK para `municipios.id`)\n  - `ativo` (boolean, default true)\n  - `created_at`, `updated_at` (timestamps automáticos)\n- FK obrigatória: `municipio_residencia_id` → `municipios.id`"},{"title":"Permissões","body":"- `pacientes.criar` — visibilidade do botão e abertura do drawer"},{"title":"Auditoria","body":"- Log: `entity_type='paciente'`, `action='create'`, `user_id`, `entity_id` (id do paciente), `diff` (snapshot completo do registro criado)"},{"title":"Acessibilidade","body":"- Drawer com `role=\"dialog\"`, `aria-modal=\"true\"`, `aria-labelledby` no título\n- Foco inicial no primeiro campo (CPF)\n- Trap de foco dentro do drawer\n- Esc fecha o drawer\n- Cada `FormField` tem `<label for=\"...\">` ligado ao input"},{"title":"Dependências","body":"- [[F03-Regionais-Saude|F03 — Regionais de Saúde]] (vínculo município ↔ regional)\n- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (tabela `municipios` IBGE)\n\n---"}],"criterios":["Clica \"+ Novo Paciente\" → drawer abre da direita, largura `640px`, animado em 200ms","Foco automático no campo CPF ao abrir","Campo CPF aparece com `fontWeight: 600, fontSize: 15` (destaque visual de campo-chave)","Ao digitar 11 dígitos válidos no CPF, sistema consulta paciente existente em paralelo (debounce 400ms)","CPF duplicado → erro inline \"Já existe paciente com este CPF\" + botão \"Salvar\" desabilitado","CPF com dígitos verificadores inválidos → erro inline \"CPF inválido\"","Hint do campo Telefone celular: \"ao menos um obrigatório\"","CEP completo (8 dígitos) → spinner aparece + após resposta, logradouro/bairro/município/UF são preenchidos (editáveis depois)","Ao falhar a consulta ViaCEP, drawer não bloqueia — usuário preenche manualmente","Campos obrigatórios em branco no submit: erro inline em cada campo + toast vermelho \"Verifique os campos obrigatórios\"","\"Cadastrar Paciente\" → durante o save: botão mostra spinner + texto \"Salvando...\" + drawer fica `aria-busy=\"true\"`","Sucesso → drawer fecha → toast verde \"Paciente cadastrado — {nome}\" → tabela recarrega (paciente aparece na lista respeitando ordem/filtro atual)","\"Cancelar\" com qualquer campo preenchido → modal \"Descartar alterações?\" (botões \"Continuar editando\" / \"Descartar\")","\"Cancelar\" sem preenchimento → drawer fecha direto","Esc no drawer tem o mesmo comportamento de \"Cancelar\""],"regras":["CPF é único no sistema (constraint UNIQUE no banco)","CNS é único quando preenchido (constraint UNIQUE parcial — só valida quando `cns IS NOT NULL`)","Nome da mãe deixou de ser campo do drawer (campo legado removido)","Sexo no BD usa `MASCULINO` / `FEMININO` / `OUTRO`","Município alimenta automaticamente a Regional do paciente via tabela auxiliar `regional_saude_municipios`","Zona regional (Norte/Sul/Leste/Oeste/Centro) é derivada da regional, não cadastrada no paciente","Validação de CPF: formato + dígitos verificadores (algoritmo da Receita Federal)","Validação client-side antes do submit; o backend valida novamente (defense in depth)"],"dependencias":["[[F03-Regionais-Saude|F03 — Regionais de Saúde]] (vínculo município ↔ regional)","[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (tabela `municipios` IBGE)","--"]},{"id":"US-PAC-03","title":"Editar paciente existente","story":"**Como** Atendente TFD, **Quero** editar os dados de um paciente já cadastrado, **Para que** correções de digitação ou atualizações de contato/endereço sejam aplicadas.","sections":[{"title":"Componentes do protótipo","body":"- Mesmo drawer da US-PAC-02 (`PacienteDrawer`), em modo \"Editar\"\n- Serviço: `atualizarPaciente(id, UpdateDTO)` em `pacientes.service.ts`\n- Trigger: ícone `Pencil` na linha da tabela ou botão \"Editar\" no detalhe"},{"title":"Layout","body":"- Igual ao drawer de cadastro, mas com:\n  - Title: \"Editar Paciente\"\n  - Subtitle: \"Atualize os dados do paciente\"\n  - Campos pré-preenchidos com os valores atuais\n  - CPF aparece como `readOnly` + ícone de cadeado pequeno + tooltip \"CPF não pode ser alterado após cadastro\"\n  - Botão final: \"Salvar Alterações\" (`tfd-btn-primary`)"},{"title":"Critérios de aceite","body":"- [ ] Clica no lápis na linha → drawer abre em modo edição\n- [ ] Campos preenchidos com os valores atuais (incluindo telefones com máscara aplicada via `maskPhone`)\n- [ ] Campo CPF: `readOnly`, fundo levemente cinza, cursor `not-allowed` no hover, tooltip \"CPF não pode ser alterado\"\n- [ ] Botão \"Salvar Alterações\" começa **desabilitado** (state `isDirty = false`)\n- [ ] Qualquer alteração em qualquer campo habilita o botão\n- [ ] Validações são as mesmas do cadastro (campos obrigatórios não podem ser limpos)\n- [ ] \"Salvar Alterações\" → spinner + texto \"Salvando...\" → drawer fecha → toast verde \"Paciente atualizado\" → linha da tabela atualiza\n- [ ] \"Cancelar\" com mudanças → modal \"Descartar alterações?\"\n- [ ] \"Cancelar\" sem mudanças → fecha direto\n- [ ] Limpar campo obrigatório e tentar salvar → erro inline + botão volta a ficar disabled"},{"title":"Estados visuais","body":"- **Pristine** (sem mudanças): botão \"Salvar Alterações\" cinza/disabled\n- **Dirty**: botão azul, ativo\n- **Saving**: spinner + \"Salvando...\"\n- **Erro**: toast vermelho + drawer permanece aberto"},{"title":"Side effects no sucesso","body":"- UPDATE em `pacientes` com `updated_at` automático\n- Log em `audit_logs` com **diff campo a campo** (valor anterior + valor novo + nome do campo)\n- Toast + fechamento + refresh"},{"title":"Regras de negócio","body":"- **CPF nunca é editável** após criado (evita perda de vínculo histórico com solicitações)\n- Alterações em qualquer campo geram log de auditoria detalhado (diff)\n- Munícipio alterado → recalcula `municipio_residencia_id`\n- Telefone celular obrigatório se telefone fixo for limpo (e vice-versa)\n- Perfis com permissão `pacientes.editar` veem o lápis"},{"title":"Schema (banco)","body":"- UPDATE em `pacientes` (todos os campos exceto `id`, `cpf`, `created_at`)\n- `updated_at` atualizado pelo trigger do Supabase"},{"title":"Permissões","body":"- `pacientes.editar`"},{"title":"Auditoria","body":"- Log: `entity_type='paciente'`, `action='update'`, `diff = { campo: { antes, depois } }`\n- 1 entrada por save (não 1 por campo)"},{"title":"Dependências","body":"- US-PAC-02 (mesma estrutura de drawer)\n- [[../EPIC-04-Configuracoes-Administrativo/F04-Logs-Auditoria|F04 — Logs de Auditoria]]\n\n---"}],"criterios":["Clica no lápis na linha → drawer abre em modo edição","Campos preenchidos com os valores atuais (incluindo telefones com máscara aplicada via `maskPhone`)","Campo CPF: `readOnly`, fundo levemente cinza, cursor `not-allowed` no hover, tooltip \"CPF não pode ser alterado\"","Botão \"Salvar Alterações\" começa **desabilitado** (state `isDirty = false`)","Qualquer alteração em qualquer campo habilita o botão","Validações são as mesmas do cadastro (campos obrigatórios não podem ser limpos)","\"Salvar Alterações\" → spinner + texto \"Salvando...\" → drawer fecha → toast verde \"Paciente atualizado\" → linha da tabela atualiza","\"Cancelar\" com mudanças → modal \"Descartar alterações?\"","\"Cancelar\" sem mudanças → fecha direto","Limpar campo obrigatório e tentar salvar → erro inline + botão volta a ficar disabled"],"regras":["**CPF nunca é editável** após criado (evita perda de vínculo histórico com solicitações)","Alterações em qualquer campo geram log de auditoria detalhado (diff)","Munícipio alterado → recalcula `municipio_residencia_id`","Telefone celular obrigatório se telefone fixo for limpo (e vice-versa)","Perfis com permissão `pacientes.editar` veem o lápis"],"dependencias":["US-PAC-02 (mesma estrutura de drawer)","[[../EPIC-04-Configuracoes-Administrativo/F04-Logs-Auditoria|F04 — Logs de Auditoria]]","--"]},{"id":"US-PAC-04","title":"Ver detalhe do paciente","story":"**Como** qualquer usuário autorizado, **Quero** abrir uma tela com todos os dados do paciente e seu histórico, **Para que** eu tenha uma visão completa sem precisar abrir várias telas.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/pacientes/[id]/page.tsx`\n- Subcomponente `Section` (definido na própria página, linha ~580): card com ícone + título + content\n- Skeleton: `DetailPageSkeleton`, `CardListSkeleton` de `@/shared/components/skeleton`\n- Serviços: `buscarPaciente(id)` (paciente + acompanhantes), `listarSolicitacoesPorPaciente(id)`\n- Ícones: `MapPin`, `Landmark`, `Phone`, `Mail`, `UserPlus`, `ArrowLeft`"},{"title":"Layout (sections empilhadas — não tabs)","body":"1. Header: nome do paciente + idade · CPF abaixo + chips (telefone com `tel:`, e-mail com `mailto:`)\n   - Botão \"Voltar\" (ArrowLeft) que respeita `?from=` na URL\n   - Botão \"Editar\" (`Pencil`) → abre drawer da US-PAC-03\n2. **Histórico de Solicitações** (em destaque no topo) — `Section icon={<FileText />}`\n3. Grid 2 colunas (em telas grandes): **Endereço** (`MapPin`) | **Dados Bancários** (`Landmark`)\n4. **Acompanhantes** — `Section icon={<Contact />}` com botão \"+ Novo\""},{"title":"Critérios de aceite","body":"- [ ] Clica em paciente na listagem → navega para `/pacientes/[id]`\n- [ ] Header mostra nome (font-size 16, font-weight 600) + idade entre parênteses (cor cinza) + CPF abaixo (mono, 12px)\n- [ ] Botão \"Voltar\" tem `ArrowLeft 14px` + texto \"Voltar para Pacientes\" (ou \"Voltar para Solicitações\" se `?from=solicitacoes`)\n- [ ] Card \"Histórico de Solicitações\" sempre presente no topo; estado vazio: \"Nenhuma solicitação cadastrada para este paciente\"\n- [ ] Cada solicitação no histórico: número (link para `/fluxo-v2/solicitacoes/[id]?from=paciente`) · data criação · status badge · botão \"Ver\"\n- [ ] Card \"Endereço\" mostra grid 80px/1fr com: CEP · Logradouro+Número · Bairro · Município/UF\n- [ ] Card \"Endereço\" estado vazio: \"Endereço não cadastrado.\" (cor cinza)\n- [ ] Card \"Dados Bancários\" mostra Banco · Agência · Conta+Tipo · Titular (ou estado vazio com botão \"Cadastrar conta\")\n- [ ] Card \"Acompanhantes\" mostra cada acompanhante com nome + idade + vínculo + ícones de ação (✎ editar, 🗑 remover)\n- [ ] Card \"Acompanhantes\" tem botão \"+ Novo\" no header da seção que abre `AcompanhanteDrawer`\n- [ ] Carregamento: `DetailPageSkeleton` para o header + `CardListSkeleton rows={3}` para as listas\n- [ ] Erro de fetch (paciente não existe): mostra mensagem \"Paciente não encontrado\" + botão \"Voltar\""},{"title":"Estados visuais","body":"- **Loading**: skeletons em cada seção\n- **Não encontrado**: mensagem + botão Voltar\n- **Acompanhantes vazios**: \"Nenhum acompanhante cadastrado\" + botão \"+ Novo\""},{"title":"Side effects","body":"- Toda navegação a partir do detalhe propaga `?from=paciente` para que o \"Voltar\" funcione corretamente\n- Sidebar destaca item \"Pacientes\" (origem efetiva)"},{"title":"Regras de negócio","body":"- Detalhe é read-only para campos do paciente (edição só via drawer)\n- Histórico inclui solicitações de qualquer status (incl. encerradas e canceladas)\n- Acompanhantes mostrados são todos os vinculados ao paciente (tabela `acompanhantes`)\n- Cliques em telefone abrem `tel:`, em e-mail abrem `mailto:`"},{"title":"Schema (banco)","body":"- SELECT em `pacientes` (`select('*, acompanhantes(*)').eq('id', id).single()`)\n- SELECT em `solicitacoes` filtrado por `paciente_id = id`"},{"title":"Permissões","body":"- `pacientes.visualizar` (mesma da listagem)"},{"title":"Acessibilidade","body":"- Header com `<h1>` (nome do paciente)\n- Cada `Section` tem `<h2>` semântico\n- Links de telefone/e-mail acessíveis via teclado"},{"title":"Dependências","body":"- US-PAC-01 (navegação a partir da listagem)\n- US-PAC-06 (card de dados bancários)\n\n---"}],"criterios":["Clica em paciente na listagem → navega para `/pacientes/[id]`","Header mostra nome (font-size 16, font-weight 600) + idade entre parênteses (cor cinza) + CPF abaixo (mono, 12px)","Botão \"Voltar\" tem `ArrowLeft 14px` + texto \"Voltar para Pacientes\" (ou \"Voltar para Solicitações\" se `?from=solicitacoes`)","Card \"Histórico de Solicitações\" sempre presente no topo; estado vazio: \"Nenhuma solicitação cadastrada para este paciente\"","Cada solicitação no histórico: número (link para `/fluxo-v2/solicitacoes/[id]?from=paciente`) · data criação · status badge · botão \"Ver\"","Card \"Endereço\" mostra grid 80px/1fr com: CEP · Logradouro+Número · Bairro · Município/UF","Card \"Endereço\" estado vazio: \"Endereço não cadastrado.\" (cor cinza)","Card \"Dados Bancários\" mostra Banco · Agência · Conta+Tipo · Titular (ou estado vazio com botão \"Cadastrar conta\")","Card \"Acompanhantes\" mostra cada acompanhante com nome + idade + vínculo + ícones de ação (✎ editar, 🗑 remover)","Card \"Acompanhantes\" tem botão \"+ Novo\" no header da seção que abre `AcompanhanteDrawer`","Carregamento: `DetailPageSkeleton` para o header + `CardListSkeleton rows={3}` para as listas","Erro de fetch (paciente não existe): mostra mensagem \"Paciente não encontrado\" + botão \"Voltar\""],"regras":["Detalhe é read-only para campos do paciente (edição só via drawer)","Histórico inclui solicitações de qualquer status (incl. encerradas e canceladas)","Acompanhantes mostrados são todos os vinculados ao paciente (tabela `acompanhantes`)","Cliques em telefone abrem `tel:`, em e-mail abrem `mailto:`"],"dependencias":["US-PAC-01 (navegação a partir da listagem)","US-PAC-06 (card de dados bancários)","--"]},{"id":"US-PAC-05","title":"Excluir paciente","story":"**Como** Coordenação Estadual ou Administrador, **Quero** excluir um paciente cadastrado por engano, **Para que** a base fique limpa.","sections":[{"title":"Componentes do protótipo","body":"- Modal: `ConfirmDialog` (componente compartilhado) ou modal inline na própria página\n- Serviço: `excluirPaciente(id)` em `pacientes.service.ts` (soft delete: `update({ ativo: false })`)\n- Trigger: ícone `Trash2` na linha da tabela (cor `var(--tfd-status-danger)`)"},{"title":"Layout do modal","body":"- Header: \"Excluir paciente?\"\n- Body: nome do paciente em **negrito** + texto \"Esta ação é permanente. O paciente não poderá ser usado em novas solicitações.\"\n- Quando há solicitação vinculada: aviso adicional âmbar \"Este paciente possui solicitações vinculadas. Cancele ou encerre antes de excluir.\" + botão \"Excluir\" desabilitado\n- Footer: \"Cancelar\" (cinza) + \"Excluir\" (vermelho `tfd-btn-danger`)"},{"title":"Critérios de aceite","body":"- [ ] Clica lixeira → modal centralizado abre (overlay escuro 40% opacidade)\n- [ ] Modal mostra nome do paciente em destaque\n- [ ] Botão \"Excluir\" só aparece para perfis com `pacientes.excluir`\n- [ ] Se há solicitação vinculada (independente do status), botão \"Excluir\" disabled + aviso âmbar\n- [ ] \"Excluir\" → spinner no botão → modal fecha → toast verde \"Paciente excluído — O registro foi desativado do sistema.\"\n- [ ] Paciente some imediatamente da tabela (refetch)\n- [ ] \"Cancelar\" ou click fora ou Esc → modal fecha sem ação\n- [ ] Erro de servidor → modal continua aberto + toast vermelho \"Erro ao excluir — {mensagem}\""},{"title":"Estados visuais","body":"- **Pode excluir**: botão vermelho ativo\n- **Bloqueado (com solicitações)**: botão cinza disabled + aviso âmbar\n- **Excluindo**: spinner no botão"},{"title":"Side effects no sucesso","body":"- UPDATE em `pacientes`: `ativo = false`\n- Log em `audit_logs` (action: `delete`)\n- Toast verde"},{"title":"Regras de negócio","body":"- **Soft delete**: o registro permanece no banco (`ativo = false`), apenas é filtrado fora das listagens e selects\n- Paciente excluído pode ser \"restaurado\" via admin (não exposto no MVP)\n- Pareceres, observações e histórico do paciente excluído permanecem intactos\n- Apenas perfis com permissão `pacientes.excluir` veem a lixeira\n- Bloqueio quando há solicitação vinculada: checagem feita no clique para abrir o modal"},{"title":"Schema (banco)","body":"- UPDATE em `pacientes`: `set ativo = false where id = X`\n- Validação prévia: `select count(*) from solicitacoes where paciente_id = X` (qualquer status)"},{"title":"Permissões","body":"- `pacientes.excluir`"},{"title":"Auditoria","body":"- Log: `entity_type='paciente'`, `action='delete'`, `entity_id`, `user_id`, `snapshot` do registro no momento da exclusão"},{"title":"Dependências","body":"- US-PAC-01 (botão de exclusão na linha)\n\n---"}],"criterios":["Clica lixeira → modal centralizado abre (overlay escuro 40% opacidade)","Modal mostra nome do paciente em destaque","Botão \"Excluir\" só aparece para perfis com `pacientes.excluir`","Se há solicitação vinculada (independente do status), botão \"Excluir\" disabled + aviso âmbar","\"Excluir\" → spinner no botão → modal fecha → toast verde \"Paciente excluído — O registro foi desativado do sistema.\"","Paciente some imediatamente da tabela (refetch)","\"Cancelar\" ou click fora ou Esc → modal fecha sem ação","Erro de servidor → modal continua aberto + toast vermelho \"Erro ao excluir — {mensagem}\""],"regras":["**Soft delete**: o registro permanece no banco (`ativo = false`), apenas é filtrado fora das listagens e selects","Paciente excluído pode ser \"restaurado\" via admin (não exposto no MVP)","Pareceres, observações e histórico do paciente excluído permanecem intactos","Apenas perfis com permissão `pacientes.excluir` veem a lixeira","Bloqueio quando há solicitação vinculada: checagem feita no clique para abrir o modal"],"dependencias":["US-PAC-01 (botão de exclusão na linha)","--"]},{"id":"US-PAC-09","title":"Histórico de solicitações exibe unidades vinculadas com tag","story":"**Como** Atendente TFD, Regulação ou Coordenação, **Quero** ver em cada card do histórico de solicitações do paciente quais unidades estão vinculadas (origem do laudo / destino do agendamento) com tag visual, **Para que** eu entenda o caminho do paciente sem precisar abrir cada solicitação e consiga navegar direto para a unidade.","criterios":["Na tela `/pacientes/[id]`, cada card de solicitação do histórico exibe uma linha com chips das unidades vinculadas.","Cada chip mostra o nome da unidade e a tag do tipo de vínculo (`ORIGEM DO LAUDO` índigo / `DESTINO DE AGENDAMENTO` verde) — mesmo padrão da US-UNI-07.","Se a mesma unidade aparece nos dois papéis na mesma solicitação, os dois badges aparecem juntos no chip.","Os chips são clicáveis e abrem `/unidades-saude/[id]` em **nova aba** (`target=\"_blank\"`).","Quando a solicitação não tem nenhuma unidade vinculada, a linha de chips não é renderizada (não exibe estado vazio dentro do card)."],"regras":["O service `historicoProcessos` retorna, para cada solicitação, `origem_laudo_unidade` (objeto da unidade) e `agendamentos.unidades_destino` (lista das unidades destino dos agendamentos da solicitação).","A UI consolida os dois campos em uma única lista de chips, derivando o tipo do vínculo a partir da fonte.","O clique em qualquer chip sempre abre em nova aba — preservar o histórico do paciente aberto.","A formatação visual dos chips reusa a mesma paleta da US-UNI-07 para consistência cross-screen."],"dependencias":["US-PAC-04 Ver detalhe do paciente","US-UNI-04 Ver detalhe da unidade","US-UNI-07 Tag de tipo de vínculo Solicitação ↔ Unidade","Service `src/services/pacientes.service.ts::historicoProcessos` (ampliado)","Migration `00057` (`solicitacoes.origem_laudo_unidade_id`)","Coluna `agendamentos.unidade_destino_id`"],"sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/pacientes/[id]/page.tsx` — cards de solicitação no histórico.\n- Service: `src/services/pacientes.service.ts::historicoProcessos` — passou a puxar `origem_laudo_unidade` e `agendamentos.unidades_destino`.\n- Chip de unidade: reusa o padrão visual de badge da US-UNI-07."},{"title":"Layout","body":"- Dentro do card de solicitação, uma linha com chips das unidades vinculadas.\n- Cada chip: nome da unidade + badge índigo (`ORIGEM DO LAUDO`) ou verde (`DESTINO DE AGENDAMENTO`), ou os dois lado a lado.\n- Clique → abre `/unidades-saude/[id]` em nova aba."},{"title":"Schema (banco)","body":"- `solicitacoes.origem_laudo_unidade_id` → FK `unidades_saude.id`.\n- `agendamentos.unidade_destino_id` → FK `unidades_saude.id`.\n- O service junta os dois caminhos por solicitação e devolve para a UI consolidar."},{"title":"Side effects","body":"- Seed: 107 solicitações com origem do laudo + 107 agendamentos com unidade de destino, cobrindo 23 unidades distintas, 34 com sobreposição entre os dois papéis — usado também para validar os chips no histórico do paciente."},{"title":"Regras de negócio","body":"- Chip sempre carrega a tag do tipo de vínculo (sem tag não existe).\n- Abertura em nova aba é obrigatória para não perder o histórico do paciente em foco.\n- Consistência visual com a tela de unidade (US-UNI-07) — mesma paleta, mesmo texto da tag."}]}]},{"file":"F01-Pacientes","code":"F02","title":"Dados Bancários e Pool de Contas do Paciente","description":"Cadastro e gestão das contas bancárias do paciente — pool reutilizável de contas usado pela Ajuda de Custo no Financeiro. Inclui criação, edição, definição de conta principal e seleção a partir do drawer da Solicitação.","meta":[{"key":"Drawer","value":"`PacienteDrawer` (cadastro/edição) · `AcompanhanteDrawer` (subdrawer)"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/pacientes/page.tsx` · `src/app/pacientes/_PacienteDrawer.tsx` · `src/app/pacientes/[id]/page.tsx` · `src/app/pacientes/_DadosBancariosDrawer.tsx`"}],"userStories":[{"id":"US-PAC-06","title":"Cadastrar dados bancários do paciente","story":"**Como** Atendente TFD ou Financeiro, **Quero** registrar a conta bancária do paciente, **Para que** seja possível pagar ajuda de custo posteriormente.","sections":[{"title":"Componentes do protótipo","body":"- Card \"Dados Bancários\" no detalhe (`/pacientes/[id]`, `Section icon={<Landmark />}`)\n- Drawer dedicado para cadastro/edição (a criar): `DadosBancariosDrawer`\n- LookupSelect: `@/shared/components/lookup-select/LookupSelect` (categoria `banco`)\n- Serviço: `salvarDadosBancarios(pacienteId, dados)` (a criar) ou inline em `pacientes.service.ts`"},{"title":"Layout do card (quando preenchido)","body":"- Grid 80px/1fr: Banco · Agência · Conta+Tipo · Titular\n- Botões \"Editar\" e \"Remover\" no header do card"},{"title":"Layout do drawer","body":"- Largura 480px\n- Campos: Banco (LookupSelect) · Agência · Conta · Tipo (Corrente/Poupança) · Titular (Paciente/Outro) · Nome do titular · CPF do titular\n- Footer: \"Cancelar\" + \"Salvar\""},{"title":"Campos do formulário","body":"| Campo            | Tipo            | Obrig.         | Validação                                  | Mensagem                       |\n|------------------|-----------------|----------------|--------------------------------------------|--------------------------------|\n| Banco            | LookupSelect    | sim            | item ativo de `banco`                      | \"Selecione um banco\"           |\n| Agência          | text            | sim            | até 5 dígitos + 1 dígito verificador      | \"Agência inválida\"             |\n| Conta            | text            | sim            | até 12 dígitos + 1 dígito verificador     | \"Conta inválida\"               |\n| Tipo             | radio           | sim            | \"Corrente\" / \"Poupança\"                    | \"Selecione o tipo\"             |\n| Titular          | radio           | sim            | \"Paciente\" / \"Outro\"                       | —                              |\n| Nome do titular  | text            | se \"Outro\"     | ≥ 3 caracteres                             | \"Informe o nome do titular\"   |\n| CPF do titular   | text            | se \"Outro\"     | dígitos verificadores + ≠ CPF do paciente | \"CPF do titular deve ser diferente\" |"},{"title":"Critérios de aceite","body":"- [ ] Card \"Dados Bancários\" vazio mostra ícone `Landmark` cinza + texto \"Nenhuma conta bancária cadastrada\" + botão \"+ Cadastrar conta\"\n- [ ] Click em \"+ Cadastrar conta\" abre drawer 480px\n- [ ] Lista de bancos vem da tabela auxiliar `banco` (filtrada `ativo = true`)\n- [ ] Quando \"Titular = Outro\", campos extras aparecem (Nome e CPF do titular)\n- [ ] CPF do titular ≠ CPF do paciente → erro inline \"CPF do titular deve ser diferente do paciente\"\n- [ ] \"Salvar\" → drawer fecha → toast verde \"Conta cadastrada\" → card mostra os dados\n- [ ] Card preenchido mostra: Banco (nome) · Agência (mono) · Conta + \" · Corrente/Poupança\" · Titular\n- [ ] Botões \"✎ Editar\" e \"🗑 Remover\" no header do card\n- [ ] \"Editar\" reabre o drawer preenchido\n- [ ] \"Remover\" → modal \"Remover conta bancária?\" → confirma → toast \"Conta removida\""},{"title":"Estados visuais","body":"- **Sem conta**: empty state com botão \"+ Cadastrar conta\"\n- **Com conta**: card preenchido com ações\n- **Saving**: spinner no botão \"Salvar\""},{"title":"Side effects","body":"- INSERT/UPDATE/DELETE em `pacientes_dados_bancarios` (1 row por paciente)\n- Log de auditoria em todas as operações"},{"title":"Regras de negócio","body":"- Apenas 1 conta bancária por paciente (constraint UNIQUE em `paciente_id`)\n- Banco vem da tabela auxiliar `banco` (configurável em `/sistema/configuracoes`)\n- Quando titular é \"Outro\", CPF do titular é obrigatório e diferente do CPF do paciente\n- Edição registra log de auditoria\n- Perfis com permissão `pacientes.dados_bancarios` editam; outros veem read-only (sem botões)"},{"title":"Schema (banco)","body":"- Tabela `pacientes_dados_bancarios` (a criar se ainda não existe):\n  - `id` (uuid)\n  - `paciente_id` (FK pacientes, UNIQUE)\n  - `banco_codigo` (FK tabela auxiliar `banco`)\n  - `agencia`, `conta`, `tipo` (`CORRENTE`/`POUPANCA`)\n  - `titular_tipo` (`PACIENTE`/`OUTRO`)\n  - `titular_nome`, `titular_cpf` (nullable, exigido quando `titular_tipo = OUTRO`)\n  - `created_at`, `updated_at`"},{"title":"Permissões","body":"- `pacientes.dados_bancarios` — editar\n- `pacientes.visualizar` — ver card"},{"title":"Auditoria","body":"- Log: `entity_type='paciente_dados_bancarios'`, actions `create` / `update` / `delete`"},{"title":"Dependências","body":"- US-PAC-04 (card no detalhe)\n- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (categoria `banco`)"}],"criterios":["Card \"Dados Bancários\" vazio mostra ícone `Landmark` cinza + texto \"Nenhuma conta bancária cadastrada\" + botão \"+ Cadastrar conta\"","Click em \"+ Cadastrar conta\" abre drawer 480px","Lista de bancos vem da tabela auxiliar `banco` (filtrada `ativo = true`)","Quando \"Titular = Outro\", campos extras aparecem (Nome e CPF do titular)","CPF do titular ≠ CPF do paciente → erro inline \"CPF do titular deve ser diferente do paciente\"","\"Salvar\" → drawer fecha → toast verde \"Conta cadastrada\" → card mostra os dados","Card preenchido mostra: Banco (nome) · Agência (mono) · Conta + \" · Corrente/Poupança\" · Titular","Botões \"✎ Editar\" e \"🗑 Remover\" no header do card","\"Editar\" reabre o drawer preenchido","\"Remover\" → modal \"Remover conta bancária?\" → confirma → toast \"Conta removida\""],"regras":["Apenas 1 conta bancária por paciente (constraint UNIQUE em `paciente_id`)","Banco vem da tabela auxiliar `banco` (configurável em `/sistema/configuracoes`)","Quando titular é \"Outro\", CPF do titular é obrigatório e diferente do CPF do paciente","Edição registra log de auditoria","Perfis com permissão `pacientes.dados_bancarios` editam; outros veem read-only (sem botões)"],"dependencias":["US-PAC-04 (card no detalhe)","[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (categoria `banco`)"]},{"id":"US-PAC-07","title":"Pool de contas bancárias do paciente","story":"**Como** Atendente TFD, **Quero** cadastrar várias contas bancárias/PIX por paciente (do próprio paciente, pai, mãe, cônjuge, acompanhante etc.), **Para que** eu possa reutilizar essas contas em diferentes ajudas de custo sem redigitar.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/pacientes/[id]/page.tsx` (seção \"Dados Bancários\")\n- Drawer: `src/app/pacientes/_DadosBancariosDrawer.tsx`\n- Serviço: `src/services/dados-bancarios.service.ts`\n- Migration: `00056_pool_dados_bancarios.sql`"},{"title":"Layout","body":"- Card \"Dados bancários\" com lista das contas do paciente (titular, vínculo, banco, agência/conta OU chave PIX)\n- Botão \"+ Nova conta\" abre o `DadosBancariosDrawer`\n- Cada linha tem ícone de lápis (editar) e lixeira (excluir)\n- Drawer com toggle no topo: \"Conta bancária\" / \"PIX\" / \"Ambos\"\n- Campos: Titular (nome), Vínculo (select da tabela auxiliar `vinculo`), CPF do titular, Banco, Agência, Conta, Tipo de conta · Tipo de chave PIX + Chave"},{"title":"Critérios de aceite (visuais)","body":"- [ ] Tela do paciente exibe lista de contas (vazio mostra \"Nenhuma conta cadastrada\")\n- [ ] Botão \"+ Nova conta\" abre drawer em modo create\n- [ ] Toggle \"Conta bancária / PIX / Ambos\" alterna seções visíveis (FormSection)\n- [ ] Lápis abre drawer em modo edit pré-preenchido\n- [ ] Lixeira pede confirmação antes de excluir\n- [ ] Vínculo \"Próprio paciente\" aparece no select"},{"title":"Regras de negócio","body":"- Uma conta = um titular + um vínculo com o paciente\n- Vínculo \"Próprio paciente\" é tratado especialmente (CPF e nome ficam iguais aos do paciente)\n- Conta exige pelo menos um dos blocos preenchidos (bancário OU PIX); \"Ambos\" exige os dois\n- Excluir conta usada por solicitações antigas NÃO apaga o snapshot já congelado nelas\n- Tabela auxiliar de vínculo é `vinculo` (compartilhada com acompanhantes)"},{"title":"Schema (banco)","body":"- Tabela `dados_bancarios` (pool) com FK `paciente_id`\n- Coluna `vinculo` referenciando tabela auxiliar `vinculo`\n- Migration `00056_pool_dados_bancarios.sql` introduz o pool\n- Migration `dedup_dados_bancarios_pool` deduplicou 107 → 30 contas e remapeou as solicitações"},{"title":"Dependências","body":"- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (tabela auxiliar `vinculo`)\n\n---"}],"criterios":["Tela do paciente exibe lista de contas (vazio mostra \"Nenhuma conta cadastrada\")","Botão \"+ Nova conta\" abre drawer em modo create","Toggle \"Conta bancária / PIX / Ambos\" alterna seções visíveis (FormSection)","Lápis abre drawer em modo edit pré-preenchido","Lixeira pede confirmação antes de excluir","Vínculo \"Próprio paciente\" aparece no select"],"regras":["Uma conta = um titular + um vínculo com o paciente","Vínculo \"Próprio paciente\" é tratado especialmente (CPF e nome ficam iguais aos do paciente)","Conta exige pelo menos um dos blocos preenchidos (bancário OU PIX); \"Ambos\" exige os dois","Excluir conta usada por solicitações antigas NÃO apaga o snapshot já congelado nelas","Tabela auxiliar de vínculo é `vinculo` (compartilhada com acompanhantes)"],"dependencias":["[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (tabela auxiliar `vinculo`)","--"]}]}]},{"folder":"EPIC-04-Solicitacoes-TFD","code":"EPIC-04","title":"Solicitações TFD","pendente":false,"features":[{"file":"F01-Listagem-Solicitacoes","code":"F01","title":"Listagem e Busca de Solicitações","description":"Tela principal do TFD: lista de todas as solicitações com busca, filtros por status, ordenação, paginação, 6 cards de KPI clicáveis no topo. É a porta de entrada do atendente, regulador e financeiro para começar/continuar um processo.","meta":[{"key":"Tela","value":"`/fluxo-v2/solicitacoes`"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/fluxo-v2/solicitacoes/page.tsx` · `src/app/fluxo-v2/solicitacoes/_NewSolicitacaoDrawer.tsx`"},{"key":"State","value":"`useFluxoV2State()` em `src/app/fluxo-v2/_state/FluxoV2Provider.tsx` (Context global do fluxo)"},{"key":"Tabela","value":"`solicitacoes`"}],"userStories":[{"id":"US-SOL-01","title":"Visualizar listagem de solicitações","story":"**Como** Atendente TFD, Regulação, Financeiro ou Coordenação, **Quero** ver todas as solicitações TFD em uma tabela, **Para que** eu encontre processos para atuar ou consultar.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/fluxo-v2/solicitacoes/page.tsx`\n- Provider de state: `FluxoV2Provider` (lê do Supabase via `solicitacoesFromSupabase` adapter)\n- StatusBadge: componente compartilhado de badges coloridos por status\n- TipoSolicitacaoBadge: badge \"Normal\" vs \"Ajuda de custo\"\n- Componentes compartilhados: `PageHeader`, `StatsRow`, `SortTh`, `Pagination`, `Skeleton`\n- Drawer: `NewSolicitacaoDrawer`"},{"title":"Layout","body":"- `PageHeader title=\"Solicitações\" subtitle=\"Visão geral de todas as solicitações com seu estado consolidado.\"`\n- Action: \"+ Nova solicitação\" (`tfd-btn-primary`), em `<Can action=\"solicitacoes.criar\">`\n- `StatsRow` com **6 cards** (ver US-SOL-05)\n- Toolbar: busca + select de status\n- Tabela `tfd-table` com 6 colunas"},{"title":"Critérios de aceite","body":"- [ ] Sidebar → \"Solicitações\" → `/fluxo-v2/solicitacoes`\n- [ ] Header title + subtitle conforme acima\n- [ ] Botão \"+ Nova solicitação\" só para `solicitacoes.criar`\n- [ ] Toolbar: campo de busca branco (min-width 280) + select de status (mesma altura 36px)\n- [ ] Tabela com colunas (todas sortable exceto Ações):\n  - **Número** — fonte mono, formato `TFD-{N|AC}-{ano}/{seq}`; chip \"Chegou há Xh\" inline se há tramitação recente\n  - **Paciente** — link azul `#146BFA` para `/pacientes/[id]` com `?from=solicitacoes`; CPF em mono cinza abaixo; idade calculada\n  - **Município / Regional** — município em cima, regional em cinza menor\n  - **Status** — `StatusBadge` colorido (cinza/azul/laranja/verde) + `TipoSolicitacaoBadge` (Normal/Ajuda de custo) ao lado\n  - **Última atualização** — `dd/mm/aaaa · HH:MM`\n  - **Ações** — RowActions com: olho (abrir), kebab com mais opções\n- [ ] Linha inteira é clicável (cursor pointer + hover `#F8FAFC`) → navega para `/fluxo-v2/solicitacoes/[id]?from=solicitacoes`\n- [ ] Click no link do paciente NÃO propaga para a row (stopPropagation)\n- [ ] Paginação rodapé: 25 por página (10/25/50/100)\n- [ ] Estado vazio: \"Nenhuma solicitação encontrada com os filtros atuais\"\n- [ ] Skeleton 6 linhas durante carga inicial"},{"title":"Estados visuais","body":"- **Loading**: skeleton (provider expõe `isLoading`)\n- **Empty**: ícone + texto\n- **Erro de fetch**: toast vermelho"},{"title":"Side effects","body":"- Mudança de busca / filtro / sort → reset página 1\n- \"+ Nova solicitação\" → abre `NewSolicitacaoDrawer` (ver F02)"},{"title":"Regras de negócio","body":"- Lista todas as solicitações (sem filtro por setor do usuário) por default\n- Encerradas aparecem com badge verde\n- Ordenação default: `ultima_atualizacao` desc (mais recente em cima)\n- Cabeçalhos clicáveis: 1 clique = asc, 2 = desc, 3 = remove ordenação\n- Perfis com `solicitacoes.visualizar` acessam"},{"title":"Schema (banco)","body":"- Tabela `solicitacoes` com colunas: `id`, `numero` (mono, único), `status` (enum), `tipo_solicitacao` (`NORMAL`/`AJUDA_CUSTO`), `paciente_id` (FK), `setor_atual` (`dados_basicos`/`regulacao`/`financeiro`), `created_at`, `updated_at`, `numero_sei`, `sei_url`, `tramitacao_atual_*` (JSON com último envio/devolução)\n- Adapter `solicitacoesFromSupabase` converte para `SolicitacaoMock` (modelo do front)"},{"title":"Permissões","body":"- `solicitacoes.visualizar` (guard de rota)\n- `solicitacoes.criar` (botão \"+ Nova\")"},{"title":"Acessibilidade","body":"- Linhas têm `role=\"button\"` + Enter abre o detalhe\n- Headers sortable têm `aria-sort`"},{"title":"Dependências","body":"- [[../EPIC-04-Configuracoes-Administrativo/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]\n\n---"}],"criterios":["Sidebar → \"Solicitações\" → `/fluxo-v2/solicitacoes`","Header title + subtitle conforme acima","Botão \"+ Nova solicitação\" só para `solicitacoes.criar`","Toolbar: campo de busca branco (min-width 280) + select de status (mesma altura 36px)","Tabela com colunas (todas sortable exceto Ações):","**Número** — fonte mono, formato `TFD-{N|AC}-{ano}/{seq}`; chip \"Chegou há Xh\" inline se há tramitação recente","**Paciente** — link azul `#146BFA` para `/pacientes/[id]` com `?from=solicitacoes`; CPF em mono cinza abaixo; idade calculada","**Município / Regional** — município em cima, regional em cinza menor","**Status** — `StatusBadge` colorido (cinza/azul/laranja/verde) + `TipoSolicitacaoBadge` (Normal/Ajuda de custo) ao lado","**Última atualização** — `dd/mm/aaaa · HH:MM`","**Ações** — RowActions com: olho (abrir), kebab com mais opções","Linha inteira é clicável (cursor pointer + hover `#F8FAFC`) → navega para `/fluxo-v2/solicitacoes/[id]?from=solicitacoes`","Click no link do paciente NÃO propaga para a row (stopPropagation)","Paginação rodapé: 25 por página (10/25/50/100)","Estado vazio: \"Nenhuma solicitação encontrada com os filtros atuais\"","Skeleton 6 linhas durante carga inicial"],"regras":["Lista todas as solicitações (sem filtro por setor do usuário) por default","Encerradas aparecem com badge verde","Ordenação default: `ultima_atualizacao` desc (mais recente em cima)","Cabeçalhos clicáveis: 1 clique = asc, 2 = desc, 3 = remove ordenação","Perfis com `solicitacoes.visualizar` acessam"],"dependencias":["[[../EPIC-04-Configuracoes-Administrativo/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]","--"]},{"id":"US-SOL-02","title":"Buscar solicitações","story":"**Como** atendente ou regulador, **Quero** digitar um trecho de texto na busca, **Para que** a tabela filtre instantaneamente os processos relevantes.","sections":[{"title":"Componentes do protótipo","body":"- Input de busca: HTML padrão dentro de container estilizado\n- Lógica de filtro: client-side, dentro do `useMemo` em `solicitacoes/page.tsx`"},{"title":"Critérios de aceite","body":"- [ ] Campo de busca com ícone `Search 14px` cinza à esquerda\n- [ ] Placeholder: \"Buscar por nome, CPF ou número...\"\n- [ ] Debounce de 300ms antes de filtrar\n- [ ] Busca cobre **simultaneamente**: nome do paciente · CPF (com/sem máscara) · número da solicitação (com/sem prefixo)\n- [ ] Aceita CPF `XXX.XXX.XXX-XX` ou `XXXXXXXXXXX`\n- [ ] Aceita número `131`, `2026/000131`, `TFD-N-2026/000131`, `TFD-AC-2026/000131`\n- [ ] Botão X dentro do campo (visível só quando há texto) limpa a busca\n- [ ] Paginação volta para página 1 ao mudar busca\n- [ ] Combina com filtro de status via AND"},{"title":"Estados visuais","body":"- Sem texto: placeholder cinza visível\n- Com texto: X aparece à direita"},{"title":"Regras de negócio","body":"- Case-insensitive\n- Ignora acentuação (normalize NFD)\n- Combina com filtro de status (interseção)"},{"title":"Permissões","body":"- Sem permissão extra (acompanha `solicitacoes.visualizar`)"},{"title":"Dependências","body":"- US-SOL-01\n\n---"}],"criterios":["Campo de busca com ícone `Search 14px` cinza à esquerda","Placeholder: \"Buscar por nome, CPF ou número...\"","Debounce de 300ms antes de filtrar","Busca cobre **simultaneamente**: nome do paciente · CPF (com/sem máscara) · número da solicitação (com/sem prefixo)","Aceita CPF `XXX.XXX.XXX-XX` ou `XXXXXXXXXXX`","Aceita número `131`, `2026/000131`, `TFD-N-2026/000131`, `TFD-AC-2026/000131`","Botão X dentro do campo (visível só quando há texto) limpa a busca","Paginação volta para página 1 ao mudar busca","Combina com filtro de status via AND"],"regras":["Case-insensitive","Ignora acentuação (normalize NFD)","Combina com filtro de status (interseção)"],"dependencias":["US-SOL-01","--"]},{"id":"US-SOL-03","title":"Filtrar por status","story":"**Como** atendente ou regulador, **Quero** filtrar a tabela por status da solicitação, **Para que** eu veja apenas processos do interesse atual.","sections":[{"title":"Componentes do protótipo","body":"- Select HTML padrão\n- Constante `STATUS_OPTIONS` em `solicitacoes/page.tsx`\n- `STATUS_LABEL` em `_state/labels.ts`"},{"title":"Critérios de aceite","body":"- [ ] Select na toolbar (altura 36px, mesma altura da busca)\n- [ ] Opções: \"Todos os status\" · \"Em Dados Básicos\" · \"Em Regulação\" · \"Em Financeiro\" · \"Encerrada\"\n- [ ] Default: \"Todos os status\"\n- [ ] Trocar a seleção filtra a tabela imediatamente\n- [ ] Paginação volta para página 1\n- [ ] Sincronizado com cards de KPI (US-SOL-05): clicar no card aplica o filtro; trocar o select destaca o card correspondente\n- [ ] Combina com busca via AND"},{"title":"Regras de negócio","body":"- Valores no banco: `em_dados_basicos` · `em_regulacao` · `em_financeiro` · `encerrada`\n- \"Todos os status\" remove o filtro"},{"title":"Permissões","body":"- Sem permissão extra"},{"title":"Dependências","body":"- US-SOL-01, US-SOL-05\n\n---"}],"criterios":["Select na toolbar (altura 36px, mesma altura da busca)","Opções: \"Todos os status\" · \"Em Dados Básicos\" · \"Em Regulação\" · \"Em Financeiro\" · \"Encerrada\"","Default: \"Todos os status\"","Trocar a seleção filtra a tabela imediatamente","Paginação volta para página 1","Sincronizado com cards de KPI (US-SOL-05): clicar no card aplica o filtro; trocar o select destaca o card correspondente","Combina com busca via AND"],"regras":["Valores no banco: `em_dados_basicos` · `em_regulacao` · `em_financeiro` · `encerrada`","\"Todos os status\" remove o filtro"],"dependencias":["US-SOL-01, US-SOL-05","--"]},{"id":"US-SOL-04","title":"Ordenar e paginar","story":"**Como** usuário da listagem, **Quero** ordenar por qualquer coluna e navegar entre páginas, **Para que** eu acesse rapidamente o subconjunto que preciso.","sections":[{"title":"Componentes do protótipo","body":"- `SortTh` componente compartilhado com lógica `compareValues` + `nextSort`\n- `Pagination` componente compartilhado"},{"title":"Critérios de aceite","body":"- [ ] Cabeçalhos clicáveis (exceto Ações)\n- [ ] 1º clique = asc (ícone seta cima)\n- [ ] 2º clique = desc (ícone seta baixo)\n- [ ] 3º clique = remove ordenação, volta para default (`ultima_atualizacao` desc)\n- [ ] Apenas 1 coluna ordenada por vez\n- [ ] Rodapé: \"Mostrando X-Y de Z solicitações\" + controles (primeira, anterior, números até 5, próxima, última)\n- [ ] Seletor de tamanho da página: 10 · 25 (default) · 50 · 100\n- [ ] Mudar o tamanho → volta para página 1\n- [ ] Tamanho persiste por sessão (localStorage)"},{"title":"Estados visuais","body":"- Seta visível no header ativo\n- Botão de página corrente destacado"},{"title":"Regras de negócio","body":"- Ordenação client-side dentro do `useMemo`\n- Coluna \"Paciente\" ordena por `paciente.nome`\n- Coluna \"Município / Regional\" ordena por `paciente.municipio`"},{"title":"Dependências","body":"- US-SOL-01\n\n---"}],"criterios":["Cabeçalhos clicáveis (exceto Ações)","1º clique = asc (ícone seta cima)","2º clique = desc (ícone seta baixo)","3º clique = remove ordenação, volta para default (`ultima_atualizacao` desc)","Apenas 1 coluna ordenada por vez","Rodapé: \"Mostrando X-Y de Z solicitações\" + controles (primeira, anterior, números até 5, próxima, última)","Seletor de tamanho da página: 10 · 25 (default) · 50 · 100","Mudar o tamanho → volta para página 1","Tamanho persiste por sessão (localStorage)"],"regras":["Ordenação client-side dentro do `useMemo`","Coluna \"Paciente\" ordena por `paciente.nome`","Coluna \"Município / Regional\" ordena por `paciente.municipio`"],"dependencias":["US-SOL-01","--"]},{"id":"US-SOL-05","title":"Cards de KPI no topo","story":"**Como** Coordenação ou atendente, **Quero** ver contagens rápidas de solicitações por status no topo, **Para que** eu tenha visão do volume de trabalho de cada setor sem abrir filtros.","sections":[{"title":"Componentes do protótipo","body":"- `StatsRow` (`src/shared/components/stats-row/StatsRow.tsx`) com prop `stats: Stat[]`\n- Cada Stat suporta `onClick`, `active`, `hint`, `title`"},{"title":"Layout","body":"- 6 cards em grid responsivo (grid-cols-2 lg:grid-cols-6)\n- Cada card mostra: número grande (24px, font-weight 600) + label menor abaixo (11px uppercase tracking)\n- Hover: borda azul sutil\n- Card ativo: fundo `var(--tfd-blue-50)`, borda azul, número azul"},{"title":"Critérios de aceite","body":"- [ ] 6 cards, na ordem:\n  1. **Total** — não clicável (informativo)\n  2. **Em Dados Básicos** — clicável (toggle filtro)\n  3. **Em Regulação** — clicável\n  4. **Em Financeiro** — clicável\n  5. **Encerradas no mês** — clicável, com hint \"do mês corrente\"\n  6. **Taxa de aprovação** — não clicável, valor com `%`, hint \"deferidos / total\"\n- [ ] Card clicável → aplica filtro de status; clicar de novo no mesmo remove o filtro\n- [ ] Quando filtro está ativo via card, card fica destacado (`active: true`)\n- [ ] \"Encerradas no mês\" combina filtro de status `encerrada` + período (mês corrente)\n- [ ] Cards atualizam quando dados mudam (criar solicitação, mudar status, etc.)\n- [ ] Tooltip no `title` do card explica o filtro (ex.: \"Solicitações encerradas no mês corrente\")"},{"title":"Estados visuais","body":"- **Idle**: card branco com borda cinza\n- **Active**: card azul claro com borda azul + número azul\n- **Hover (não-ativo)**: borda azul sutil"},{"title":"Regras de negócio","body":"- Total = total de solicitações na base (sem filtro)\n- \"Encerradas no mês\": `status = encerrada` AND `encerrada_em` dentro do mês corrente\n- \"Taxa de aprovação\" = `(pareceres deferidos) / (pareceres com decisão)` * 100, arredondado\n- Contagens são derivadas no client a partir do array do provider"},{"title":"Schema (banco)","body":"- Sem queries dedicadas — usa o array `solicitacoes` já carregado pelo provider\n- \"Taxa de aprovação\" precisa de SELECT em `pareceres` (count deferidos / count total com decisão)"},{"title":"Permissões","body":"- Acompanha `solicitacoes.visualizar`"},{"title":"Dependências","body":"- US-SOL-01, US-SOL-03"}],"criterios":["6 cards, na ordem:","Card clicável → aplica filtro de status; clicar de novo no mesmo remove o filtro","Quando filtro está ativo via card, card fica destacado (`active: true`)","\"Encerradas no mês\" combina filtro de status `encerrada` + período (mês corrente)","Cards atualizam quando dados mudam (criar solicitação, mudar status, etc.)","Tooltip no `title` do card explica o filtro (ex.: \"Solicitações encerradas no mês corrente\")"],"regras":["Total = total de solicitações na base (sem filtro)","\"Encerradas no mês\": `status = encerrada` AND `encerrada_em` dentro do mês corrente","\"Taxa de aprovação\" = `(pareceres deferidos) / (pareceres com decisão)` * 100, arredondado","Contagens são derivadas no client a partir do array do provider"],"dependencias":["US-SOL-01, US-SOL-03"]},{"id":"US-SOL-23","title":"Sinalizar tramitações recentes na listagem","story":"**Como** atendente do setor receptor, **Quero** identificar visualmente as solicitações que acabaram de chegar, **Para que** eu priorize trabalhar nelas.","sections":[{"title":"Componentes do protótipo","body":"- Helper: `isTramitacaoRecente(tram)` em `_utils/tramitacao` (janela de 24h fixa)\n- `TramitacaoInfoPopover` em `_components/TramitacaoBadge.tsx`\n- Aplicado na linha da tabela em `solicitacoes/page.tsx`, `regulacao/page.tsx`, `financeiro/page.tsx`"},{"title":"Layout do destaque","body":"- Linha da solicitação com **boxShadow `inset 3px 0 0 0 {cor}`** à esquerda (3px de borda colorida):\n  - Azul (`#94A3B8` ou cor info) para envio recente\n  - Laranja para devolução recente\n- Chip \"Chegou há Xh\" / \"Devolvida há Xh\" ao lado do número\n- Ícone `Info` clicável → popover com detalhes da tramitação"},{"title":"Critérios de aceite","body":"- [ ] Solicitação com `ultima_tramitacao.data` < 24h → linha destacada com borda colorida à esquerda\n- [ ] Chip texto: \"Chegou há Xh\" (envio) ou \"Devolvida há Xh\" (devolução), arredondado em horas (mín 1h)\n- [ ] Ícone `Info` ao lado do chip → click abre popover com:\n  - Tipo de tramitação (envio / devolução)\n  - Autor (nome + perfil)\n  - Data/hora completa\n  - Observação completa\n- [ ] Após 24h o destaque desaparece naturalmente (sem necessidade de ação)\n- [ ] Indicador respeita o setor atual do usuário — Regulação só vê destaque em solicitações que chegaram à Regulação"},{"title":"Estados visuais","body":"- **Envio recente**: borda cinza/azul + chip azul claro\n- **Devolução recente**: borda laranja + chip laranja claro"},{"title":"Regras de negócio","body":"- Janela de 24h é fixa (não configurável no MVP)\n- Dado vem do campo `ultima_tramitacao` (JSON na `solicitacoes`) que armazena o último envio/devolução\n- Quando 2+ tramitações em 24h: mostra a mais recente"},{"title":"Schema (banco)","body":"- `solicitacoes.ultima_tramitacao` (JSONB): `{ tipo, data, autor, perfil, observacao, setor_destino }`"},{"title":"Permissões","body":"- Sem permissão extra — herda da listagem"},{"title":"Dependências","body":"- US-SOL-20, US-SOL-21, US-SOL-22\n- [[F01-Listagem-Solicitacoes|F01 — Listagem]]"}],"criterios":["Solicitação com `ultima_tramitacao.data` < 24h → linha destacada com borda colorida à esquerda","Chip texto: \"Chegou há Xh\" (envio) ou \"Devolvida há Xh\" (devolução), arredondado em horas (mín 1h)","Ícone `Info` ao lado do chip → click abre popover com:","Tipo de tramitação (envio / devolução)","Autor (nome + perfil)","Data/hora completa","Observação completa","Após 24h o destaque desaparece naturalmente (sem necessidade de ação)","Indicador respeita o setor atual do usuário — Regulação só vê destaque em solicitações que chegaram à Regulação"],"regras":["Janela de 24h é fixa (não configurável no MVP)","Dado vem do campo `ultima_tramitacao` (JSON na `solicitacoes`) que armazena o último envio/devolução","Quando 2+ tramitações em 24h: mostra a mais recente"],"dependencias":["US-SOL-20, US-SOL-21, US-SOL-22","[[F01-Listagem-Solicitacoes|F01 — Listagem]]"]}]},{"file":"F02-Cadastro-Solicitacao","code":"F02","title":"Cadastro de Solicitação (Drawer Multi-seção)","description":"Criação de uma nova solicitação TFD no drawer único. Suporta TFD normal e Ajuda de Custo (ambos com ou sem agendamento), múltiplos agendamentos por unidade, acompanhantes com resumo expandido, e múltiplos anexos com tipo de documento classificado.","meta":[{"key":"Tela","value":"`/fluxo-v2/solicitacoes` (drawer `NewSolicitacaoDrawer`)"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/fluxo-v2/solicitacoes/_NewSolicitacaoDrawer.tsx`"},{"key":"State","value":"`useFluxoV2State().createSolicitacao(input)`"},{"key":"Serviços relacionados","value":"`pacientes.service.ts`, `acompanhantes.service.ts`, `tabelas-auxiliares.service.ts`, `unidades-saude.service.ts`"},{"key":"Tabelas","value":"`solicitacoes`, `solicitacao_acompanhantes`, `solicitacao_anexos`, `solicitacao_agendamentos`, `pacientes`"}],"userStories":[{"id":"US-SOL-06","title":"Abrir o drawer de Nova Solicitação","story":"**Como** Atendente TFD, **Quero** clicar em \"+ Nova solicitação\" e ter um drawer pronto para preencher, **Para que** eu inicie o cadastro sem trocar de tela.","sections":[{"title":"Componentes do protótipo","body":"- Drawer: `NewSolicitacaoDrawer` (largura 640px)\n- Trigger: botão no header de `/fluxo-v2/solicitacoes`\n- Foco gerenciado pelo `Drawer` base (`@/shared/components/drawer/Drawer`)"},{"title":"Critérios de aceite","body":"- [ ] Click \"+ Nova solicitação\" → drawer abre da direita, 640px\n- [ ] Title: \"Nova solicitação\" + subtitle \"Preencha os dados para abrir uma solicitação TFD\"\n- [ ] Drawer abre na primeira seção: \"Tipo de solicitação\"\n- [ ] Default: \"TFD Normal\" pré-selecionado\n- [ ] Foco automático no campo de seleção do paciente após render\n- [ ] Footer fixo no rodapé: \"Cancelar\" (cinza) e \"Criar solicitação\" (azul, desabilitado até validações)\n- [ ] Botão só aparece para perfis com `solicitacoes.criar`"},{"title":"Estados visuais","body":"- **Idle**: drawer com campos vazios\n- **Saving**: botão \"Criando...\" com spinner + inputs disabled"},{"title":"Regras de negócio","body":"- Drawer sempre abre em branco (não persiste rascunho)\n- \"Criar solicitação\" só habilita quando todos os obrigatórios estão preenchidos (paciente + agendamento OK)"},{"title":"Permissões","body":"- `solicitacoes.criar`"},{"title":"Acessibilidade","body":"- `role=\"dialog\"` + `aria-modal=\"true\"`\n- Esc fecha (com confirmação se sujou)\n- Foco trap"},{"title":"Dependências","body":"- [[F01-Listagem-Solicitacoes|F01 — Listagem]]\n\n---"}],"criterios":["Click \"+ Nova solicitação\" → drawer abre da direita, 640px","Title: \"Nova solicitação\" + subtitle \"Preencha os dados para abrir uma solicitação TFD\"","Drawer abre na primeira seção: \"Tipo de solicitação\"","Default: \"TFD Normal\" pré-selecionado","Foco automático no campo de seleção do paciente após render","Footer fixo no rodapé: \"Cancelar\" (cinza) e \"Criar solicitação\" (azul, desabilitado até validações)","Botão só aparece para perfis com `solicitacoes.criar`"],"regras":["Drawer sempre abre em branco (não persiste rascunho)","\"Criar solicitação\" só habilita quando todos os obrigatórios estão preenchidos (paciente + agendamento OK)"],"dependencias":["[[F01-Listagem-Solicitacoes|F01 — Listagem]]","--"]},{"id":"US-SOL-07","title":"Selecionar tipo (TFD normal ou Ajuda de Custo)","story":"**Como** atendente, **Quero** escolher logo no início se é TFD normal ou ajuda de custo, **Para que** o resto do fluxo seja coerente com o tipo.","sections":[{"title":"Componentes do protótipo","body":"- 2 cartões clicáveis (não radio buttons) — divs estilizados\n- State local `tipoSolicitacao` (`'normal' | 'ajuda_custo'`)"},{"title":"Layout","body":"- 2 cartões lado a lado em grid 1fr/1fr, gap 8px\n- Cada cartão tem título (12px, 700) + descrição (10px)\n- Cartão ativo: borda âmbar/azul + fundo destacado (`var(--tfd-accent-soft)`)\n- Cartão inativo: borda cinza + fundo branco"},{"title":"Critérios de aceite","body":"- [ ] Cartão \"TFD Normal\" — descrição \"Inclui passagens, ajuda de custo e adicionais\"\n- [ ] Cartão \"Ajuda de Custo\" — descrição \"Paciente já está no destino — só diárias\"\n- [ ] Default: TFD Normal selecionado\n- [ ] Trocar de tipo NÃO limpa os campos já preenchidos (apenas altera lógica downstream)\n- [ ] Ambos os tipos exibem a seção de Agendamento (atualizado em reunião com TFD/SES)"},{"title":"Regras de negócio","body":"- TFD Normal: ciclo completo (DB → Regulação → Financeiro com viagens)\n- Ajuda de Custo: pula emissão de passagens, paciente recebe só diárias\n- Grava em `solicitacoes.tipo_solicitacao` (`NORMAL` ou `AJUDA_CUSTO`)\n- Número da solicitação muda o prefixo: `TFD-N-AAAA/NNNNNN` ou `TFD-AC-AAAA/NNNNNN`"},{"title":"Schema (banco)","body":"- Campo `tipo_solicitacao` na tabela `solicitacoes` (enum)"},{"title":"Dependências","body":"- US-SOL-06\n\n---"}],"criterios":["Cartão \"TFD Normal\" — descrição \"Inclui passagens, ajuda de custo e adicionais\"","Cartão \"Ajuda de Custo\" — descrição \"Paciente já está no destino — só diárias\"","Default: TFD Normal selecionado","Trocar de tipo NÃO limpa os campos já preenchidos (apenas altera lógica downstream)","Ambos os tipos exibem a seção de Agendamento (atualizado em reunião com TFD/SES)"],"regras":["TFD Normal: ciclo completo (DB → Regulação → Financeiro com viagens)","Ajuda de Custo: pula emissão de passagens, paciente recebe só diárias","Grava em `solicitacoes.tipo_solicitacao` (`NORMAL` ou `AJUDA_CUSTO`)","Número da solicitação muda o prefixo: `TFD-N-AAAA/NNNNNN` ou `TFD-AC-AAAA/NNNNNN`"],"dependencias":["US-SOL-06","--"]},{"id":"US-SOL-08","title":"Vincular paciente existente com resumo","story":"**Como** atendente, **Quero** selecionar um paciente cadastrado e ver um resumo dos dados, **Para que** eu confirme que o cadastro está atualizado antes de criar a solicitação.","sections":[{"title":"Componentes do protótipo","body":"- Select HTML (no protótipo atual) — pode ser substituído por autocomplete em iteração futura\n- Componente `ResumoPaciente` (definido na própria página, linha ~880 do drawer)\n- `IdadeBadge` em `@/shared/components/idade-badge`\n- Máscaras: `maskCPF`, `maskCNS`, `maskPhone`, `maskCEP`\n- Ícones: `Pencil`, `MapPin`, `Phone`, `Mail`, `IdCard`"},{"title":"Layout","body":"- Seção \"Paciente\"\n- Linha 1: Select de paciente (label \"Selecionar paciente *\")\n- Linha 2 (quando paciente selecionado): card de resumo"},{"title":"Card de resumo (sempre que há paciente selecionado)","body":"- Header do card: \"RESUMO DO CADASTRO\" (uppercase, 10px, mono) + `IdadeBadge` + link \"✎ Editar cadastro\" no canto direito\n- Grid auto-fit minmax(220px, 1fr) com:\n  - Nome completo · CPF (mono) · CNS (com ícone IdCard, mono) · Sexo\n  - Telefone (com ícone Phone, mono) · E-mail (com ícone Mail) · Município (com ícone MapPin) · Endereço (logradouro+número+bairro, com CEP em mono cinza abaixo)\n- Campos vazios aparecem em itálico cinza: \"Não informado\"\n- Background: `#F8FAFC`, border: 1px sólido cinza claro, border-radius: 10"},{"title":"Critérios de aceite","body":"- [ ] Select com placeholder \"Selecione um paciente...\"\n- [ ] Lista todos os pacientes ativos, ordenados por nome\n- [ ] Cada item mostra \"{nome} — {cpf mascarado}\"\n- [ ] Loading do select quando carrega pacientes: opção desabilitada \"Carregando pacientes...\"\n- [ ] Sem pacientes na base: opção \"Nenhum paciente cadastrado\"\n- [ ] Selecionar paciente → renderiza imediatamente o card de resumo abaixo\n- [ ] Link \"Editar cadastro\" abre `/pacientes/{id}` em nova aba (`target=\"_blank\"`)\n- [ ] Todos os campos do card aparecem (vazios → \"Não informado\" em itálico)\n- [ ] Trocar de paciente atualiza o card e reseta os acompanhantes selecionados"},{"title":"Estados visuais","body":"- Sem paciente: select vazio, card oculto\n- Com paciente: card preenchido"},{"title":"Side effects","body":"- Selecionar paciente dispara fetch de acompanhantes desse paciente (`listarPorPaciente`)\n- Resetar `acompanhanteIds` selecionados ao trocar"},{"title":"Regras de negócio","body":"- Paciente \"encontrado\" reusa o `paciente_id` (não cria novo)\n- ⚠ A US-08 antiga previa busca por CPF — evoluiu para dropdown + card de resumo após pedido do TFD/SES"},{"title":"Schema (banco)","body":"- Reusa `pacientes.id` (FK na `solicitacoes.paciente_id`)"},{"title":"Permissões","body":"- `solicitacoes.criar` (já contempla)"},{"title":"Dependências","body":"- [[../EPIC-01-Cadastros-Fundamentais/F01-Pacientes|F01 — Pacientes]] (base consultada)\n\n---"}],"criterios":["Select com placeholder \"Selecione um paciente...\"","Lista todos os pacientes ativos, ordenados por nome","Cada item mostra \"{nome} — {cpf mascarado}\"","Loading do select quando carrega pacientes: opção desabilitada \"Carregando pacientes...\"","Sem pacientes na base: opção \"Nenhum paciente cadastrado\"","Selecionar paciente → renderiza imediatamente o card de resumo abaixo","Link \"Editar cadastro\" abre `/pacientes/{id}` em nova aba (`target=\"_blank\"`)","Todos os campos do card aparecem (vazios → \"Não informado\" em itálico)","Trocar de paciente atualiza o card e reseta os acompanhantes selecionados"],"regras":["Paciente \"encontrado\" reusa o `paciente_id` (não cria novo)","⚠ A US-08 antiga previa busca por CPF — evoluiu para dropdown + card de resumo após pedido do TFD/SES"],"dependencias":["[[../EPIC-01-Cadastros-Fundamentais/F01-Pacientes|F01 — Pacientes]] (base consultada)","--"]},{"id":"US-SOL-09","title":"Cadastrar novo paciente direto no drawer","story":"**Como** atendente, **Quero** cadastrar um novo paciente sem sair do drawer, **Para que** eu não precise abandonar o fluxo.","sections":[{"title":"Componentes do protótipo","body":"- Botão \"Cadastrar novo paciente\" ao lado/abaixo do select\n- Reutiliza o `PacienteDrawer` da feature F01-Pacientes (sobreposto ao drawer da solicitação)"},{"title":"Critérios de aceite","body":"- [ ] Link/botão \"Cadastrar novo paciente\" abaixo do select de paciente (texto em azul, hover sublinha)\n- [ ] Click abre `PacienteDrawer` por cima (z-index maior)\n- [ ] Cadastro segue as mesmas validações de US-PAC-02\n- [ ] Ao salvar com sucesso → drawer do paciente fecha → paciente novo automaticamente selecionado no drawer da solicitação → card de resumo aparece preenchido\n- [ ] Cancelar cadastro do paciente → volta ao drawer da solicitação sem mudanças"},{"title":"Estados visuais","body":"- Drawer da solicitação fica visível atrás (com leve dim) enquanto o do paciente está aberto"},{"title":"Side effects","body":"- INSERT em `pacientes` (igual US-PAC-02)\n- Lista de pacientes do drawer principal recarrega para incluir o novo"},{"title":"Regras de negócio","body":"- Paciente criado pelo drawer é persistido imediatamente (não fica \"rascunho\")\n- Pode ser usado em qualquer solicitação subsequente sem novo cadastro"},{"title":"Permissões","body":"- `pacientes.criar` E `solicitacoes.criar`"},{"title":"Dependências","body":"- US-SOL-08\n- [[../EPIC-01-Cadastros-Fundamentais/F01-Pacientes|F01 — Pacientes]]\n\n---"}],"criterios":["Link/botão \"Cadastrar novo paciente\" abaixo do select de paciente (texto em azul, hover sublinha)","Click abre `PacienteDrawer` por cima (z-index maior)","Cadastro segue as mesmas validações de US-PAC-02","Ao salvar com sucesso → drawer do paciente fecha → paciente novo automaticamente selecionado no drawer da solicitação → card de resumo aparece preenchido","Cancelar cadastro do paciente → volta ao drawer da solicitação sem mudanças"],"regras":["Paciente criado pelo drawer é persistido imediatamente (não fica \"rascunho\")","Pode ser usado em qualquer solicitação subsequente sem novo cadastro"],"dependencias":["US-SOL-08","[[../EPIC-01-Cadastros-Fundamentais/F01-Pacientes|F01 — Pacientes]]","--"]},{"id":"US-SOL-10","title":"Adicionar e remover acompanhantes","story":"**Como** atendente, **Quero** registrar acompanhantes do paciente no momento do cadastro, **Para que** regulador e financeiro saibam quantas pessoas terão direito a passagem/ajuda.","sections":[{"title":"Componentes do protótipo","body":"- Componente `AcompanhanteCard` (definido na própria página) — lista expandida\n- Modal de criação inline (form dentro do drawer)\n- LookupSelect categoria `vinculo_acompanhante`\n- Serviço: `listarPorPaciente(pacienteId)`, `criarAcompanhante(payload)` em `acompanhantes.service.ts`\n- `calcularIdade` em `@/shared/utils/idade`"},{"title":"Layout da seção","body":"- Header: \"Acompanhantes ({total})\" + link \"+ Novo acompanhante\" (só quando paciente selecionado)\n- Quando sem paciente: card cinza \"Selecione um paciente para listar os acompanhantes cadastrados\"\n- Quando paciente sem acompanhantes: card cinza \"Este paciente não possui acompanhantes cadastrados\"\n- Quando há acompanhantes: lista de `AcompanhanteCard` (cada um clicável como checkbox)"},{"title":"Layout do `AcompanhanteCard`","body":"- Container clicável (label) com checkbox à esquerda + área de dados à direita\n- Borda azul + fundo `#EBF0FF` quando selecionado\n- Linha 1: Nome (negrito) + `IdadeBadge` + chip de vínculo (cinza, uppercase, 10px) + badge âmbar \"Necessidade especial\" se aplicável\n- Linha 2 (sempre visível): CPF · CNS (com ícone) · Telefone (com ícone) — separados por `·` cinza, todos em mono\n- Linha 3 (condicional): descrição da necessidade especial em itálico âmbar"},{"title":"Layout do form inline \"Novo Acompanhante\"","body":"- Aparece ao clicar \"+ Novo acompanhante\"\n- Campos: Nome (obrigatório), CPF (obrigatório, máscara + dígitos verificadores), Nascimento (obrigatório), CNS (opcional), Vínculo (LookupSelect obrigatório), Telefone (obrigatório, máscara)\n- Botões: \"Cancelar\" e \"Salvar acompanhante\""},{"title":"Critérios de aceite","body":"- [ ] Quando paciente menor de idade selecionado + nenhum acompanhante adulto marcado: alerta vermelho bloqueante \"Paciente menor de 18 anos exige ao menos um acompanhante adulto (≥ 18 anos)\"\n- [ ] Checkbox no card alterna seleção do acompanhante para esta solicitação\n- [ ] Selecionar/desselecionar atualiza array `acompanhanteIds`\n- [ ] CPF do acompanhante NÃO pode ser igual ao do paciente nem a outro acompanhante já marcado → erro inline no form de criação\n- [ ] Salvar novo acompanhante → INSERT em `acompanhantes` (vinculado ao paciente) → lista atualiza → novo acompanhante já vem marcado\n- [ ] Cancelar form de criação fecha o form sem salvar"},{"title":"Estados visuais","body":"- **Sem paciente**: estado vazio cinza\n- **Carregando acompanhantes**: spinner + \"Carregando acompanhantes...\"\n- **Lista vazia**: card cinza com call-to-action\n- **Lista preenchida**: cards de acompanhante\n- **Validação menor**: alerta vermelho com ícone `AlertTriangle`"},{"title":"Side effects","body":"- Salvar novo: INSERT em `acompanhantes`\n- Cada acompanhante marcado é salvo em `solicitacao_acompanhantes` no submit da solicitação"},{"title":"Regras de negócio","body":"- Vínculo obrigatório (item da tabela `vinculo_acompanhante`)\n- Acompanhantes ficam vinculados ao paciente (não à solicitação) — listáveis em qualquer solicitação futura do mesmo paciente\n- Marcação acompanhante-solicitação fica em `solicitacao_acompanhantes` (N:N)\n- Paciente menor → exige acompanhante adulto (regra bloqueante)"},{"title":"Schema (banco)","body":"- Tabela `acompanhantes` (N:1 com pacientes)\n- Tabela `solicitacao_acompanhantes` (N:N entre solicitação e acompanhante)"},{"title":"Permissões","body":"- `solicitacoes.criar` (já contempla cadastro do acompanhante inline)"},{"title":"Dependências","body":"- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (`vinculo_acompanhante`)\n\n---"}],"criterios":["Quando paciente menor de idade selecionado + nenhum acompanhante adulto marcado: alerta vermelho bloqueante \"Paciente menor de 18 anos exige ao menos um acompanhante adulto (≥ 18 anos)\"","Checkbox no card alterna seleção do acompanhante para esta solicitação","Selecionar/desselecionar atualiza array `acompanhanteIds`","CPF do acompanhante NÃO pode ser igual ao do paciente nem a outro acompanhante já marcado → erro inline no form de criação","Salvar novo acompanhante → INSERT em `acompanhantes` (vinculado ao paciente) → lista atualiza → novo acompanhante já vem marcado","Cancelar form de criação fecha o form sem salvar"],"regras":["Vínculo obrigatório (item da tabela `vinculo_acompanhante`)","Acompanhantes ficam vinculados ao paciente (não à solicitação) — listáveis em qualquer solicitação futura do mesmo paciente","Marcação acompanhante-solicitação fica em `solicitacao_acompanhantes` (N:N)","Paciente menor → exige acompanhante adulto (regra bloqueante)"],"dependencias":["[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (`vinculo_acompanhante`)","--"]},{"id":"US-SOL-11","title":"Configurar agendamento com múltiplos procedimentos","story":"**Como** atendente, **Quero** selecionar a unidade de destino e cadastrar um ou mais procedimentos (tipo + data), **Para que** a solicitação reflita todos os atendimentos planejados.","sections":[{"title":"Componentes do protótipo","body":"- Hook `useTiposProcedimento()` em `src/shared/hooks/useTiposProcedimento.ts` (lê de `tipo_procedimento` lookup)\n- Select de unidade: `listarUnidadesSaude()` retorna ativas\n- State local `agendamentos: AgendamentoLinha[]` (default 1 linha vazia)\n- Ícones: `CalendarPlus`, `Trash2`"},{"title":"Layout da seção","body":"- Header: \"Agendamento\"\n- Checkbox: \"Solicitação sem agendamento (caso de exceção)\" + texto auxiliar \"Marque apenas quando o paciente ainda não tem unidade/data definidas — o caso seguirá para a Regulação registrar o agendamento posteriormente (CNRAC, CET ou Outros).\"\n- Quando NÃO marcado:\n  - Select \"Selecione a unidade cadastrada\" (header com link \"Cadastrar nova unidade\" → `/unidades-saude`)\n  - Sub-label \"Procedimentos agendados ({total})\"\n  - Lista repetível de linhas com grid 1.4fr/1fr/32px:\n    - Select de Tipo do procedimento (vem de `useTiposProcedimento()`)\n    - Input `type=\"date\"` para data\n    - Botão `Trash2` (limpa se for a única, remove se há mais)\n  - Botão tracejado azul \"+ Adicionar agendamento\" (`CalendarPlus`)"},{"title":"Critérios de aceite","body":"- [ ] Checkbox \"sem agendamento\" desativa toda a seção (unidade + lista)\n- [ ] Select de unidade lista unidades ativas: \"{nome} — CNES {cnes} ({cidade}/{uf})\"\n- [ ] Loading do select: \"Carregando unidades...\"\n- [ ] Lista vazia de unidades: \"Nenhuma unidade cadastrada — clique em 'Cadastrar nova unidade'\"\n- [ ] Tipo do procedimento vem de `tipo_procedimento` (Consulta, Cirurgia, Exame, Hemodiálise, Odontologia, Quimioterapia, Radioterapia, Tratamento Contínuo, etc.)\n- [ ] Loading dos tipos: \"Carregando tipos...\"\n- [ ] Sem tipos cadastrados: \"Nenhum tipo cadastrado\"\n- [ ] Lixeira no item único: limpa os campos (não remove a linha)\n- [ ] Lixeira em itens duplicados: remove a linha (mantém a estrutura geral)\n- [ ] \"+ Adicionar agendamento\" adiciona linha vazia ao final\n- [ ] Hora **NÃO está no formulário** (removido em reunião com TFD/SES)\n- [ ] Validação: para passar de \"Tipo de solicitação\", precisa OU `semAgendamento = true` OU (unidade selecionada AND pelo menos 1 procedimento com tipo+data)\n- [ ] Mesma seção aparece para TFD Normal e Ajuda de Custo"},{"title":"Estados visuais","body":"- Linha completa: inputs preenchidos, dropdown valor selecionado\n- Linha vazia: placeholders cinza"},{"title":"Side effects no save","body":"- INSERT no `solicitacao_agendamentos` (1 row por procedimento)\n- Mesma `unidade_id` para todas as linhas da mesma solicitação"},{"title":"Regras de negócio","body":"- Unidade é única por solicitação (paciente vai a 1 unidade só, mesmo com vários procedimentos)\n- Cada procedimento vira uma \"tentativa confirmada\" no modelo de agendamento da Regulação (ver F03 da regulação)\n- Sem hora cadastrada (apenas data)"},{"title":"Schema (banco)","body":"- Tabela `solicitacao_agendamentos`:\n  - `id`, `solicitacao_id` (FK), `unidade_saude_id` (FK), `tipo_procedimento` (código da lookup), `data_procedimento` (date), `created_at`\n- Tabela auxiliar `tipo_procedimento`"},{"title":"Dependências","body":"- [[../EPIC-01-Cadastros-Fundamentais/F02-Unidades-Saude|F02 — Unidades de Saúde]]\n- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (`tipo_procedimento`)\n\n---"}],"criterios":["Checkbox \"sem agendamento\" desativa toda a seção (unidade + lista)","Select de unidade lista unidades ativas: \"{nome} — CNES {cnes} ({cidade}/{uf})\"","Loading do select: \"Carregando unidades...\"","Lista vazia de unidades: \"Nenhuma unidade cadastrada — clique em 'Cadastrar nova unidade'\"","Tipo do procedimento vem de `tipo_procedimento` (Consulta, Cirurgia, Exame, Hemodiálise, Odontologia, Quimioterapia, Radioterapia, Tratamento Contínuo, etc.)","Loading dos tipos: \"Carregando tipos...\"","Sem tipos cadastrados: \"Nenhum tipo cadastrado\"","Lixeira no item único: limpa os campos (não remove a linha)","Lixeira em itens duplicados: remove a linha (mantém a estrutura geral)","\"+ Adicionar agendamento\" adiciona linha vazia ao final","Hora **NÃO está no formulário** (removido em reunião com TFD/SES)","Validação: para passar de \"Tipo de solicitação\", precisa OU `semAgendamento = true` OU (unidade selecionada AND pelo menos 1 procedimento com tipo+data)","Mesma seção aparece para TFD Normal e Ajuda de Custo"],"regras":["Unidade é única por solicitação (paciente vai a 1 unidade só, mesmo com vários procedimentos)","Cada procedimento vira uma \"tentativa confirmada\" no modelo de agendamento da Regulação (ver F03 da regulação)","Sem hora cadastrada (apenas data)"],"dependencias":["[[../EPIC-01-Cadastros-Fundamentais/F02-Unidades-Saude|F02 — Unidades de Saúde]]","[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (`tipo_procedimento`)","--"]},{"id":"US-SOL-12","title":"Anexar documentos com tipo","story":"**Como** atendente, **Quero** anexar documentos ao cadastrar a solicitação, **Para que** o regulador tenha tudo que precisa para o parecer.","sections":[{"title":"Componentes do protótipo","body":"- Input `<input type=\"file\" multiple>` oculto + botão estilizado para abrir o seletor\n- LookupSelect inline categoria `tipo_documento`\n- State local `anexos: { nome: string; tipo: string; tipoDocumento?: string }[]`\n- Ícones: `Upload`, `Paperclip`, `Trash2`"},{"title":"Layout da seção","body":"- Header: \"Documentos anexos (opcional, múltiplos arquivos)\" + link \"Cadastrar novo tipo\" → `/sistema/configuracoes`\n- Área de drop: tracejado cinza com `Upload 16` + \"Selecionar arquivos\" + texto auxiliar \"Selecione um ou mais arquivos. Pode adicionar mais depois.\"\n- Lista de anexos: cada item em card cinza com `Paperclip` + nome do arquivo + select de Tipo + `Trash2`\n- O select \"Tipo do documento...\" é obrigatório por anexo (no padrão da imagem que o usuário forneceu)"},{"title":"Critérios de aceite","body":"- [ ] Click no botão \"Selecionar arquivos\" → abre seletor nativo do SO (multi-select)\n- [ ] Formatos aceitos: PDF, JPG, JPEG, PNG (extensões + MIME types)\n- [ ] Tamanho máximo: 10MB por arquivo\n- [ ] Arquivo > 10MB → toast vermelho \"Arquivo excede o tamanho máximo de 10MB\"\n- [ ] Formato não aceito → toast vermelho \"Formato não suportado. Use PDF, JPG ou PNG\"\n- [ ] Cada anexo na lista: ícone Paperclip + filename truncado + select de Tipo + Trash2\n- [ ] Select de Tipo: placeholder \"Tipo do documento...\" + opções da lookup `tipo_documento` (Laudo Médico, Exame Complementar, Documento Pessoal, Cartão SUS, Comprovante de Residência, Outros, ...)\n- [ ] Lixeira remove o anexo da lista (sem confirmação)\n- [ ] Múltiplos arquivos podem ser anexados em sequência (botão pode ser usado várias vezes)"},{"title":"Estados visuais","body":"- **Hover na área de drop**: borda azul + fundo `#EFF6FF`\n- **Lista vazia**: oculta\n- **Lista preenchida**: cards de arquivo"},{"title":"Side effects no save","body":"- Upload de cada arquivo para Supabase Storage (bucket `solicitacao-anexos`)\n- INSERT em `solicitacao_anexos` com `nome`, `mime_type`, `tamanho_kb`, `tipo_documento`, `storage_path`"},{"title":"Regras de negócio","body":"- Tipo do documento é **obrigatório** para cada anexo (validação no submit da solicitação)\n- Anexos só são realmente uploadados ao confirmar a solicitação (não há upload prematuro)\n- Anexos podem ser adicionados/removidos depois (ver F03 do detalhe)\n- Documentos gerados pelo sistema (Parecer Médico, Despacho Financeiro) aparecem automaticamente na aba Anexos"},{"title":"Schema (banco)","body":"- Tabela `solicitacao_anexos`: `id`, `solicitacao_id`, `nome`, `mime_type`, `tamanho_kb`, `tipo_documento`, `storage_path`, `criado_por`, `created_at`\n- Storage: bucket `solicitacao-anexos`"},{"title":"Permissões","body":"- `solicitacoes.criar`"},{"title":"Dependências","body":"- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (`tipo_documento`)\n\n---"}],"criterios":["Click no botão \"Selecionar arquivos\" → abre seletor nativo do SO (multi-select)","Formatos aceitos: PDF, JPG, JPEG, PNG (extensões + MIME types)","Tamanho máximo: 10MB por arquivo","Arquivo > 10MB → toast vermelho \"Arquivo excede o tamanho máximo de 10MB\"","Formato não aceito → toast vermelho \"Formato não suportado. Use PDF, JPG ou PNG\"","Cada anexo na lista: ícone Paperclip + filename truncado + select de Tipo + Trash2","Select de Tipo: placeholder \"Tipo do documento...\" + opções da lookup `tipo_documento` (Laudo Médico, Exame Complementar, Documento Pessoal, Cartão SUS, Comprovante de Residência, Outros, ...)","Lixeira remove o anexo da lista (sem confirmação)","Múltiplos arquivos podem ser anexados em sequência (botão pode ser usado várias vezes)"],"regras":["Tipo do documento é **obrigatório** para cada anexo (validação no submit da solicitação)","Anexos só são realmente uploadados ao confirmar a solicitação (não há upload prematuro)","Anexos podem ser adicionados/removidos depois (ver F03 do detalhe)","Documentos gerados pelo sistema (Parecer Médico, Despacho Financeiro) aparecem automaticamente na aba Anexos"],"dependencias":["[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (`tipo_documento`)","--"]},{"id":"US-SOL-24","title":"Drawer da Solicitação mais largo e seção Paciente+Acompanhantes unificada","story":"**Como** Atendente/Regulador editando uma solicitação, **Quero** um drawer mais largo (até 680px) e ver Paciente e Acompanhantes em uma única seção, **Para que** os blocos de 3 colunas (Agendamento e Laudo) caibam sem quebrar e eu enxergue o contexto do paciente junto.","sections":[{"title":"Componentes do protótipo","body":"- Drawer principal: `NewEditarSolicitacaoDrawer` / `_NewSolicitacaoDrawer`\n- FormSection: `src/shared/components/drawer/FormSection.tsx`"},{"title":"Critérios de aceite (visuais)","body":"- [ ] Largura do drawer: `min(680px, 95vw)` (antes: 560px fixo)\n- [ ] Seções \"Paciente\" e \"Acompanhantes\" colapsadas em uma única seção \"Paciente e Acompanhantes\"\n- [ ] Dentro dela há um divider tracejado separando o sub-bloco de acompanhantes\n- [ ] Blocos com 3 colunas (Agendamento, Laudo) não quebram para 1 coluna em desktop"},{"title":"Regras de negócio","body":"- A unificação é puramente visual; os dados continuam separados no banco\n- O divider tracejado é meramente estético, não há toggle de colapsar"},{"title":"Dependências","body":"- [[../../EPIC-09-Design-System-Padroes/F01-FormSection|EPIC-09 F01 — FormSection]]\n\n---"}],"criterios":["Largura do drawer: `min(680px, 95vw)` (antes: 560px fixo)","Seções \"Paciente\" e \"Acompanhantes\" colapsadas em uma única seção \"Paciente e Acompanhantes\"","Dentro dela há um divider tracejado separando o sub-bloco de acompanhantes","Blocos com 3 colunas (Agendamento, Laudo) não quebram para 1 coluna em desktop"],"regras":["A unificação é puramente visual; os dados continuam separados no banco","O divider tracejado é meramente estético, não há toggle de colapsar"],"dependencias":["[[../../EPIC-09-Design-System-Padroes/F01-FormSection|EPIC-09 F01 — FormSection]]","--"]},{"id":"US-SOL-13","title":"Salvar e cancelar","story":"**Como** atendente, **Quero** salvar a solicitação ao final do preenchimento, **Para que** ela entre no fluxo e fique disponível na listagem.","sections":[{"title":"Componentes do protótipo","body":"- `createSolicitacao(input)` no provider\n- Toast: `useToast()` (`@/shared/components/toast/Toast`)\n- `useRouter()` para redirect"},{"title":"Critérios de aceite","body":"- [ ] Botão \"Criar solicitação\" no rodapé do drawer\n- [ ] Botão fica disabled enquanto qualquer obrigatório está vazio ou inválido\n- [ ] Click no botão habilitado: spinner + texto \"Criando...\" + inputs disabled\n- [ ] Sucesso: drawer fecha → toast verde \"Solicitação criada — TFD-{tipo}-AAAA/NNNNNN\" (usa número devolvido) → navega para `/fluxo-v2/solicitacoes/{id}`\n- [ ] Erro de servidor: toast vermelho com mensagem + drawer permanece aberto\n- [ ] \"Cancelar\" com qualquer preenchimento → modal \"Descartar alterações?\" com botões \"Continuar editando\" / \"Descartar\"\n- [ ] \"Cancelar\" sem preenchimento → fecha direto\n- [ ] Esc no drawer = \"Cancelar\""},{"title":"Estados visuais","body":"- **Saving**: botão spinner + form disabled\n- **Sucesso**: drawer fecha animado, toast aparece\n- **Erro**: drawer permanece, toast vermelho"},{"title":"Side effects no sucesso","body":"- Transação atômica:\n  1. INSERT em `solicitacoes` com `status = em_dados_basicos`, `setor_atual = dados_basicos`\n  2. INSERT em `solicitacao_acompanhantes` (1 row por acompanhante marcado)\n  3. INSERT em `solicitacao_agendamentos` (1 row por procedimento)\n  4. Upload + INSERT em `solicitacao_anexos`\n- Log em `audit_logs` (action: `create`)\n- Provider refetch → tabela atualiza\n- Redireciona para detalhe"},{"title":"Regras de negócio","body":"- Solicitação nasce com `status: em_dados_basicos`, `setor_atual: dados_basicos`\n- Número da solicitação: `TFD-{NORMAL→N | AJUDA_CUSTO→AC}-{ano}/{sequencial 6 dígitos}` (sequencial por ano + tipo, gerado por trigger ou função SQL)\n- `criado_por` registra usuário logado\n- Tudo na mesma transação — se qualquer parte falhar, rollback total"},{"title":"Schema (banco)","body":"- INSERT principal em `solicitacoes` + cascata para tabelas filhas"},{"title":"Permissões","body":"- `solicitacoes.criar`"},{"title":"Auditoria","body":"- Log: `entity_type='solicitacao'`, `action='create'`, snapshot completo"},{"title":"Dependências","body":"- US-SOL-06 até US-SOL-12"}],"criterios":["Botão \"Criar solicitação\" no rodapé do drawer","Botão fica disabled enquanto qualquer obrigatório está vazio ou inválido","Click no botão habilitado: spinner + texto \"Criando...\" + inputs disabled","Sucesso: drawer fecha → toast verde \"Solicitação criada — TFD-{tipo}-AAAA/NNNNNN\" (usa número devolvido) → navega para `/fluxo-v2/solicitacoes/{id}`","Erro de servidor: toast vermelho com mensagem + drawer permanece aberto","\"Cancelar\" com qualquer preenchimento → modal \"Descartar alterações?\" com botões \"Continuar editando\" / \"Descartar\"","\"Cancelar\" sem preenchimento → fecha direto","Esc no drawer = \"Cancelar\""],"regras":["Solicitação nasce com `status: em_dados_basicos`, `setor_atual: dados_basicos`","Número da solicitação: `TFD-{NORMAL→N | AJUDA_CUSTO→AC}-{ano}/{sequencial 6 dígitos}` (sequencial por ano + tipo, gerado por trigger ou função SQL)","`criado_por` registra usuário logado","Tudo na mesma transação — se qualquer parte falhar, rollback total"],"dependencias":["US-SOL-06 até US-SOL-12"]}]},{"file":"F03-Detalhe-e-Edicao-Solicitacao","code":"F03","title":"Detalhe e Edição de Solicitação","description":"Tela única do detalhe da solicitação com header rico (status, tipo, número, contato, contagem de anexos) e abas: Linha do tempo · Regulação · Financeiro · Anexos · Observações. Lock por setor controla quem edita o quê.","meta":[{"key":"Tela","value":"`/fluxo-v2/solicitacoes/[id]`"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/fluxo-v2/solicitacoes/[id]/page.tsx` · `src/app/fluxo-v2/_components/AnexosTab.tsx` · `src/app/fluxo-v2/_components/RegulacaoTab.tsx` · `src/app/fluxo-v2/_components/FinanceiroTab.tsx` · `src/app/fluxo-v2/_components/ObservacoesTab.tsx` · `src/app/fluxo-v2/_components/LinhaDoTempoTab.tsx`"},{"key":"State","value":"`useFluxoV2State().getById(id)`, `updateSolicitacao(id, patch)`"},{"key":"Tabelas","value":"`solicitacoes`, `solicitacao_*`"}],"userStories":[{"id":"US-SOL-14","title":"Abrir detalhe","story":"**Como** qualquer usuário autorizado, **Quero** abrir o detalhe completo de uma solicitação, **Para que** eu veja todo o estado do processo e atue nas seções permitidas.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/fluxo-v2/solicitacoes/[id]/page.tsx`\n- Componentes de aba (em `_components/`): `LinhaDoTempoTab`, `RegulacaoTab`, `FinanceiroTab`, `AnexosTab`, `ObservacoesTab`\n- Helpers: `agendamentoConfirmado(s)` em `_utils/agendamento`, `setorAtual(s)` em `_utils/lock`\n- `resolverOrigem(from)` em `@/shared/utils/solicitacaoOrigem` (define link \"Voltar\")\n- Drawer: `EditarDespachoDrawer` (para o detalhe do despacho)"},{"title":"Layout","body":"- **Header** (background branco, border-radius 10, sombra sutil):\n  - Linha 1: nome do paciente (16px, 600, link azul) + idade + CPF (mono cinza)\n    - Botões à direita: \"Enviar para setor\" (`tfd-btn-secondary`) e \"Encerrar solicitação\" (`tfd-btn-danger`)\n  - Linha 2: `StatusBadge` + `TipoSolicitacaoBadge` + \"Solicitação {numero}\" (mono) + \"Criada em {data}\" + ícone SEI (chip)\n  - Linha 3: ícones de Contato (telefone, e-mail) + região + chip \"📎 N anexos\" (clicável → abre aba Anexos) + resumo de acompanhantes\n- **Abas** (border-bottom + abas com underline azul ativo): Linha do tempo (default) · Regulação · Financeiro · Anexos (com badge de contagem) · Observações\n- **Conteúdo da aba ativa**: render do componente correspondente"},{"title":"Critérios de aceite","body":"- [ ] Click na linha da listagem → navega para `/fluxo-v2/solicitacoes/{id}?from=solicitacoes`\n- [ ] Header mostra nome do paciente (link clicável para `/pacientes/{id}?from=solicitacao`)\n- [ ] Link `tel:` no telefone abre app de telefone\n- [ ] Link `mailto:` no e-mail abre cliente de e-mail\n- [ ] Link SEI: se `numeroSEI + seiUrl` preenchidos → ícone `ExternalLink` + \"SEI {numero}\" (mono, azul) abre URL em nova aba; se só `numero` sem URL → chip cinza sem link; se nenhum → chip \"Sem vínculo SEI\" com `FileX` cinza\n- [ ] Chip \"📎 N anexos\" usa `agregarAnexos(s).length` para contar TODOS os documentos (abertura + adicionais + passagens + pareceres + despachos)\n- [ ] Click no chip de anexos → ativa aba Anexos (`?tab=anexos`)\n- [ ] Aba default é \"Linha do tempo\" (`?tab=timeline` no protótipo; sem `?tab` → também default)\n- [ ] Forçar aba via querystring `?tab={timeline|regulacao|financeiro|anexos|observacoes}` funciona\n- [ ] `?tab=dados` (legado) é redirecionado para \"Linha do tempo\" (e param removido da URL)\n- [ ] Botão \"Voltar para {origem}\" no topo respeita `?from=`:\n  - `?from=regulacao` → \"Voltar para Regulação\"\n  - `?from=financeiro` → \"Voltar para Financeiro\"\n  - `?from=solicitacoes` → \"Voltar para Solicitações\"\n- [ ] Solicitação encerrada: banner vermelho no topo + todas as abas read-only"},{"title":"Estados visuais","body":"- **Loading**: `DetailPageSkeleton tabs={5}`\n- **Não encontrada**: mensagem + botão Voltar\n- **Encerrada**: banner com cor `#FEF2F2`, border `#FECACA`, ícone Archive + texto explicativo + botão \"Reabrir solicitação\" (se permitido)"},{"title":"Side effects","body":"- Mudança de aba: atualiza `?tab=` (router.push com scroll: false)\n- \"Encerrar\" → modal de confirmação (US-SOL-XX)\n- \"Enviar para setor\" → abre `EnviarParaSetorDrawer` (F04)"},{"title":"Regras de negócio","body":"- Detalhe acessível a perfis com `solicitacoes.visualizar`\n- Cada aba pode ser ocultada/desabilitada por permissão (ex.: aba Regulação só para perfis de regulação ou maiores)\n- Solicitação encerrada exibe tudo como read-only (lock global, exceto Observações)"},{"title":"Schema (banco)","body":"- SELECT em `solicitacoes` + joins/relacionamentos completos (paciente, acompanhantes, anexos, agendamento, pareceres, viagens, ajudas, adicionais, observações)\n- Provider já carrega tudo no `solicitacoesFromSupabase` adapter"},{"title":"Permissões","body":"- `solicitacoes.visualizar`"},{"title":"Acessibilidade","body":"- Abas com `role=\"tablist\"` + cada aba com `role=\"tab\"` + `aria-selected`\n- Conteúdo de aba com `role=\"tabpanel\"`"},{"title":"Dependências","body":"- [[F01-Listagem-Solicitacoes|F01 — Listagem]]\n\n---"}],"criterios":["Click na linha da listagem → navega para `/fluxo-v2/solicitacoes/{id}?from=solicitacoes`","Header mostra nome do paciente (link clicável para `/pacientes/{id}?from=solicitacao`)","Link `tel:` no telefone abre app de telefone","Link `mailto:` no e-mail abre cliente de e-mail","Link SEI: se `numeroSEI + seiUrl` preenchidos → ícone `ExternalLink` + \"SEI {numero}\" (mono, azul) abre URL em nova aba; se só `numero` sem URL → chip cinza sem link; se nenhum → chip \"Sem vínculo SEI\" com `FileX` cinza","Chip \"📎 N anexos\" usa `agregarAnexos(s).length` para contar TODOS os documentos (abertura + adicionais + passagens + pareceres + despachos)","Click no chip de anexos → ativa aba Anexos (`?tab=anexos`)","Aba default é \"Linha do tempo\" (`?tab=timeline` no protótipo; sem `?tab` → também default)","Forçar aba via querystring `?tab={timeline|regulacao|financeiro|anexos|observacoes}` funciona","`?tab=dados` (legado) é redirecionado para \"Linha do tempo\" (e param removido da URL)","Botão \"Voltar para {origem}\" no topo respeita `?from=`:","`?from=regulacao` → \"Voltar para Regulação\"","`?from=financeiro` → \"Voltar para Financeiro\"","`?from=solicitacoes` → \"Voltar para Solicitações\"","Solicitação encerrada: banner vermelho no topo + todas as abas read-only"],"regras":["Detalhe acessível a perfis com `solicitacoes.visualizar`","Cada aba pode ser ocultada/desabilitada por permissão (ex.: aba Regulação só para perfis de regulação ou maiores)","Solicitação encerrada exibe tudo como read-only (lock global, exceto Observações)"],"dependencias":["[[F01-Listagem-Solicitacoes|F01 — Listagem]]","--"]},{"id":"US-SOL-15","title":"Editar dados básicos","story":"**Como** Atendente TFD (enquanto a solicitação está no setor dados básicos), **Quero** editar paciente, acompanhantes, anexos, tipo e agendamento, **Para que** correções sejam feitas antes de enviar para regulação.","sections":[{"title":"Componentes do protótipo","body":"- Drawer: `EditarDespachoDrawer` (ou similar — drawer de edição completo)\n- Reusa o `NewSolicitacaoDrawer` com flag `mode='edit'`\n- Provider: `updateSolicitacao(id, patch)` em `FluxoV2Provider`"},{"title":"Critérios de aceite","body":"- [ ] Botão \"Editar solicitação\" no header (após o status/tipo/número, ícone `Pencil`)\n- [ ] Click → abre drawer \"Editar solicitação\" com dados preenchidos (mesma estrutura do F02)\n- [ ] CPF do paciente nunca editável\n- [ ] Botão começa disabled (até houver mudança); ativa em \"dirty\"\n- [ ] Save → drawer fecha → toast \"Solicitação atualizada\" → header e abas atualizam\n- [ ] Botão \"Editar solicitação\" desabilitado quando setor atual ≠ `dados_basicos` (lock — ver US-SOL-19)\n- [ ] Tooltip explica o lock: \"Esta solicitação está em {SetorAtual}. Apenas a equipe daquele setor pode editar.\"\n- [ ] Coordenação Estadual e Admin Master: override total (botão sempre habilitado)\n- [ ] Tipo da solicitação NÃO é editável após sair do setor dados básicos"},{"title":"Estados visuais","body":"- Pristine / Dirty / Saving / Erro: idem F01-US-PAC-03"},{"title":"Side effects","body":"- UPDATE em `solicitacoes` + INSERT/UPDATE/DELETE em tabelas filhas\n- Log de auditoria detalhado\n- Provider refetch"},{"title":"Regras de negócio","body":"- Perfis com `solicitacoes.editar` veem o botão (e respeitam o lock)\n- Coordenação Estadual e Admin Master: bypass do lock\n- Mudança de tipo (Normal ↔ Ajuda de Custo) só permitida em DB"},{"title":"Schema (banco)","body":"- UPDATE em `solicitacoes` + cascata para tabelas relacionadas"},{"title":"Permissões","body":"- `solicitacoes.editar`"},{"title":"Auditoria","body":"- Log: `action='update'` com diff por campo"},{"title":"Dependências","body":"- US-SOL-14\n- [[F02-Cadastro-Solicitacao|F02 — Cadastro de Solicitação]] (drawer reutilizado)\n\n---"}],"criterios":["Botão \"Editar solicitação\" no header (após o status/tipo/número, ícone `Pencil`)","Click → abre drawer \"Editar solicitação\" com dados preenchidos (mesma estrutura do F02)","CPF do paciente nunca editável","Botão começa disabled (até houver mudança); ativa em \"dirty\"","Save → drawer fecha → toast \"Solicitação atualizada\" → header e abas atualizam","Botão \"Editar solicitação\" desabilitado quando setor atual ≠ `dados_basicos` (lock — ver US-SOL-19)","Tooltip explica o lock: \"Esta solicitação está em {SetorAtual}. Apenas a equipe daquele setor pode editar.\"","Coordenação Estadual e Admin Master: override total (botão sempre habilitado)","Tipo da solicitação NÃO é editável após sair do setor dados básicos"],"regras":["Perfis com `solicitacoes.editar` veem o botão (e respeitam o lock)","Coordenação Estadual e Admin Master: bypass do lock","Mudança de tipo (Normal ↔ Ajuda de Custo) só permitida em DB"],"dependencias":["US-SOL-14","[[F02-Cadastro-Solicitacao|F02 — Cadastro de Solicitação]] (drawer reutilizado)","--"]},{"id":"US-SOL-16","title":"Anexos (aba dedicada agregada)","story":"**Como** qualquer usuário autorizado, **Quero** ver todos os documentos da solicitação numa aba dedicada, **Para que** eu acesse rapidamente qualquer arquivo do processo.","sections":[{"title":"Componentes do protótipo","body":"- Aba: `AnexosTab` em `src/app/fluxo-v2/_components/AnexosTab.tsx`\n- Helper de agregação: `agregarAnexos(s, opts)` e `ordenarAnexos(itens, desc)` em `src/app/fluxo-v2/_utils/anexosUnificados.ts`\n- Lookup: `useLookup('tipo_documento')` em `src/shared/hooks/useLookup`\n- Serviço de despachos: `buscarPorSolicitacao(id)` em `despachos-financeiros.service`\n- Ícones: `Paperclip`, `Sparkles`, `FileText`, `ExternalLink`, `ArrowDownUp`"},{"title":"Fontes agregadas","body":"- `s.anexos` (abertura/edição)\n- `s.adicionais[].documentoUrl` (comprovantes de adicionais) → classificado como \"Comprovante — {categoria}\"\n- `s.viagens[].bilheteUrl` (bilhetes de passagem) → \"Bilhete de passagem\"\n- `s.pareceres[]` (gerados pelo sistema) → \"Parecer médico\"\n- Despacho financeiro (vindo do Supabase) → \"Despacho financeiro\""},{"title":"Layout","body":"- **Toolbar** (card branco no topo):\n  - Chips de filtro por origem (Todos · Abertura · Adicional · Passagem · Parecer · Despacho) com contagem ao lado de cada\n  - Botão à direita: \"Mais recente primeiro\" / \"Mais antigo primeiro\" (toggle de ordenação) com ícone `ArrowDownUp`\n- **Tabela** (card branco abaixo):\n  - Cabeçalho cinza com colunas: Documento · Tipo · Origem · Data · (ícone)\n  - Cada linha:\n    - Ícone `Sparkles` azul (se gerado pelo sistema) ou `Paperclip` cinza\n    - Nome do arquivo (truncate, 13px, 500)\n    - Tipo do documento (resolvido via lookup, 13px)\n    - `OrigemBadge` (chip colorido)\n    - Data formatada `dd/mm/aaaa` (mono, 12px)\n    - Ícone à direita: `ExternalLink` (rota interna) ou `FileText` (download)\n  - Hover: `#F8FAFC`\n- **Estado vazio**: `Paperclip 28` cinza + \"Nenhum anexo nesta solicitação\" + texto auxiliar"},{"title":"OrigemBadge cores","body":"- Abertura: azul (`#EFF6FF`/`#1D4ED8`)\n- Edição: cinza (`#F1F5F9`/`#475569`)\n- Adicional: âmbar (`#FFFBEB`/`#92400E`)\n- Passagem: verde (`#ECFDF5`/`#047857`)\n- Parecer: violeta (`#F5F3FF`/`#6D28D9`)\n- Despacho: vermelho (`#FEF2F2`/`#B91C1C`)"},{"title":"Critérios de aceite","body":"- [ ] Aba \"Anexos\" tem badge com contagem no label da aba (ex.: \"Anexos (4)\")\n- [ ] Lista agrega todas as 5 fontes\n- [ ] Filtros por origem com contagem dinâmica\n- [ ] Toggle de ordenação alterna asc/desc (default desc)\n- [ ] Click em anexo com `rotaInterna` (despacho) → abre `/despacho/{id}` em nova aba\n- [ ] Click em anexo com `href` (storage) → faz download / abre preview\n- [ ] Estado vazio quando 0 documentos\n- [ ] Adicionar anexos novos **NÃO** acontece nesta aba — só nos drawers de origem (abertura, adicional, passagem)\n- [ ] Tipo de documento resolvido via lookup: códigos viram nomes (ex.: `LAUDO_MEDICO` → \"Laudo Médico\")\n- [ ] Comprovantes de adicionais ficam com tipo \"Comprovante — {Hospedagem/Bagagem/Transfer/...}\""},{"title":"Estados visuais","body":"- **Loading dos despachos**: lista normal renderiza sem despacho (busca async é silenciosa)\n- **Erro de fetch**: ignora (fail silencioso, mantém prototype-safe)"},{"title":"Side effects","body":"- Mudança de filtro/ordenação não muda URL (estado local)\n- Click no chip de anexos no header da solicitação ativa a aba"},{"title":"Regras de negócio","body":"- Aba mostra TODOS os anexos vinculados à solicitação (não só os da abertura)\n- Documentos gerados pelo sistema (parecer, despacho) entram automaticamente — marcados com `Sparkles` azul\n- Adicionar anexo continua no drawer da origem (mantém anexo amarrado ao contexto)\n- Soft delete (mantém para auditoria)"},{"title":"Schema (banco)","body":"- `solicitacao_anexos` (abertura/edição) — fonte principal\n- `adicionais.documento_url` — comprovante embutido\n- `viagens.bilhete_url` — bilhete embutido\n- `pareceres` — gerado dinamicamente\n- `despachos_financeiros` — query via service"},{"title":"Permissões","body":"- `solicitacoes.visualizar` (apenas leitura na aba)"},{"title":"Dependências","body":"- US-SOL-14\n\n---"}],"criterios":["Aba \"Anexos\" tem badge com contagem no label da aba (ex.: \"Anexos (4)\")","Lista agrega todas as 5 fontes","Filtros por origem com contagem dinâmica","Toggle de ordenação alterna asc/desc (default desc)","Click em anexo com `rotaInterna` (despacho) → abre `/despacho/{id}` em nova aba","Click em anexo com `href` (storage) → faz download / abre preview","Estado vazio quando 0 documentos","Adicionar anexos novos **NÃO** acontece nesta aba — só nos drawers de origem (abertura, adicional, passagem)","Tipo de documento resolvido via lookup: códigos viram nomes (ex.: `LAUDO_MEDICO` → \"Laudo Médico\")","Comprovantes de adicionais ficam com tipo \"Comprovante — {Hospedagem/Bagagem/Transfer/...}\""],"regras":["Aba mostra TODOS os anexos vinculados à solicitação (não só os da abertura)","Documentos gerados pelo sistema (parecer, despacho) entram automaticamente — marcados com `Sparkles` azul","Adicionar anexo continua no drawer da origem (mantém anexo amarrado ao contexto)","Soft delete (mantém para auditoria)"],"dependencias":["US-SOL-14","--"]},{"id":"US-SOL-17","title":"Observações (chat)","story":"**Como** qualquer usuário do fluxo, **Quero** registrar observações em formato de chat dentro da solicitação, **Para que** a comunicação entre setores fique documentada no processo.","sections":[{"title":"Componentes do protótipo","body":"- Aba: `ObservacoesTab` em `_components/ObservacoesTab.tsx`\n- Componente `StatusDot` (com tom semântico por perfil)\n- `tempoRelativo`, `fmtDataHora` em `_utils/derivarLinhaDoTempo`\n- Provider: `addObservacao(id, texto)`"},{"title":"Layout","body":"- **Lista de mensagens** (área scrollável, ordenação asc — mais antigas em cima):\n  - Avatar do autor (com `StatusDot` colorido por perfil — info/warning/etc.)\n  - Nome do autor (negrito) + badge de perfil (Coordenação/Regulação/Financeiro/etc.)\n  - Data/hora formatada (humanizada — \"há 2 horas\", \"ontem\")\n  - Texto da mensagem (suporta múltiplas linhas)\n- **Rodapé fixo** (sticky bottom):\n  - Textarea com placeholder \"Escreva uma mensagem...\"\n  - Botão \"Enviar\" (`Send` ícone, azul, disabled se vazio)\n- Estado vazio: ícone `MessagesSquare` + \"Sem observações ainda. Use este espaço para alinhar com outros setores.\""},{"title":"Critérios de aceite","body":"- [ ] Aba \"Observações\" sempre acessível (qualquer perfil com acesso à solicitação)\n- [ ] Lista ordenada cronologicamente asc (mais antiga em cima)\n- [ ] Cada mensagem: avatar circular cinza + nome + chip de perfil + tempo + texto\n- [ ] Perfis com cores semânticas: Coordenação Estadual=info, Regulação=info, Financeiro=warning, Atendente=neutral\n- [ ] Textarea no rodapé com placeholder\n- [ ] Enter envia a mensagem\n- [ ] Shift+Enter quebra linha (não envia)\n- [ ] Após envio: mensagem aparece imediatamente + campo limpa\n- [ ] Mensagens são imutáveis (não há editar/apagar no MVP)\n- [ ] Auto-scroll para o final ao enviar nova mensagem"},{"title":"Estados visuais","body":"- **Vazio**: ícone + mensagem + textarea\n- **Com mensagens**: lista + textarea\n- **Enviando**: botão spinner"},{"title":"Side effects","body":"- INSERT em `solicitacao_observacoes` com `autor`, `perfil_autor`, `texto`, `data`\n- Provider refetch (ou append no estado local)\n- Sem notificação automática (apenas registro)"},{"title":"Regras de negócio","body":"- Qualquer perfil com acesso à solicitação pode enviar (não há lock)\n- Observações são vinculadas à solicitação (FK)\n- Texto livre, sem limite de tamanho explícito (default DB text)"},{"title":"Schema (banco)","body":"- Tabela `solicitacao_observacoes`: `id`, `solicitacao_id` (FK), `autor` (nome), `perfil_autor`, `texto`, `data`"},{"title":"Permissões","body":"- `solicitacoes.visualizar` (leitura E escrita)"},{"title":"Dependências","body":"- US-SOL-14\n\n---"}],"criterios":["Aba \"Observações\" sempre acessível (qualquer perfil com acesso à solicitação)","Lista ordenada cronologicamente asc (mais antiga em cima)","Cada mensagem: avatar circular cinza + nome + chip de perfil + tempo + texto","Perfis com cores semânticas: Coordenação Estadual=info, Regulação=info, Financeiro=warning, Atendente=neutral","Textarea no rodapé com placeholder","Enter envia a mensagem","Shift+Enter quebra linha (não envia)","Após envio: mensagem aparece imediatamente + campo limpa","Mensagens são imutáveis (não há editar/apagar no MVP)","Auto-scroll para o final ao enviar nova mensagem"],"regras":["Qualquer perfil com acesso à solicitação pode enviar (não há lock)","Observações são vinculadas à solicitação (FK)","Texto livre, sem limite de tamanho explícito (default DB text)"],"dependencias":["US-SOL-14","--"]},{"id":"US-SOL-18","title":"Linha do tempo","story":"**Como** Coordenação ou Auditoria, **Quero** ver todas as ações que aconteceram na solicitação em ordem cronológica, **Para que** eu reconstrua o histórico do processo para análise ou auditoria.","sections":[{"title":"Componentes do protótipo","body":"- Aba: `LinhaDoTempoTab` em `_components/LinhaDoTempoTab.tsx`\n- Helper: `derivarLinhaDoTempo(s)` em `_utils/derivarLinhaDoTempo.ts` (combina logs + eventos de domínio)"},{"title":"Layout","body":"- Lista vertical de eventos com timeline visual (linha cinza à esquerda + pontos)\n- Cada evento (card):\n  - Ícone do tipo (à esquerda, dentro de círculo colorido)\n  - Tempo relativo (mono, cinza, ex.: \"há 3h\", \"ontem\", \"12/05/2026\")\n  - Descrição do evento (ex.: \"Enviada para Regulação\", \"Parecer emitido — Deferido\")\n  - Autor (nome + perfil em chip cinza)\n- Filtro multi-select no topo: Criação · Edição · Parecer · Tramitação · Financeiro · Encerramento"},{"title":"Tipos de evento","body":"- **Criação**: ícone `Plus`, cor verde\n- **Edição**: ícone `Pencil`, cor cinza\n- **Parecer**: ícone `Stethoscope`, cor violeta\n- **Tramitação (envio)**: ícone `Send`, cor azul\n- **Tramitação (devolução)**: ícone `RotateCcw`, cor laranja\n- **Financeiro**: ícone `Wallet`, cor laranja\n- **Encerramento**: ícone `Archive`, cor vermelha"},{"title":"Critérios de aceite","body":"- [ ] Lista vertical com timeline visual\n- [ ] Eventos ordenados desc (mais recentes no topo)\n- [ ] Eventos importantes (mudança de setor, parecer, encerramento) têm destaque (borda colorida ou fundo levemente tingido)\n- [ ] Filtro por tipo de evento (multi-select) no topo\n- [ ] Estado vazio: \"Sem eventos registrados ainda.\" (raro)\n- [ ] Tempo relativo até 24h (\"há Xh\"), depois absoluto (\"12/05/2026\")\n- [ ] Clicar em evento de tramitação abre popover com observação completa\n- [ ] Clicar em evento de parecer abre `/parecer/{id}` em nova aba"},{"title":"Estados visuais","body":"- Loading: skeleton de 4 eventos\n- Vazio: mensagem cinza centralizada"},{"title":"Regras de negócio","body":"- Eventos vêm de:\n  - `audit_logs` (criação, edição)\n  - `pareceres` (cada parecer = 1 evento)\n  - `solicitacao_tramitacoes` (envio/devolução entre setores)\n  - `solicitacao_encerramentos`\n- Eventos não podem ser editados/removidos pelo usuário\n- Acessível a perfis com `solicitacoes.visualizar`"},{"title":"Schema (banco)","body":"- Múltiplas tabelas (ver acima) consolidadas via VIEW ou função SQL"},{"title":"Permissões","body":"- `solicitacoes.visualizar`"},{"title":"Dependências","body":"- US-SOL-14\n- [[../EPIC-04-Configuracoes-Administrativo/F04-Logs-Auditoria|F04 — Logs de Auditoria]]\n\n---"}],"criterios":["Lista vertical com timeline visual","Eventos ordenados desc (mais recentes no topo)","Eventos importantes (mudança de setor, parecer, encerramento) têm destaque (borda colorida ou fundo levemente tingido)","Filtro por tipo de evento (multi-select) no topo","Estado vazio: \"Sem eventos registrados ainda.\" (raro)","Tempo relativo até 24h (\"há Xh\"), depois absoluto (\"12/05/2026\")","Clicar em evento de tramitação abre popover com observação completa","Clicar em evento de parecer abre `/parecer/{id}` em nova aba"],"regras":["Eventos vêm de:","`audit_logs` (criação, edição)","`pareceres` (cada parecer = 1 evento)","`solicitacao_tramitacoes` (envio/devolução entre setores)","`solicitacao_encerramentos`","Eventos não podem ser editados/removidos pelo usuário","Acessível a perfis com `solicitacoes.visualizar`"],"dependencias":["US-SOL-14","[[../EPIC-04-Configuracoes-Administrativo/F04-Logs-Auditoria|F04 — Logs de Auditoria]]","--"]},{"id":"US-SOL-19","title":"Lock por setor","story":"**Como** usuário do TFD, **Quero** que o sistema mostre claramente quando posso ou não editar algo, **Para que** eu não tente fazer ações que serão bloqueadas.","sections":[{"title":"Componentes do protótipo","body":"- Helpers: `isLocked(s, setorUsuario)`, `tooltipLocked(s, setorUsuario)`, `setorAtual(s)` em `_utils/lock.ts`\n- Verifica `s.status` e `s.setor_atual` vs setor do usuário\n- Override para perfis de Coordenação Estadual e Admin Master via permissões"},{"title":"Critérios de aceite","body":"- [ ] Botões de edição em cada aba ficam cinza/disabled quando setor atual ≠ setor do usuário\n- [ ] Tooltip no hover do botão disabled: \"Esta solicitação está em {SetorAtual}. Apenas a equipe daquele setor pode editar.\"\n- [ ] Solicitação encerrada: TODOS os botões de edição cinza com tooltip \"Solicitação encerrada — somente leitura.\"\n- [ ] Coordenação Estadual e Admin Master: bypass total (todos os botões habilitados em qualquer setor)\n- [ ] Visualização é sempre livre (qualquer perfil com `solicitacoes.visualizar`)\n- [ ] Lock se aplica a:\n  - Editar dados básicos (US-SOL-15)\n  - Anexar/remover documentos (US-SOL-16) — exceto pelos drawers de origem\n  - Registrar parecer / carimbo / tentativa / agendamento (Regulação)\n  - Cadastrar passagem / ajuda / adicional (Financeiro)\n- [ ] Observações NÃO têm lock (qualquer setor envia)\n- [ ] Tramitação tem permissão própria (`tramitacao.tramitar` / `tramitacao.devolver`)"},{"title":"Estados visuais","body":"- **Habilitado**: botão padrão (azul ou neutro)\n- **Locked**: botão cinza com cursor `not-allowed`\n- **Encerrada**: banner global vermelho + todos os botões locked"},{"title":"Regras de negócio","body":"- Setor do usuário derivado do perfil (Atendente → DB, Regulador → Regulação, Financeiro → Financeiro, Coord/Admin → todos)\n- Status `encerrada` trumpa setor (tudo locked, exceto Observações)\n- Override para Coord Estadual e Admin Master"},{"title":"Schema (banco)","body":"- Sem schema dedicado — lógica no client com base em `status` e `setor_atual` + permissões"},{"title":"Permissões","body":"- Permissões usadas: `solicitacoes.editar`, `regulacao.emitir_parecer`, `financeiro.criar_passagem`, etc.\n- Override por permissão: `solicitacoes.editar_qualquer_setor` (atribuída a Coord/Admin)"},{"title":"Dependências","body":"- US-SOL-15, US-SOL-16\n- [[F04-Tramitacao-Entre-Setores|F04 — Tramitação Entre Setores]]\n- [[../EPIC-04-Configuracoes-Administrativo/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]"}],"criterios":["Botões de edição em cada aba ficam cinza/disabled quando setor atual ≠ setor do usuário","Tooltip no hover do botão disabled: \"Esta solicitação está em {SetorAtual}. Apenas a equipe daquele setor pode editar.\"","Solicitação encerrada: TODOS os botões de edição cinza com tooltip \"Solicitação encerrada — somente leitura.\"","Coordenação Estadual e Admin Master: bypass total (todos os botões habilitados em qualquer setor)","Visualização é sempre livre (qualquer perfil com `solicitacoes.visualizar`)","Lock se aplica a:","Editar dados básicos (US-SOL-15)","Anexar/remover documentos (US-SOL-16) — exceto pelos drawers de origem","Registrar parecer / carimbo / tentativa / agendamento (Regulação)","Cadastrar passagem / ajuda / adicional (Financeiro)","Observações NÃO têm lock (qualquer setor envia)","Tramitação tem permissão própria (`tramitacao.tramitar` / `tramitacao.devolver`)"],"regras":["Setor do usuário derivado do perfil (Atendente → DB, Regulador → Regulação, Financeiro → Financeiro, Coord/Admin → todos)","Status `encerrada` trumpa setor (tudo locked, exceto Observações)","Override para Coord Estadual e Admin Master"],"dependencias":["US-SOL-15, US-SOL-16","[[F04-Tramitacao-Entre-Setores|F04 — Tramitação Entre Setores]]","[[../EPIC-04-Configuracoes-Administrativo/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]"]}]},{"file":"F04-Tramitacao-Entre-Setores","code":"F04","title":"Tramitação entre Setores","description":"A solicitação caminha entre 3 setores (Dados Básicos → Regulação → Financeiro) e pode voltar (devolução). Cada envio e devolução gera registro auditável e marca a linha na tabela do setor destino com destaque temporário.","meta":[{"key":"Tela","value":"`/fluxo-v2/solicitacoes/[id]` (botões \"Enviar para…\" e \"Devolver para…\")"},{"key":"Drawer","value":"`EnviarParaSetorDrawer`"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/fluxo-v2/_components/drawers/EnviarParaSetorDrawer.tsx` · `src/app/fluxo-v2/_utils/tramitacao.ts`"},{"key":"State","value":"`enviarParaSetor(id, destino, observacao, tipo)` em `FluxoV2Provider`"},{"key":"Tabelas","value":"`solicitacoes` (status + setor_atual + ultima_tramitacao) · `solicitacao_tramitacoes` · `solicitacao_devolucoes`"}],"userStories":[{"id":"US-SOL-20","title":"Enviar de Dados Básicos para Regulação","story":"**Como** Atendente TFD, **Quero** marcar uma solicitação como pronta e enviá-la para regulação, **Para que** o regulador receba o processo e emita o parecer.","sections":[{"title":"Componentes do protótipo","body":"- Drawer: `EnviarParaSetorDrawer` (largura 480px)\n- Validação de pré-requisitos: função `prerequisitosParaRegulacao(s)` em `_utils/tramitacao`\n- Provider: `enviarParaSetor(id, 'regulacao', observacao, 'enviar')`\n- Ícones: `Send`, `CheckCircle2`, `XCircle`"},{"title":"Layout do drawer","body":"- Title: \"Enviar para Regulação\"\n- Subtitle: \"{numero} — {nome do paciente}\"\n- Seção \"Checklist de pré-requisitos\":\n  - Linha por pré-requisito: ícone verde `CheckCircle2` (OK) ou ícone vermelho `XCircle` (faltando) + texto\n- Seção \"Observação para a Regulação (opcional)\": textarea grande\n- Footer: \"Cancelar\" + \"Enviar\" (desabilitado se algum pré-requisito falta)"},{"title":"Pré-requisitos","body":"| Item                       | Validação                                                     | Mensagem se faltando                        |\n|----------------------------|---------------------------------------------------------------|---------------------------------------------|\n| Paciente completo          | nome, CPF, sexo, data nascimento, município preenchidos       | \"Complete o cadastro do paciente\"           |\n| Laudo médico anexado       | ao menos 1 anexo com `tipo_documento = LAUDO_MEDICO`         | \"Anexe ao menos 1 laudo médico\"             |\n| Acompanhante (se menor)    | paciente < 18 → ao menos 1 acompanhante adulto marcado        | \"Paciente menor precisa de acompanhante adulto\" |"},{"title":"Critérios de aceite","body":"- [ ] Botão \"Enviar para Regulação\" só aparece quando `status = em_dados_basicos`\n- [ ] Click → drawer 480px da direita\n- [ ] Title + subtitle com número e nome do paciente\n- [ ] Checklist exibe cada pré-requisito com ícone verde (OK) ou vermelho (falta)\n- [ ] Itens faltando: texto cinza + tooltip explica o que falta\n- [ ] Itens OK: texto preto + ícone verde\n- [ ] Textarea \"Observação para a Regulação\" (placeholder \"Caso prioritário, observações para o regulador...\"), opcional\n- [ ] Botão \"Enviar\" disabled enquanto algum pré-requisito falta + tooltip \"Atenda aos pré-requisitos para enviar\"\n- [ ] Botão habilitado: ícone `Send` + texto \"Enviar\"\n- [ ] Confirma → spinner → drawer fecha → toast verde \"Solicitação enviada para Regulação\" → navega para `/fluxo-v2/solicitacoes` (volta para listagem)\n- [ ] Cancel / Esc → drawer fecha sem ação"},{"title":"Estados visuais","body":"- **Pré-req faltando**: botão Enviar disabled + cor cinza\n- **Tudo OK**: botão Enviar azul ativo\n- **Enviando**: spinner"},{"title":"Side effects","body":"- UPDATE em `solicitacoes`: `status = 'em_regulacao'`, `setor_atual = 'regulacao'`, `ultima_tramitacao = JSON(...)`\n- INSERT em `solicitacao_tramitacoes`: `tipo='envio_regulacao'`, `destino='regulacao'`, `autor`, `perfil`, `data`, `observacao`\n- Log em `audit_logs`\n- Listagem da Regulação destaca a nova solicitação por 24h (chip azul \"Chegou há Xh\") — ver US-SOL-23"},{"title":"Regras de negócio","body":"- Permissão `tramitacao.tramitar` no setor de origem (Dados Básicos)\n- Pré-requisitos obrigatórios bloqueiam o envio\n- Tramitação registra: tipo, destino, autor, perfil, data, observação\n- Coordenação Estadual: pode forçar envio mesmo sem pré-requisitos (com confirmação extra)"},{"title":"Schema (banco)","body":"- UPDATE `solicitacoes`\n- INSERT `solicitacao_tramitacoes`:\n  - `id`, `solicitacao_id`, `tipo`, `origem`, `destino`, `autor_id`, `autor_nome`, `autor_perfil`, `observacao`, `created_at`"},{"title":"Permissões","body":"- `tramitacao.tramitar` (em DB)"},{"title":"Auditoria","body":"- Log: `entity_type='solicitacao'`, `action='send_to_regulacao'`, snapshot incluindo destino e observação"},{"title":"Dependências","body":"- [[F03-Detalhe-e-Edicao-Solicitacao|F03 — Detalhe e Edição]]\n\n---"}],"criterios":["Botão \"Enviar para Regulação\" só aparece quando `status = em_dados_basicos`","Click → drawer 480px da direita","Title + subtitle com número e nome do paciente","Checklist exibe cada pré-requisito com ícone verde (OK) ou vermelho (falta)","Itens faltando: texto cinza + tooltip explica o que falta","Itens OK: texto preto + ícone verde","Textarea \"Observação para a Regulação\" (placeholder \"Caso prioritário, observações para o regulador...\"), opcional","Botão \"Enviar\" disabled enquanto algum pré-requisito falta + tooltip \"Atenda aos pré-requisitos para enviar\"","Botão habilitado: ícone `Send` + texto \"Enviar\"","Confirma → spinner → drawer fecha → toast verde \"Solicitação enviada para Regulação\" → navega para `/fluxo-v2/solicitacoes` (volta para listagem)","Cancel / Esc → drawer fecha sem ação"],"regras":["Permissão `tramitacao.tramitar` no setor de origem (Dados Básicos)","Pré-requisitos obrigatórios bloqueiam o envio","Tramitação registra: tipo, destino, autor, perfil, data, observação","Coordenação Estadual: pode forçar envio mesmo sem pré-requisitos (com confirmação extra)"],"dependencias":["[[F03-Detalhe-e-Edicao-Solicitacao|F03 — Detalhe e Edição]]","--"]},{"id":"US-SOL-21","title":"Enviar de Regulação para Financeiro","story":"**Como** Regulador, **Quero** enviar a solicitação para o Financeiro depois de emitir o parecer, **Para que** o Financeiro emita passagens e/ou ajuda de custo.","sections":[{"title":"Componentes do protótipo","body":"- Mesmo `EnviarParaSetorDrawer`, com destino `financeiro`\n- Provider: `enviarParaSetor(id, 'financeiro', observacao, 'enviar')`"},{"title":"Layout do drawer","body":"- Title: \"Enviar para Financeiro\"\n- Seção \"Resumo do parecer\": card cinza com decisão (Deferido/Indeferido) + data + médico responsável (read-only)\n- Seção \"Observação para o Financeiro (opcional)\": textarea\n- Pré-requisitos: ao menos 1 parecer emitido + (opcional) carimbo definido se aplicável\n- Footer: \"Cancelar\" + \"Enviar\""},{"title":"Critérios de aceite","body":"- [ ] Botão \"Enviar para Financeiro\" só quando `status = em_regulacao`\n- [ ] Drawer com resumo do último parecer\n- [ ] Pré-requisito: ao menos 1 parecer com decisão (deferido OU indeferido)\n- [ ] Quando parecer = \"indeferido\": aviso laranja \"Esta solicitação será encerrada após o envio (indeferimento). Confirme antes de prosseguir.\"\n- [ ] Confirma → `status = 'em_financeiro'` (se deferido) OU encerra automaticamente (se indeferido) → toast → redireciona"},{"title":"Estados visuais","body":"- **Sem parecer**: botão Enviar disabled + aviso \"Registre o parecer médico antes de enviar\"\n- **Indeferido**: aviso laranja antes do botão\n- **Deferido**: confirmação padrão"},{"title":"Side effects","body":"- Se deferido: UPDATE `status='em_financeiro'`, `setor_atual='financeiro'`\n- Se indeferido: UPDATE `status='encerrada'`, registra encerramento automático com motivo \"Parecer indeferido\"\n- INSERT em `solicitacao_tramitacoes` com `tipo='envio_financeiro'`\n- Log de auditoria"},{"title":"Regras de negócio","body":"- Parecer indeferido → solicitação **encerra** após envio (não vai realmente para o Financeiro emitir nada)\n- Parecer deferido → vai para Financeiro normalmente\n- Permissão `tramitacao.tramitar` em Regulação"},{"title":"Schema (banco)","body":"- UPDATE em `solicitacoes`\n- INSERT em `solicitacao_tramitacoes`\n- (Se indeferido) INSERT em `solicitacao_encerramentos`"},{"title":"Permissões","body":"- `tramitacao.tramitar` (em Regulação)"},{"title":"Auditoria","body":"- Log: `action='send_to_financeiro'` ou `action='encerrar_por_indeferimento'`"},{"title":"Dependências","body":"- [[../EPIC-03-Regulacao-Parecer-Medico/F01-Parecer-Medico|F01 — Parecer Médico]]\n\n---"}],"criterios":["Botão \"Enviar para Financeiro\" só quando `status = em_regulacao`","Drawer com resumo do último parecer","Pré-requisito: ao menos 1 parecer com decisão (deferido OU indeferido)","Quando parecer = \"indeferido\": aviso laranja \"Esta solicitação será encerrada após o envio (indeferimento). Confirme antes de prosseguir.\"","Confirma → `status = 'em_financeiro'` (se deferido) OU encerra automaticamente (se indeferido) → toast → redireciona"],"regras":["Parecer indeferido → solicitação **encerra** após envio (não vai realmente para o Financeiro emitir nada)","Parecer deferido → vai para Financeiro normalmente","Permissão `tramitacao.tramitar` em Regulação"],"dependencias":["[[../EPIC-03-Regulacao-Parecer-Medico/F01-Parecer-Medico|F01 — Parecer Médico]]","--"]},{"id":"US-SOL-22","title":"Devolver para o setor anterior","story":"**Como** Regulador ou Financeiro, **Quero** devolver uma solicitação quando há pendência, **Para que** o setor anterior corrija algo que me impede de seguir.","sections":[{"title":"Componentes do protótipo","body":"- Mesmo `EnviarParaSetorDrawer`, com `tipo='devolver'`\n- Categorias predefinidas no select\n- Provider: `enviarParaSetor(id, setorAnterior, observacao, 'devolver')`"},{"title":"Layout do drawer","body":"- Title: \"Devolver para {SetorAnterior}\"\n- Seção \"Motivo da devolução\":\n  - Select de categoria (obrigatório): \"Documentação incompleta\" · \"Dados inconsistentes\" · \"Falta de informação clínica\" · \"Outro\"\n  - Textarea de detalhamento (obrigatório, mín. 10 caracteres; quando \"Outro\", obrigatório ainda mais detalhado)\n- Footer: \"Cancelar\" + \"Devolver\" (vermelho)"},{"title":"Critérios de aceite","body":"- [ ] Botão \"Devolver para {SetorAnterior}\" no header com ícone `RotateCcw` ou seta para trás\n- [ ] Disabled se setor atual ≠ setor do usuário\n- [ ] Drawer 480px com title contextualizado pelo setor anterior\n- [ ] Categoria é obrigatória (placeholder \"Selecione o motivo...\")\n- [ ] Textarea com placeholder \"Descreva detalhadamente o que precisa ser corrigido...\" (mín. 10 caracteres validado on-blur)\n- [ ] \"Outro\" exige descrição ainda mais detalhada (recomendação visual: \"Descreva o motivo com clareza\")\n- [ ] Confirma → spinner → drawer fecha → toast laranja \"Devolvida para {SetorAnterior}\" → navega para listagem\n- [ ] Listagem do setor receptor mostra a linha com borda laranja + chip \"Devolvida há Xh\""},{"title":"Estados visuais","body":"- **Sem motivo / detalhe curto**: botão Devolver disabled\n- **OK**: botão Devolver vermelho ativo\n- **Enviando**: spinner"},{"title":"Side effects","body":"- UPDATE em `solicitacoes`: volta `status` e `setor_atual` para o anterior\n- INSERT em `solicitacao_devolucoes`: `motivo`, `categoria`, `autor`, `perfil`, `data`, `setor_origem`, `setor_destino`\n- INSERT em `solicitacao_tramitacoes` com `tipo='devolucao'`\n- Log de auditoria"},{"title":"Regras de negócio","body":"- Devolução só permite voltar **1 nível**:\n  - `em_regulacao` → `em_dados_basicos`\n  - `em_financeiro` → `em_regulacao`\n- Histórico de devoluções fica visível na Linha do Tempo\n- Permissão `tramitacao.devolver` no setor remetente\n- Coordenação Estadual: override para forçar devolução de qualquer setor para qualquer outro"},{"title":"Schema (banco)","body":"- UPDATE `solicitacoes`\n- INSERT `solicitacao_devolucoes`:\n  - `id`, `solicitacao_id`, `categoria` (enum), `motivo` (text), `autor_id`, `setor_origem`, `setor_destino`, `created_at`"},{"title":"Permissões","body":"- `tramitacao.devolver`\n- `solicitacoes.devolver_qualquer_setor` (override de Coord Estadual)"},{"title":"Auditoria","body":"- Log: `entity_type='solicitacao'`, `action='devolver'`, com categoria + motivo no diff"},{"title":"Dependências","body":"- US-SOL-20, US-SOL-21\n\n---"}],"criterios":["Botão \"Devolver para {SetorAnterior}\" no header com ícone `RotateCcw` ou seta para trás","Disabled se setor atual ≠ setor do usuário","Drawer 480px com title contextualizado pelo setor anterior","Categoria é obrigatória (placeholder \"Selecione o motivo...\")","Textarea com placeholder \"Descreva detalhadamente o que precisa ser corrigido...\" (mín. 10 caracteres validado on-blur)","\"Outro\" exige descrição ainda mais detalhada (recomendação visual: \"Descreva o motivo com clareza\")","Confirma → spinner → drawer fecha → toast laranja \"Devolvida para {SetorAnterior}\" → navega para listagem","Listagem do setor receptor mostra a linha com borda laranja + chip \"Devolvida há Xh\""],"regras":["Devolução só permite voltar **1 nível**:","`em_regulacao` → `em_dados_basicos`","`em_financeiro` → `em_regulacao`","Histórico de devoluções fica visível na Linha do Tempo","Permissão `tramitacao.devolver` no setor remetente","Coordenação Estadual: override para forçar devolução de qualquer setor para qualquer outro"],"dependencias":["US-SOL-20, US-SOL-21","--"]}]}]},{"folder":"EPIC-05-Regulacao","code":"EPIC-05","title":"Regulação (Parecer, Carimbo, Tentativas, Agendamento)","pendente":true,"features":[{"file":"F01-Parecer-Medico","code":"F01","title":"Parecer Médico","description":"Drawer do médico regulador para emitir parecer (deferido / indeferido) usando templates oficiais. Inclui resumo da solicitação com documentos, CIDs (CID-10 ou CID-11) com autocomplete, variante \"serviço no MA\" para deferidos, área de observação ampla, e card de identificação do médico com snapshot.","meta":[{"key":"Tela","value":"`/fluxo-v2/solicitacoes/[id]` (aba Regulação, drawer `NewParecerDrawer`)"},{"key":"Status","value":"✅ Validado pelo setor"},{"key":"Arquivos-chave","value":"`src/app/fluxo-v2/_components/drawers/NewParecerDrawer.tsx` · `src/app/fluxo-v2/_components/RegulacaoTab.tsx` · `src/core/templates/templates-parecer.ts`"},{"key":"State","value":"`addParecer(id, p)`, `editarParecer(id, parecerId, patch)`, `removerParecer(id, parecerId)` em `FluxoV2Provider`"},{"key":"Serviços CID","value":"`buscarCid10(query)`, `buscarCid11(query)` em `cids.service.ts`"},{"key":"Tabelas","value":"`pareceres`"}],"userStories":[{"id":"US-PAR-01","title":"Abrir o drawer de Novo Parecer","story":"**Como** Médico Regulador, **Quero** abrir o drawer de parecer a partir do detalhe da solicitação, **Para que** eu registre minha decisão clínica.","sections":[{"title":"Componentes do protótipo","body":"- Drawer: `NewParecerDrawer` (largura 560px)\n- Trigger: botão \"+ Novo parecer\" na seção \"Pareceres médicos\" da aba Regulação\n- Auth: hook `useAuth()` para snapshot do médico"},{"title":"Layout do trigger","body":"- Na aba Regulação, seção \"Pareceres médicos\" tem header com título + contagem + botão \"+ Novo parecer\"\n- Botão estilo `tfd-btn-primary` (violeta no contexto da regulação)"},{"title":"Critérios de aceite","body":"- [ ] Botão \"+ Novo parecer\" no header da seção \"Pareceres médicos\"\n- [ ] Click → drawer 560px abre da direita\n- [ ] Title: \"Novo parecer médico\"\n- [ ] Subtitle: \"Decisão, CIDs e observações do médico regulador.\"\n- [ ] Foco inicial no segmented control da decisão\n- [ ] Botão \"+ Novo parecer\" desabilitado se setor atual ≠ `regulacao` (lock) OU sem permissão\n- [ ] Tooltip do botão desabilitado: \"Esta solicitação está em {SetorAtual}\" ou \"Você não tem permissão para emitir parecer\""},{"title":"Estados visuais","body":"- **Lock por setor**: botão cinza + tooltip explicativo\n- **Sem perfil completo (médico sem CRM)**: drawer abre mas card de médico mostra alerta amarelo bloqueando o salvar"},{"title":"Regras de negócio","body":"- Permissão `regulacao.emitir_parecer` (Médico Regulador · Coordenação Médica · Admin Master)\n- Admin Master pode emitir mesmo sem CRM (atua como suporte)\n- Demais perfis precisam ter `medico_crm`, `medico_crm_uf`, `medico_especialidade` no perfil — drawer bloqueia salvar se faltar\n- Múltiplos pareceres por solicitação são permitidos (histórico)"},{"title":"Permissões","body":"- `regulacao.emitir_parecer`"},{"title":"Acessibilidade","body":"- `role=\"dialog\"` + `aria-modal=\"true\"` + `aria-labelledby=\"parecer-drawer-title\"`\n- Foco trap"},{"title":"Dependências","body":"- [[../EPIC-02-Solicitacoes-TFD/F03-Detalhe-e-Edicao-Solicitacao|F03 — Detalhe e Edição]]\n- [[../EPIC-04-Configuracoes-Administrativo/F02-Usuarios|F02 — Usuários]] (campos CRM/UF/Especialidade no perfil)\n\n---"}],"criterios":["Botão \"+ Novo parecer\" no header da seção \"Pareceres médicos\"","Click → drawer 560px abre da direita","Title: \"Novo parecer médico\"","Subtitle: \"Decisão, CIDs e observações do médico regulador.\"","Foco inicial no segmented control da decisão","Botão \"+ Novo parecer\" desabilitado se setor atual ≠ `regulacao` (lock) OU sem permissão","Tooltip do botão desabilitado: \"Esta solicitação está em {SetorAtual}\" ou \"Você não tem permissão para emitir parecer\""],"regras":["Permissão `regulacao.emitir_parecer` (Médico Regulador · Coordenação Médica · Admin Master)","Admin Master pode emitir mesmo sem CRM (atua como suporte)","Demais perfis precisam ter `medico_crm`, `medico_crm_uf`, `medico_especialidade` no perfil — drawer bloqueia salvar se faltar","Múltiplos pareceres por solicitação são permitidos (histórico)"],"dependencias":["[[../EPIC-02-Solicitacoes-TFD/F03-Detalhe-e-Edicao-Solicitacao|F03 — Detalhe e Edição]]","[[../EPIC-04-Configuracoes-Administrativo/F02-Usuarios|F02 — Usuários]] (campos CRM/UF/Especialidade no perfil)","--"]},{"id":"US-PAR-02","title":"Visualizar resumo da solicitação no drawer","story":"**Como** Médico Regulador, **Quero** ver os dados-chave do paciente, acompanhantes e documentos no topo do drawer, **Para que** eu emita o parecer sem precisar fechar o drawer e abrir o detalhe.","sections":[{"title":"Componentes do protótipo","body":"- Card \"Resumo da solicitação\" — definido inline no `NewParecerDrawer`\n- Link \"↗ Abrir solicitação\" no canto do card"},{"title":"Layout do card","body":"- Background: `#FAFAF7`, border: 1px sólido, border-radius: 4\n- Header do card: \"RESUMO DA SOLICITAÇÃO\" (mono, 10px, uppercase) + link \"↗ Abrir em nova aba\" à direita\n- Grid 1fr/1fr com:\n  - Paciente (nome) · Sexo / Idade\n  - CPF · Data nascimento\n  - Município · Data do laudo\n- Bloco \"Acompanhantes\" (oculto se vazio): contagem + lista compacta de nomes + vínculos\n- Bloco \"Documentos\" (sempre): contagem + lista de arquivos clicáveis\n  - Laudos identificados por nome contendo \"laudo\" (case-insensitive) recebem badge azul \"Laudo\"\n  - Cada doc é link → abre em nova aba"},{"title":"Critérios de aceite","body":"- [ ] Card aparece logo abaixo do título do drawer\n- [ ] Grid 2 colunas com os 6 campos listados\n- [ ] Acompanhantes: se 0, bloco oculto; se ≥1, mostra contagem + lista\n- [ ] Documentos: contagem + lista (ordenados com laudos primeiro)\n- [ ] Cada documento mostra ícone + nome (truncate) + tamanho (KB)\n- [ ] Click no documento abre em nova aba (PDF) ou modal de preview (imagem)\n- [ ] Sem documentos: bloco mostra \"Nenhum documento anexado. Atenção: laudo costuma ser obrigatório.\" (em laranja)\n- [ ] Link \"↗ Abrir solicitação\" abre `/fluxo-v2/solicitacoes/{id}` em nova aba"},{"title":"Estados visuais","body":"- **Acompanhantes vazios**: bloco oculto\n- **Documentos vazios**: aviso laranja no bloco\n- **Laudo presente**: badge azul destaca o arquivo"},{"title":"Regras de negócio","body":"- Card é read-only no drawer; correções de paciente só pelo atendente em Dados Básicos\n- \"Laudo\" é detectado por substring \"laudo\" no nome do arquivo (case-insensitive)\n- Acompanhantes ocultos se não houver nenhum"},{"title":"Permissões","body":"- `regulacao.emitir_parecer` (já contempla visualização do resumo)"},{"title":"Dependências","body":"- US-PAR-01\n\n---"}],"criterios":["Card aparece logo abaixo do título do drawer","Grid 2 colunas com os 6 campos listados","Acompanhantes: se 0, bloco oculto; se ≥1, mostra contagem + lista","Documentos: contagem + lista (ordenados com laudos primeiro)","Cada documento mostra ícone + nome (truncate) + tamanho (KB)","Click no documento abre em nova aba (PDF) ou modal de preview (imagem)","Sem documentos: bloco mostra \"Nenhum documento anexado. Atenção: laudo costuma ser obrigatório.\" (em laranja)","Link \"↗ Abrir solicitação\" abre `/fluxo-v2/solicitacoes/{id}` em nova aba"],"regras":["Card é read-only no drawer; correções de paciente só pelo atendente em Dados Básicos","\"Laudo\" é detectado por substring \"laudo\" no nome do arquivo (case-insensitive)","Acompanhantes ocultos se não houver nenhum"],"dependencias":["US-PAR-01","--"]},{"id":"US-PAR-03","title":"Escolher decisão Deferido ou Indeferido","story":"**Como** Médico Regulador, **Quero** escolher de forma clara se estou deferindo ou indeferindo o pedido, **Para que** a decisão fique inequívoca no parecer.","sections":[{"title":"Componentes do protótipo","body":"- Segmented control (não radio) — 2 botões grandes lado a lado\n- State `decisao` (`'deferido' | 'indeferido'`)\n- Cor de feedback visual:\n  - Deferido: borda `#15803D`, bg `#DCFCE7` (ativo) ou bg branco (inativo)\n  - Indeferido: borda `#B91C1C`, bg `#FEE2E2` (ativo) ou bg branco (inativo)"},{"title":"Layout","body":"- Container com 2 botões grid 1fr/1fr, gap 6px, padding 4, background `#F8F8F4`, border-radius 6\n- Cada botão: 10px de padding, font-weight 600, 13px"},{"title":"Critérios de aceite","body":"- [ ] 2 botões \"✓ Deferido\" e \"✕ Indeferido\" lado a lado\n- [ ] Botão ativo tem cor de fundo destacada (verde claro para deferido, vermelho claro para indeferido)\n- [ ] Botão inativo é branco com texto cinza\n- [ ] Default: \"Deferido\" pré-selecionado ao abrir\n- [ ] Trocar de decisão NÃO limpa o texto da observação (médico mantém o que digitou)\n- [ ] Trocar para \"Indeferido\" oculta a seção \"Situação do serviço no MA\" (US-PAR-04)\n- [ ] Trocar para \"Deferido\" mostra a seção novamente"},{"title":"Estados visuais","body":"- **Deferido ativo**: fundo verde claro\n- **Indeferido ativo**: fundo vermelho claro\n- **Inativos**: brancos com texto cinza"},{"title":"Regras de negócio","body":"- Apenas 2 valores: `deferido` ou `indeferido`\n- Cada decisão tem um template oficial específico\n- Mudança de decisão NÃO substitui o texto automaticamente (médico decide se reinsere o template)"},{"title":"Schema (banco)","body":"- Campo `decisao` na tabela `pareceres` (enum `deferido` / `indeferido`)"},{"title":"Dependências","body":"- US-PAR-01\n\n---"}],"criterios":["2 botões \"✓ Deferido\" e \"✕ Indeferido\" lado a lado","Botão ativo tem cor de fundo destacada (verde claro para deferido, vermelho claro para indeferido)","Botão inativo é branco com texto cinza","Default: \"Deferido\" pré-selecionado ao abrir","Trocar de decisão NÃO limpa o texto da observação (médico mantém o que digitou)","Trocar para \"Indeferido\" oculta a seção \"Situação do serviço no MA\" (US-PAR-04)","Trocar para \"Deferido\" mostra a seção novamente"],"regras":["Apenas 2 valores: `deferido` ou `indeferido`","Cada decisão tem um template oficial específico","Mudança de decisão NÃO substitui o texto automaticamente (médico decide se reinsere o template)"],"dependencias":["US-PAR-01","--"]},{"id":"US-PAR-04","title":"Selecionar variante de serviço no MA (somente Deferido)","story":"**Como** Médico Regulador, **Quero** indicar se o Maranhão tem ou não unidade habilitada para o tratamento, **Para que** o template do parecer use o parágrafo correto sem que eu precise editar manualmente.","sections":[{"title":"Componentes do protótipo","body":"- Select HTML com 2 opções\n- State `varianteServicoMA` (`'nao_dispoe' | 'dispoe_com_justificativa'`)\n- Visibilidade condicional ao valor de `decisao`"},{"title":"Layout","body":"- Seção \"Situação do serviço no Maranhão\" abaixo da seção Decisão\n- Select de largura 100%\n- Texto auxiliar abaixo: \"Define qual parágrafo entra no template ao clicar em 'Inserir template'.\"\n- Quando `decisao === 'indeferido'`: seção inteira escondida (display none)"},{"title":"Critérios de aceite","body":"- [ ] Seção aparece quando `decisao === 'deferido'`\n- [ ] Seção oculta quando `decisao === 'indeferido'`\n- [ ] Select com 2 opções:\n  - \"Maranhão NÃO dispõe de unidade habilitada\" (value: `nao_dispoe`)\n  - \"Maranhão dispõe, mas há justificativa para deslocamento\" (value: `dispoe_com_justificativa`)\n- [ ] Default: \"NÃO dispõe\"\n- [ ] Texto auxiliar visível abaixo do select\n- [ ] Mudar a variante NÃO atualiza o texto da observação automaticamente — só ao clicar \"Inserir template\" novamente"},{"title":"Regras de negócio","body":"- A variante substitui o placeholder `{{servico_ma}}` no template do parecer ao clicar \"Inserir template\"\n- Cada variante tem um parágrafo distinto, conforme template oficial em `templates-parecer.ts`\n- Indeferido tem template único, sem variantes"},{"title":"Schema (banco)","body":"- Não persistida diretamente; embarcada no texto final do parecer"},{"title":"Dependências","body":"- US-PAR-03, US-PAR-05\n\n---"}],"criterios":["Seção aparece quando `decisao === 'deferido'`","Seção oculta quando `decisao === 'indeferido'`","Select com 2 opções:","\"Maranhão NÃO dispõe de unidade habilitada\" (value: `nao_dispoe`)","\"Maranhão dispõe, mas há justificativa para deslocamento\" (value: `dispoe_com_justificativa`)","Default: \"NÃO dispõe\"","Texto auxiliar visível abaixo do select","Mudar a variante NÃO atualiza o texto da observação automaticamente — só ao clicar \"Inserir template\" novamente"],"regras":["A variante substitui o placeholder `{{servico_ma}}` no template do parecer ao clicar \"Inserir template\"","Cada variante tem um parágrafo distinto, conforme template oficial em `templates-parecer.ts`","Indeferido tem template único, sem variantes"],"dependencias":["US-PAR-03, US-PAR-05","--"]},{"id":"US-PAR-05","title":"Inserir template e editar texto","story":"**Como** Médico Regulador, **Quero** clicar em \"Inserir template\" e ter o texto pré-preenchido com os dados do paciente, **Para que** eu só precise ajustar o que é específico (diagnóstico, tratamento).","sections":[{"title":"Componentes do protótipo","body":"- Botão \"+ Inserir template\" no header da seção \"Observação\"\n- Templates em `src/core/templates/templates-parecer.ts` (constantes versionadas no código)\n- Função `aplicarTemplate(decisao, variante, paciente, solicitacao)` que substitui placeholders"},{"title":"Layout","body":"- Seção \"Observação do parecer\":\n  - Header com label + botão \"+ Inserir template\" à direita\n  - Textarea grande (mín. 320px altura, 16 linhas, resizável verticalmente)"},{"title":"Placeholders substituídos","body":"| Placeholder                       | Substituído por                          |\n|-----------------------------------|------------------------------------------|\n| `{{paciente.nome}}`               | Nome do paciente                         |\n| `{{paciente.sexo}}`               | \"masculino\" / \"feminino\"                 |\n| `{{paciente.dataNascimento}}`     | Data formatada DD/MM/AAAA                |\n| `{{paciente.municipio}}`          | Município do paciente                    |\n| `{{solicitacao.dataLaudo}}`       | Data do laudo formatada (ou \"—\")         |\n| `{{servico_ma}}`                  | Parágrafo da variante (só em Deferido)   |"},{"title":"Campos não substituídos (permanecem para o médico preencher)","body":"- `[DIAGNÓSTICO]`\n- `[LOCAL DE TRATAMENTO]`\n- `[CONDUTA RECOMENDADA]`\n- (outros conforme template)"},{"title":"Critérios de aceite","body":"- [ ] Botão \"+ Inserir template\" no canto direito do header da seção Observação\n- [ ] Click → textarea recebe o template correspondente (`deferido + variante` ou `indeferido`)\n- [ ] Placeholders `{{}}` são substituídos pelos dados do paciente\n- [ ] Placeholders `[]` permanecem como estão (caixa alta entre colchetes)\n- [ ] Insert sobrescreve texto anterior sem confirmação (intencional — para iteração rápida)\n- [ ] Textarea redimensionável verticalmente (resize: vertical)\n- [ ] Médico edita livremente após inserir\n- [ ] Médico pode digitar do zero sem usar template"},{"title":"Estados visuais","body":"- **Vazio**: textarea com placeholder \"Digite ou clique em 'Inserir template'...\"\n- **Preenchido**: texto branco com quebras de linha preservadas"},{"title":"Regras de negócio","body":"- 2 templates oficiais:\n  - `deferido` (com placeholder `{{servico_ma}}` que vira o parágrafo da variante)\n  - `indeferido` (texto único)\n- Templates ficam em `templates-parecer.ts` no repo — versionados junto com o código\n- Atualizar templates exige deploy (intencional — texto oficial controlado)"},{"title":"Schema (banco)","body":"- Campo `observacao` na tabela `pareceres` (text, sem limite)"},{"title":"Dependências","body":"- US-PAR-03, US-PAR-04\n\n---"}],"criterios":["Botão \"+ Inserir template\" no canto direito do header da seção Observação","Click → textarea recebe o template correspondente (`deferido + variante` ou `indeferido`)","Placeholders `{{}}` são substituídos pelos dados do paciente","Placeholders `[]` permanecem como estão (caixa alta entre colchetes)","Insert sobrescreve texto anterior sem confirmação (intencional — para iteração rápida)","Textarea redimensionável verticalmente (resize: vertical)","Médico edita livremente após inserir","Médico pode digitar do zero sem usar template"],"regras":["2 templates oficiais:","`deferido` (com placeholder `{{servico_ma}}` que vira o parágrafo da variante)","`indeferido` (texto único)","Templates ficam em `templates-parecer.ts` no repo — versionados junto com o código","Atualizar templates exige deploy (intencional — texto oficial controlado)"],"dependencias":["US-PAR-03, US-PAR-04","--"]},{"id":"US-PAR-06","title":"Registrar CIDs principal e secundário","story":"**Como** Médico Regulador, **Quero** buscar e selecionar CIDs (principal e opcional secundário) com código + descrição, **Para que** o registro fique completo e legível sem precisar decorar códigos.","sections":[{"title":"Componentes do protótipo","body":"- Toggle pill \"CID-10 / CID-11\" no topo da seção\n- Autocomplete: componente `CidAutocomplete` (a criar) com debounce 300ms\n- Serviços: `buscarCid10(query)`, `buscarCid11(query)` em `cids.service.ts`\n- State: `versaoCID`, `cidPrincipal`, `cidPrincipalNome`, `cidSecundario`, `cidSecundarioNome`\n- Chip do CID selecionado: chip violeta com `código · descrição` + X para limpar"},{"title":"Layout","body":"- Seção \"CIDs\":\n  - Header: label \"CIDs\" + pills CID-10 (ativo, fundo branco com borda violeta) / CID-11 (inativo, fundo cinza)\n  - Campo \"CID principal\":\n    - Input com placeholder \"Buscar código ou descrição (CID-{versão})\"\n    - Quando selecionado: chip violeta abaixo com código + descrição + X\n  - Campo \"CID secundário (opcional)\": mesmo padrão"},{"title":"Critérios de aceite","body":"- [ ] Toggle CID-10/CID-11 no topo (default CID-10)\n- [ ] Trocar versão limpa os CIDs selecionados (com confirmação se houver valor)\n- [ ] Autocomplete: ao digitar, lista de sugestões com:\n  - Código em destaque (mono, azul)\n  - Descrição abaixo (texto menor)\n- [ ] Selecionar item → input limpa + chip violeta aparece abaixo com `{código} · {descrição}` + X\n- [ ] Click no X do chip limpa o CID (volta ao estado vazio)\n- [ ] Autocompletes têm mesma altura/fonte/border que outros selects (13px)\n- [ ] CID secundário tem label \"(opcional)\" em cinza ao lado\n- [ ] Salvar sem nenhum CID é permitido (não-obrigatórios)\n- [ ] Pesquisas mínimas: 2 caracteres para disparar busca"},{"title":"Estados visuais","body":"- **Vazio**: input com placeholder\n- **Buscando**: spinner pequeno à direita do input\n- **Selecionado**: chip violeta com X\n- **Sem resultados**: dropdown mostra \"Nenhum CID encontrado para '{termo}'\""},{"title":"Side effects no save","body":"- 4 campos persistidos: `cid_principal`, `cid_principal_nome`, `cid_secundario`, `cid_secundario_nome`"},{"title":"Regras de negócio","body":"- 4 campos no banco para flexibilidade\n- Texto do parecer NÃO é auto-preenchido com o CID — médico digita o diagnóstico manualmente\n- CID-10 e CID-11 vêm de fontes diferentes (`cids.service` decide qual API consultar)\n- Trocar a versão limpa os campos (visões diferentes)"},{"title":"Schema (banco)","body":"- Tabela `pareceres`:\n  - `cid_principal` (text, nullable, ex.: `C50.9`)\n  - `cid_principal_nome` (text, nullable)\n  - `cid_secundario` (text, nullable)\n  - `cid_secundario_nome` (text, nullable)\n  - `versao_cid` (`'10' | '11'`, default `'10'`)"},{"title":"Dependências","body":"- US-PAR-01\n\n---"}],"criterios":["Toggle CID-10/CID-11 no topo (default CID-10)","Trocar versão limpa os CIDs selecionados (com confirmação se houver valor)","Autocomplete: ao digitar, lista de sugestões com:","Código em destaque (mono, azul)","Descrição abaixo (texto menor)","Selecionar item → input limpa + chip violeta aparece abaixo com `{código} · {descrição}` + X","Click no X do chip limpa o CID (volta ao estado vazio)","Autocompletes têm mesma altura/fonte/border que outros selects (13px)","CID secundário tem label \"(opcional)\" em cinza ao lado","Salvar sem nenhum CID é permitido (não-obrigatórios)","Pesquisas mínimas: 2 caracteres para disparar busca"],"regras":["4 campos no banco para flexibilidade","Texto do parecer NÃO é auto-preenchido com o CID — médico digita o diagnóstico manualmente","CID-10 e CID-11 vêm de fontes diferentes (`cids.service` decide qual API consultar)","Trocar a versão limpa os campos (visões diferentes)"],"dependencias":["US-PAR-01","--"]},{"id":"US-PAR-07","title":"Salvar parecer com snapshot do médico","story":"**Como** Médico Regulador, **Quero** salvar o parecer com meus dados capturados automaticamente do meu perfil, **Para que** o documento fique íntegro mesmo se eu alterar meu perfil depois.","sections":[{"title":"Componentes do protótipo","body":"- Card \"Médico responsável\" no fim do drawer\n- Hook `useAuth()` para dados do usuário logado\n- Provider: `addParecer(id, parecer)` (sem `id` e `data` — são gerados)"},{"title":"Layout do card","body":"- Background `#FAFAF7`, border 1px, border-radius 4, padding 10px 12px\n- Display flex com:\n  - Avatar circular 36px (iniciais do nome em maiúsculas, fundo violeta claro, texto violeta)\n  - Bloco central: nome (negrito) + linha menor com CRM-UF · Especialidade · email\n  - Link \"Editar perfil\" à direita (10px) → abre `/meu-perfil` em nova aba\n- Quando CRM/UF faltam (e não é Admin Master): card vira amarelo `#FFFBEB` com texto \"Informe seu CRM e UF em Meu Perfil antes de emitir um parecer\" + ícone `AlertTriangle`"},{"title":"Critérios de aceite","body":"- [ ] Card \"Médico responsável\" no fim do drawer\n- [ ] Avatar com iniciais do nome (max 2 caracteres)\n- [ ] Mostra: nome do usuário logado, CRM/UF, especialidade, email — todos do perfil\n- [ ] Read-only (não há campo editável no card; só o link \"Editar perfil\")\n- [ ] Link \"Editar perfil\" abre `/meu-perfil` em nova aba\n- [ ] CRM/UF em branco (e perfil ≠ Admin Master) → card amarelo bloqueante + alerta + botão \"Salvar parecer\" desabilitado\n- [ ] Botão \"Salvar parecer\" no rodapé do drawer (violeta `tfd-btn-primary` adaptado)\n- [ ] Click no botão: spinner + texto \"Salvando...\" + drawer disabled\n- [ ] Sucesso: drawer fecha → toast verde \"Parecer registrado — Decisão: {Deferido/Indeferido}\" → seção \"Pareceres médicos\" recarrega com o novo parecer no topo\n- [ ] Erro: drawer permanece + toast vermelho\n- [ ] \"Cancelar\" com mudanças → modal \"Descartar alterações?\""},{"title":"Estados visuais","body":"- **Pristine**: card normal cinza\n- **CRM ausente**: card amarelo + botão Salvar disabled\n- **Saving**: spinner + textarea disabled"},{"title":"Side effects no sucesso","body":"- INSERT em `pareceres`:\n  - `id`, `solicitacao_id`, `decisao`, `variante_servico_ma` (nullable), `observacao`, `cid_principal*`, `cid_secundario*`, `versao_cid`\n  - **Snapshot do médico**: `medico` (nome), `medico_crm`, `medico_crm_uf`, `medico_especialidade`, `medico_email`, `medico_id`\n  - `data` (timestamptz now)\n- Log em `audit_logs`\n- Provider refetch"},{"title":"Regras de negócio","body":"- Snapshot: parecer guarda dados do médico no momento da emissão — não muda se o perfil mudar depois\n- Solicitação NÃO muda automaticamente de setor ao salvar parecer — regulador faz o envio manual (ver F04 da solicitação)\n- Múltiplos pareceres por solicitação são permitidos (histórico)\n- Parecer mais recente é o \"atual\" (UI usa o último)"},{"title":"Schema (banco)","body":"- Tabela `pareceres`:\n  - `id` (uuid)\n  - `solicitacao_id` (FK)\n  - `decisao` (enum)\n  - `variante_servico_ma` (enum, nullable — só em deferido)\n  - `observacao` (text)\n  - `cid_principal`, `cid_principal_nome`, `cid_secundario`, `cid_secundario_nome` (nullable)\n  - `versao_cid` (`'10' | '11'`)\n  - `medico` (nome — snapshot)\n  - `medico_crm`, `medico_crm_uf`, `medico_especialidade`, `medico_email`, `medico_id`\n  - `data` (timestamp)\n  - `created_at`, `updated_at`"},{"title":"Permissões","body":"- `regulacao.emitir_parecer`"},{"title":"Auditoria","body":"- Log: `entity_type='parecer'`, `action='create'`, snapshot"},{"title":"Dependências","body":"- US-PAR-01 (até US-PAR-06)\n- [[../EPIC-04-Configuracoes-Administrativo/F02-Usuarios|F02 — Usuários]] (perfil do médico)\n\n---"}],"criterios":["Card \"Médico responsável\" no fim do drawer","Avatar com iniciais do nome (max 2 caracteres)","Mostra: nome do usuário logado, CRM/UF, especialidade, email — todos do perfil","Read-only (não há campo editável no card; só o link \"Editar perfil\")","Link \"Editar perfil\" abre `/meu-perfil` em nova aba","CRM/UF em branco (e perfil ≠ Admin Master) → card amarelo bloqueante + alerta + botão \"Salvar parecer\" desabilitado","Botão \"Salvar parecer\" no rodapé do drawer (violeta `tfd-btn-primary` adaptado)","Click no botão: spinner + texto \"Salvando...\" + drawer disabled","Sucesso: drawer fecha → toast verde \"Parecer registrado — Decisão: {Deferido/Indeferido}\" → seção \"Pareceres médicos\" recarrega com o novo parecer no topo","Erro: drawer permanece + toast vermelho","\"Cancelar\" com mudanças → modal \"Descartar alterações?\""],"regras":["Snapshot: parecer guarda dados do médico no momento da emissão — não muda se o perfil mudar depois","Solicitação NÃO muda automaticamente de setor ao salvar parecer — regulador faz o envio manual (ver F04 da solicitação)","Múltiplos pareceres por solicitação são permitidos (histórico)","Parecer mais recente é o \"atual\" (UI usa o último)"],"dependencias":["US-PAR-01 (até US-PAR-06)","[[../EPIC-04-Configuracoes-Administrativo/F02-Usuarios|F02 — Usuários]] (perfil do médico)","--"]},{"id":"US-PAR-08","title":"Editar ou remover parecer existente","story":"**Como** Médico Regulador (autor do parecer) ou Coordenação Médica, **Quero** editar ou remover um parecer que tem erro, **Para que** o registro reflita a decisão correta.","sections":[{"title":"Componentes do protótipo","body":"- Menu kebab (`MoreVertical`) em cada parecer da lista\n- Reusa o `NewParecerDrawer` em modo edição\n- Modal de confirmação para remoção\n- Provider: `editarParecer(id, parecerId, patch)`, `removerParecer(id, parecerId)`"},{"title":"Layout da lista de pareceres (em RegulacaoTab)","body":"- Cards stackados verticalmente\n- Cada card:\n  - Header: chip de decisão (verde/vermelho) + data + médico (CRM-UF)\n  - Body: trecho da observação (truncate ~120 chars com \"... ver completo\")\n  - Footer: link \"Ver parecer completo\" → abre `/parecer/{id}` em nova aba + menu kebab à direita"},{"title":"Critérios de aceite","body":"- [ ] Cada parecer na lista tem menu kebab (⋮)\n- [ ] Menu opens dropdown com 2 opções: \"Editar\" e \"Remover\" (ambas só visíveis para autor original OU perfis com `regulacao.gerenciar_pareceres`)\n- [ ] \"Editar\" → abre drawer \"Editar parecer médico\" com dados preenchidos\n- [ ] Em modo edição:\n  - Title: \"Editar parecer médico\"\n  - Card \"Médico responsável\" mostra dados **originais** do parecer (não substitui pelo usuário logado)\n  - Subtítulo do card: \"Parecer original emitido por {médico} em {data}\"\n- [ ] Salvar → drawer fecha → toast verde \"Parecer atualizado\" → card atualiza na lista\n- [ ] \"Remover\" → modal \"Remover parecer?\" com aviso \"Esta ação é registrada em log de auditoria\"\n- [ ] Confirma remoção → spinner → modal fecha → toast \"Parecer removido\" → card sai da lista (soft delete)\n- [ ] Solicitação encerrada: menu kebab oculto (não há editar/remover em encerradas)"},{"title":"Estados visuais","body":"- **Lista normal**: cards stackados\n- **Após edição**: card atualiza com nova data de modificação\n- **Após remoção**: card some"},{"title":"Side effects","body":"- Edição: UPDATE em `pareceres` com `updated_at` + log de auditoria com diff\n- Remoção: UPDATE em `pareceres` com `excluido = true` + log\n- Provider refetch"},{"title":"Regras de negócio","body":"- Edição registra log com diff campo a campo (especialmente decisão, observação, CIDs)\n- Remoção é **soft delete** (`excluido = true`) — mantém para auditoria\n- Solicitação encerrada não permite editar nem remover pareceres\n- Apenas autor original OU `regulacao.gerenciar_pareceres` (Coord Médica, Admin)\n- Em modo edição, o card de médico responsável NÃO troca para o usuário logado (mantém snapshot do autor)"},{"title":"Schema (banco)","body":"- UPDATE em `pareceres` (com snapshot do médico imutável)\n- Campo `excluido` (boolean, default false) para soft delete"},{"title":"Permissões","body":"- `regulacao.emitir_parecer` (autor pode editar/remover seu próprio)\n- `regulacao.gerenciar_pareceres` (Coord Médica, Admin Master)"},{"title":"Auditoria","body":"- Log: `action='update'` ou `action='delete'`, com user_id do executor (não do autor original)"},{"title":"Dependências","body":"- US-PAR-01, US-PAR-07"}],"criterios":["Cada parecer na lista tem menu kebab (⋮)","Menu opens dropdown com 2 opções: \"Editar\" e \"Remover\" (ambas só visíveis para autor original OU perfis com `regulacao.gerenciar_pareceres`)","\"Editar\" → abre drawer \"Editar parecer médico\" com dados preenchidos","Em modo edição:","Title: \"Editar parecer médico\"","Card \"Médico responsável\" mostra dados **originais** do parecer (não substitui pelo usuário logado)","Subtítulo do card: \"Parecer original emitido por {médico} em {data}\"","Salvar → drawer fecha → toast verde \"Parecer atualizado\" → card atualiza na lista","\"Remover\" → modal \"Remover parecer?\" com aviso \"Esta ação é registrada em log de auditoria\"","Confirma remoção → spinner → modal fecha → toast \"Parecer removido\" → card sai da lista (soft delete)","Solicitação encerrada: menu kebab oculto (não há editar/remover em encerradas)"],"regras":["Edição registra log com diff campo a campo (especialmente decisão, observação, CIDs)","Remoção é **soft delete** (`excluido = true`) — mantém para auditoria","Solicitação encerrada não permite editar nem remover pareceres","Apenas autor original OU `regulacao.gerenciar_pareceres` (Coord Médica, Admin)","Em modo edição, o card de médico responsável NÃO troca para o usuário logado (mantém snapshot do autor)"],"dependencias":["US-PAR-01, US-PAR-07"]}]},{"file":"F01-Carimbo-Regulacao","code":"F02","title":"F01* — Carimbo de Regulação","description":"⚠ **AGUARDANDO VALIDAÇÃO PELO SETOR — não incluída em sprints ainda.** Todas as US deste arquivo terminam com asterisco (`*`). Revisar com o setor antes de virar PBI.","meta":[{"key":"Tela","value":"`/fluxo-v2/regulacao` + drawer `CarimboRegulacaoDrawer`"},{"key":"Status","value":"⚠ Pendente de validação"}],"userStories":[]},{"file":"F02-Tentativas-Unidade","code":"F03","title":"F02* — Tentativas com Unidades de Destino","description":"⚠ **AGUARDANDO VALIDAÇÃO PELO SETOR — não incluída em sprints ainda.** US marcadas com asterisco (`*`). Validar fluxo com regulação amanhã.","meta":[{"key":"Tela","value":"Detalhe da solicitação → tab Regulação → seção Tentativas"},{"key":"Drawer","value":"`NewTentativaDrawer`"},{"key":"Status","value":"⚠ Pendente de validação"}],"userStories":[]},{"file":"F03-Agendamento-Confirmado","code":"F04","title":"F03* — Agendamento Confirmado","description":"⚠ **AGUARDANDO VALIDAÇÃO PELO SETOR — não incluída em sprints ainda.** US marcadas com asterisco (`*`).","meta":[{"key":"Tela","value":"Detalhe da solicitação → tab Regulação → bloco \"Agendamento\""},{"key":"Drawer","value":"`RegistrarAgendamentoDrawer`"},{"key":"Status","value":"⚠ Pendente de validação"}],"userStories":[]}]},{"folder":"EPIC-06-Financeiro","code":"EPIC-06","title":"Financeiro (Passagens, Ajudas de Custo, Adicionais)","pendente":false,"features":[{"file":"F01-Passagens","code":"F01","title":"Passagens (Viagens)","description":"Cadastro e custeio das viagens (passagens) da solicitação. Cada viagem agrupa múltiplos trechos (ida, volta e intermediários), com origem/destino, modal, distância e custo real por trecho, alimentando o consumo do contrato anual de passagens.","meta":[{"key":"Tela","value":"Detalhe da solicitação → tab Financeiro · Tela de Financeiro → aba Passagens"},{"key":"Drawer","value":"`NewPassagemDrawer`"},{"key":"Arquivos-chave","value":"`src/app/fluxo-v2/_components/drawers/NewPassagemDrawer.tsx` · `src/app/fluxo-v2/_utils/totaisFinanceiros.ts` (`buildViagem`)"},{"key":"Status","value":"✅ Validado pelo setor"}],"userStories":[{"id":"US-PAS-01","title":"Cadastrar viagem com múltiplos trechos","story":"**Como** Setor de Passagens, **Quero** cadastrar uma viagem com múltiplos trechos (ida e volta independentes, opcionalmente com trechos intermediários), **Para que** o sistema reflita o caminho real do paciente quando a viagem não é direta.","sections":[{"title":"Componentes do protótipo","body":"- Drawer `NewPassagemDrawer` em `src/app/fluxo-v2/_components/drawers/NewPassagemDrawer.tsx`\n- Builder `buildViagem` em `src/app/fluxo-v2/_utils/totaisFinanceiros.ts`\n- Aba **Passagens** em `FinanceiroTab` e em `src/app/fluxo-v2/financeiro/page.tsx`"},{"title":"Critérios de aceite","body":"- [ ] Botão \"Nova viagem\" na seção de Viagens da solicitação\n- [ ] Drawer aceita N trechos (mínimo 1, sem limite máximo)\n- [ ] Cada trecho: origem (unidade ou município), destino, data, modal (terrestre/aéreo/fluvial), distância em km\n- [ ] Rotas cadastradas aparecem como sugestão (autocomplete origem → destino)\n- [ ] Trechos numerados na ordem (Trecho 1, Trecho 2, ...)\n- [ ] Reordenar trechos via drag (SHOULD)\n- [ ] Validação: a data de um trecho posterior não pode ser anterior à do trecho anterior\n- [ ] Salvar grava em `viagens` + `viagem_trechos` em transação"},{"title":"Regras de negócio","body":"- Uma viagem pertence a uma solicitação e agrupa todos os seus trechos\n- Os trechos mantêm a ordem de cadastro, com numeração sequencial\n- As datas dos trechos são monotônicas (não retrocedem ao longo da viagem)"},{"title":"Schema (banco)","body":"- Tabela `viagens` (`id`, `solicitacao_id` FK, `created_at`)\n- Tabela `viagem_trechos` (`id`, `viagem_id` FK, `ordem`, `origem`, `destino`, `data`, `modal`, `distancia_km`, `custo`)\n- Gravação transacional de viagem + trechos"},{"title":"Permissões","body":"- `financeiro.passagens.lancar` (criar/editar viagem)\n- `financeiro.visualizar` (consultar)"},{"title":"Dependências","body":"- [[../EPIC-04-Solicitacoes-TFD/F01-Listagem|F01 — Solicitações]] (a viagem nasce da solicitação)\n- [[../EPIC-02-Cadastros-Base/F01-Unidades|F01 — Unidades e Rotas]] (origem/destino e sugestões)\n\n---"}],"criterios":["Botão \"Nova viagem\" na seção de Viagens da solicitação","Drawer aceita N trechos (mínimo 1, sem limite máximo)","Cada trecho: origem (unidade ou município), destino, data, modal (terrestre/aéreo/fluvial), distância em km","Rotas cadastradas aparecem como sugestão (autocomplete origem → destino)","Trechos numerados na ordem (Trecho 1, Trecho 2, ...)","Reordenar trechos via drag (SHOULD)","Validação: a data de um trecho posterior não pode ser anterior à do trecho anterior","Salvar grava em `viagens` + `viagem_trechos` em transação"],"regras":["Uma viagem pertence a uma solicitação e agrupa todos os seus trechos","Os trechos mantêm a ordem de cadastro, com numeração sequencial","As datas dos trechos são monotônicas (não retrocedem ao longo da viagem)"],"dependencias":["[[../EPIC-04-Solicitacoes-TFD/F01-Listagem|F01 — Solicitações]] (a viagem nasce da solicitação)","[[../EPIC-02-Cadastros-Base/F01-Unidades|F01 — Unidades e Rotas]] (origem/destino e sugestões)","--"]},{"id":"US-PAS-02","title":"Registrar custo real da passagem","story":"**Como** Setor de Passagens, **Quero** registrar o custo real cobrado pela agência para cada trecho, **Para que** o sistema reflita o valor a ser faturado e a coordenação acompanhe o consumo do contrato em tempo real.","sections":[{"title":"Componentes do protótipo","body":"- Drawer `NewPassagemDrawer` (campo de custo por trecho + total)\n- `totaisFinanceiros` soma o total da viagem\n- `AnexosUploadField` para o comprovante por trecho"},{"title":"Critérios de aceite","body":"- [ ] Cada trecho tem campo \"Custo (R$)\" obrigatório no momento da finalização\n- [ ] Comprovante anexável (PDF/JPG/PNG) por trecho via `AnexosUploadField`\n- [ ] Total da viagem somado automaticamente e exibido no topo do drawer\n- [ ] O custo afeta o consumo do contrato anual (dashboard)\n- [ ] Trigger de auditoria registra alteração de custo\n- [ ] Lock por setor: após o setor de Custos aprovar, o valor fica imutável (apenas Admin destrava com motivo)"},{"title":"Regras de negócio","body":"- O total da viagem é a soma dos custos dos trechos\n- Após a aprovação de Custos, o valor fica imutável; o destravamento só ocorre por Admin com motivo registrado\n- Toda alteração de custo é auditada com autor e data"},{"title":"Schema (banco)","body":"- Coluna `custo` em `viagem_trechos`\n- Anexos de comprovante por trecho\n- Registro de auditoria de alteração de custo"},{"title":"Permissões","body":"- `financeiro.passagens.lancar` (lançar custo)\n- `financeiro.custos.aprovar` (aprovar e travar)\n- Admin para destravar com motivo"},{"title":"Dependências","body":"- [[#US-PAS-01|US-PAS-01 — Cadastrar viagem com múltiplos trechos]]\n\n---"}],"criterios":["Cada trecho tem campo \"Custo (R$)\" obrigatório no momento da finalização","Comprovante anexável (PDF/JPG/PNG) por trecho via `AnexosUploadField`","Total da viagem somado automaticamente e exibido no topo do drawer","O custo afeta o consumo do contrato anual (dashboard)","Trigger de auditoria registra alteração de custo","Lock por setor: após o setor de Custos aprovar, o valor fica imutável (apenas Admin destrava com motivo)"],"regras":["O total da viagem é a soma dos custos dos trechos","Após a aprovação de Custos, o valor fica imutável; o destravamento só ocorre por Admin com motivo registrado","Toda alteração de custo é auditada com autor e data"],"dependencias":["[[#US-PAS-01|US-PAS-01 — Cadastrar viagem com múltiplos trechos]]","--"]}]},{"file":"F02-Ajudas-de-Custo","code":"F02","title":"Ajudas de Custo (Diárias)","description":"Cálculo e pagamento das diárias (ajuda de custo) do paciente e acompanhantes, com base na tabela SIGTAP parametrizada, e seleção da conta bancária do pool do paciente para depósito.","meta":[{"key":"Tela","value":"Detalhe da solicitação → tab Financeiro · Tela de Financeiro → aba Ajudas de Custo"},{"key":"Drawer","value":"`NewAjudaCustoDrawer`"},{"key":"Arquivos-chave","value":"`src/app/fluxo-v2/_components/drawers/NewAjudaCustoDrawer.tsx` · `src/app/fluxo-v2/_components/DadosBancariosBlock.tsx` · `src/core/models/sigtap.model.ts`"},{"key":"Status","value":"✅ Validado pelo setor"}],"userStories":[{"id":"US-PAC-08","title":"Selecionar conta do pool na Ajuda de Custo","story":"**Como** Atendente TFD ao registrar uma Ajuda de Custo, **Quero** selecionar uma das contas já cadastradas para o paciente (e poder criar uma nova inline), **Para que** eu não precise sair do drawer da solicitação para mexer no cadastro.","sections":[{"title":"Componentes do protótipo","body":"- Bloco `DadosBancariosBlock` em `src/app/fluxo-v2/_components/DadosBancariosBlock.tsx`\n- Usado dentro de `NewAjudaCustoDrawer` (fluxo-v2)\n- Botão \"Nova conta\" abre o `DadosBancariosDrawer` em modo create por cima"},{"title":"Critérios de aceite (visuais)","body":"- [ ] Select \"Conta bancária do paciente\" lista todas as contas do pool (titular + banco + agência/conta OU chave PIX em ellipsis)\n- [ ] Botão \"+ Nova conta\" (link ou `tfd-btn tfd-btn-ghost`) abre o drawer de cadastro por cima\n- [ ] Ao salvar a nova conta, o select já a seleciona automaticamente\n- [ ] Resumo mostra os dados da conta escolhida (read-only)"},{"title":"Regras de negócio","body":"- Ao confirmar a Ajuda de Custo, snapshot dos dados da conta é gravado na solicitação (titular, vínculo, banco, agência, conta, chave PIX)\n- O FK aponta para a conta do pool, mas o snapshot é congelado: alterações posteriores na conta NÃO mexem em ajudas de custo já confirmadas\n- Cenários cobertos: paciente menor com pai/mãe; adulto com cônjuge; acompanhante que recebe; próprio paciente"},{"title":"Dependências","body":"- [[../EPIC-01-Cadastros-Fundamentais/F01-Pacientes#US-PAC-07|US-PAC-07 — Pool de contas bancárias do paciente]]\n- [[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (tabela `vinculo`)\n\n---"}],"criterios":["Select \"Conta bancária do paciente\" lista todas as contas do pool (titular + banco + agência/conta OU chave PIX em ellipsis)","Botão \"+ Nova conta\" (link ou `tfd-btn tfd-btn-ghost`) abre o drawer de cadastro por cima","Ao salvar a nova conta, o select já a seleciona automaticamente","Resumo mostra os dados da conta escolhida (read-only)"],"regras":["Ao confirmar a Ajuda de Custo, snapshot dos dados da conta é gravado na solicitação (titular, vínculo, banco, agência, conta, chave PIX)","O FK aponta para a conta do pool, mas o snapshot é congelado: alterações posteriores na conta NÃO mexem em ajudas de custo já confirmadas","Cenários cobertos: paciente menor com pai/mãe; adulto com cônjuge; acompanhante que recebe; próprio paciente"],"dependencias":["[[../EPIC-01-Cadastros-Fundamentais/F01-Pacientes#US-PAC-07|US-PAC-07]] — Pool de contas bancárias do paciente","[[../EPIC-04-Configuracoes-Administrativo/F01-Cadastros-Mestres|F01 — Cadastros Mestres]] (tabela `vinculo`)","--"]},{"id":"US-AJU-01","title":"Calcular a diária automaticamente pela SIGTAP","story":"**Como** Setor de Ajuda de Custo, **Quero** que o sistema calcule automaticamente a diária a pagar com base na tabela SIGTAP parametrizada (com/sem pernoite, modal terrestre/aéreo/fluvial, quantidade de acompanhantes), **Para que** eu elimine o cálculo manual em planilha.","sections":[{"title":"Componentes do protótipo","body":"- Drawer `NewAjudaCustoDrawer` (breakdown do cálculo)\n- Builder `buildAjudaCusto` em `src/app/fluxo-v2/_utils/totaisFinanceiros.ts`\n- Parâmetros em `src/core/models/sigtap.model.ts`"},{"title":"Critérios de aceite","body":"- [ ] O cálculo dispara automaticamente após a viagem cadastrada e o parecer deferido\n- [ ] O algoritmo lê a tabela SIGTAP parametrizada e cruza com tipo (com/sem pernoite), modal, quantidade de dias e de acompanhantes\n- [ ] Resultado exibido em breakdown: valor base × dias × pessoas + adicionais = total\n- [ ] Permite ajuste manual com motivo obrigatório (exceção autorizada pela coordenação)\n- [ ] Histórico de cálculos preservado (valor automático vs. valor pago)\n- [ ] Trigger de auditoria registra qualquer ajuste manual com autor"},{"title":"Regras de negócio","body":"- O valor automático é derivado da tabela SIGTAP; o ajuste manual exige motivo e fica auditado\n- O histórico mantém o valor automático e o valor pago lado a lado\n- O cálculo depende de viagem cadastrada e parecer deferido"},{"title":"Schema (banco)","body":"- Tabela `ajuda_custo` (`solicitacao_id` FK, `valor_automatico`, `valor_pago`, `ajuste_motivo`, `created_at`)\n- Parametrização em `sigtap` (valor base por modal/pernoite)\n- Histórico de cálculo (automático × pago)"},{"title":"Permissões","body":"- `financeiro.ajuda_custo.calcular`\n- `financeiro.ajuda_custo.aprovar`\n- Coordenação para ajuste manual com motivo"},{"title":"Dependências","body":"- [[#US-PAC-08|US-PAC-08 — Selecionar conta do pool na Ajuda de Custo]]\n- [[../EPIC-02-Cadastros-Base/F03-Tabelas-Auxiliares#SIGTAP|Tabela SIGTAP parametrizada]]\n\n---"}],"criterios":["O cálculo dispara automaticamente após a viagem cadastrada e o parecer deferido","O algoritmo lê a tabela SIGTAP parametrizada e cruza com tipo (com/sem pernoite), modal, quantidade de dias e de acompanhantes","Resultado exibido em breakdown: valor base × dias × pessoas + adicionais = total","Permite ajuste manual com motivo obrigatório (exceção autorizada pela coordenação)","Histórico de cálculos preservado (valor automático vs. valor pago)","Trigger de auditoria registra qualquer ajuste manual com autor"],"regras":["O valor automático é derivado da tabela SIGTAP; o ajuste manual exige motivo e fica auditado","O histórico mantém o valor automático e o valor pago lado a lado","O cálculo depende de viagem cadastrada e parecer deferido"],"dependencias":["[[#US-PAC-08|US-PAC-08 — Selecionar conta do pool na Ajuda de Custo]]","[[../EPIC-02-Cadastros-Base/F03-Tabelas-Auxiliares#SIGTAP|Tabela SIGTAP parametrizada]]","--"]}]},{"file":"F03-Adicionais","code":"F03","title":"Adicionais","description":"Registro de adicionais pagos quando a solicitação foi aprovada com 2 acompanhantes (acima do padrão de 1), garantindo que o cálculo da ajuda de custo cubra o segundo acompanhante.","meta":[{"key":"Tela","value":"Detalhe da solicitação → tab Financeiro · Tela de Financeiro → aba Adicionais"},{"key":"Drawer","value":"`NewAdicionalDrawer`"},{"key":"Arquivos-chave","value":"`src/app/fluxo-v2/_components/drawers/NewAdicionalDrawer.tsx` · `src/app/fluxo-v2/_utils/totaisFinanceiros.ts` (`buildAdicional`)"},{"key":"Status","value":"✅ Validado pelo setor"}],"userStories":[{"id":"US-ADI-01","title":"Cadastrar adicional por acompanhante extra","story":"**Como** Setor de Ajuda de Custo, **Quero** registrar um adicional pago quando a solicitação foi aprovada com 2 acompanhantes (em vez do padrão de 1), **Para que** o cálculo da ajuda de custo cubra o segundo acompanhante corretamente.","sections":[{"title":"Componentes do protótipo","body":"- Drawer `NewAdicionalDrawer` em `src/app/fluxo-v2/_components/drawers/NewAdicionalDrawer.tsx`\n- Builder `buildAdicional` em `src/app/fluxo-v2/_utils/totaisFinanceiros.ts`\n- Aba **Adicionais** na Tela de Financeiro"},{"title":"Critérios de aceite","body":"- [ ] O adicional aparece automaticamente quando a solicitação tem 2 acompanhantes autorizados\n- [ ] Valor calculado pela tabela SIGTAP (adicional por acompanhante)\n- [ ] Justificativa do acompanhante extra (já registrada na solicitação) replicada no adicional\n- [ ] O adicional pode ser removido pela Coordenação com motivo (retirada de autorização)"},{"title":"Regras de negócio","body":"- O disparo automático fica condicionado a 2 acompanhantes autorizados na solicitação\n- A remoção do adicional é exclusiva da Coordenação e exige motivo\n- O valor segue a parametrização SIGTAP de adicional por acompanhante"},{"title":"Schema (banco)","body":"- Tabela `adicional` (`solicitacao_id` FK, `valor`, `justificativa`, `removido_motivo`, `created_at`)\n- Parametrização SIGTAP (adicional por acompanhante)"},{"title":"Permissões","body":"- `financeiro.adicional.registrar`\n- Coordenação para remover com motivo"},{"title":"Dependências","body":"- [[#US-AJU-01|US-AJU-01 — Calcular a diária automaticamente pela SIGTAP]]\n- [[../EPIC-04-Solicitacoes-TFD/F02-Cadastro#acompanhantes|Acompanhantes autorizados na solicitação]]\n\n---"}],"criterios":["O adicional aparece automaticamente quando a solicitação tem 2 acompanhantes autorizados","Valor calculado pela tabela SIGTAP (adicional por acompanhante)","Justificativa do acompanhante extra (já registrada na solicitação) replicada no adicional","O adicional pode ser removido pela Coordenação com motivo (retirada de autorização)"],"regras":["O disparo automático fica condicionado a 2 acompanhantes autorizados na solicitação","A remoção do adicional é exclusiva da Coordenação e exige motivo","O valor segue a parametrização SIGTAP de adicional por acompanhante"],"dependencias":["[[#US-AJU-01|US-AJU-01 — Calcular a diária automaticamente pela SIGTAP]]","[[../EPIC-04-Solicitacoes-TFD/F02-Cadastro#acompanhantes|Acompanhantes autorizados na solicitação]]","--"]}]},{"file":"F04-Tela-Financeiro","code":"F04","title":"Tela de Financeiro","description":"Tela principal do Financeiro, organizada em abas (Passagens, Ajudas de Custo, Adicionais), com KPIs contextuais, busca, filtros e ações por linha, para conferência e aprovação dos valores antes do faturamento BPA.","meta":[{"key":"Tela","value":"`/fluxo-v2/financeiro`"},{"key":"Página","value":"`FinanceiroListPage`"},{"key":"Arquivos-chave","value":"`src/app/fluxo-v2/financeiro/page.tsx` · `src/app/fluxo-v2/_components/FinanceiroTab.tsx` · `src/app/fluxo-v2/_utils/totaisFinanceiros.ts`"},{"key":"Status","value":"✅ Validado pelo setor"}],"userStories":[{"id":"US-FIN-TELA","title":"Listagem do Financeiro em abas (Passagens, Ajudas de Custo, Adicionais)","story":"**Como** Setor Financeiro (Passagens, Ajuda de Custo, Custos), Faturamento ou Coordenação, **Quero** a tela principal de Financeiro organizada em abas, com filtros, busca, totais e ações por linha, **Para que** eu confira e aprove os valores antes do faturamento BPA direto a partir da tabela.","sections":[{"title":"Componentes do protótipo","body":"- Página `src/app/fluxo-v2/financeiro/page.tsx` (`FinanceiroListPage`)\n- `FinanceiroTab` (conteúdo por aba) em `src/app/fluxo-v2/_components/FinanceiroTab.tsx`\n- `totaisFinanceiros` para os KPIs e totais\n- Componentes compartilhados: `PageHeader`, `StatsRow`, `Pagination`, `RowActions`"},{"title":"Critérios de aceite","body":"- [ ] Tela acessível para Passagens, Ajuda de Custo, Custos, Faturamento e Coordenação, com visibilidade conforme o papel\n- [ ] Header com título \"Financeiro\" e subtítulo \"Acompanhamento de viagens, ajudas de custo e adicionais\"\n- [ ] Abas no topo: Passagens (Viagens) · Ajudas de Custo · Adicionais; a aba inicial é a do papel do usuário logado\n- [ ] Sem botão de criação principal: os itens chegam automaticamente ao financeiro quando o parecer é deferido e a solicitação é encaminhada\n- [ ] Cards de KPI contextuais à aba ativa (Passagens: total no mês, trechos pendentes de lançamento, trechos sem custo, divergências com a agência; Ajudas de Custo: total no mês, aguardando aprovação, com ajuste manual, internações; Adicionais: total no mês, acompanhantes extras, internações, trocas de acompanhante)\n- [ ] Busca por número da solicitação, nome do paciente ou CPF\n- [ ] Filtros: Mês (default mês atual), Regional, Status (Lançado / Aprovado / Pago) e Modal (apenas na aba Passagens)\n- [ ] Ações por linha: lançar custo, aprovar, anexar comprovante, registrar ajuda, registrar adicional e devolver"},{"title":"Regras de negócio","body":"- A visibilidade de abas e ações segue o papel do usuário logado\n- Os itens entram no Financeiro automaticamente após o deferimento do parecer e o encaminhamento da solicitação\n- A aba inicial corresponde ao setor do usuário logado (Passagens abre em Passagens, etc.)\n- O faturamento BPA é feito a partir da própria tabela, após a conferência"},{"title":"Schema (banco)","body":"- Leitura consolidada de `viagens` / `viagem_trechos`, `ajuda_custo` e `adicional`\n- Status financeiro por item (`Lançado` / `Aprovado` / `Pago`)"},{"title":"Permissões","body":"- `financeiro.visualizar` (guard de rota)\n- Ações por setor: `financeiro.passagens.lancar`, `financeiro.custos.aprovar`, `financeiro.ajuda_custo.aprovar`, `financeiro.adicional.registrar`"},{"title":"Dependências","body":"- [[#US-PAS-01|US-PAS-01]], [[#US-PAS-02|US-PAS-02]], [[#US-AJU-01|US-AJU-01]], [[#US-ADI-01|US-ADI-01]]\n- [[../EPIC-01-Acesso-e-Perfis/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]\n\n---"}],"criterios":["Tela acessível para Passagens, Ajuda de Custo, Custos, Faturamento e Coordenação, com visibilidade conforme o papel","Header com título \"Financeiro\" e subtítulo \"Acompanhamento de viagens, ajudas de custo e adicionais\"","Abas no topo: Passagens (Viagens) · Ajudas de Custo · Adicionais; a aba inicial é a do papel do usuário logado","Sem botão de criação principal: os itens chegam automaticamente ao financeiro quando o parecer é deferido e a solicitação é encaminhada","Cards de KPI contextuais à aba ativa (Passagens: total no mês, trechos pendentes de lançamento, trechos sem custo, divergências com a agência; Ajudas de Custo: total no mês, aguardando aprovação, com ajuste manual, internações; Adicionais: total no mês, acompanhantes extras, internações, trocas de acompanhante)","Busca por número da solicitação, nome do paciente ou CPF","Filtros: Mês (default mês atual), Regional, Status (Lançado / Aprovado / Pago) e Modal (apenas na aba Passagens)","Ações por linha: lançar custo, aprovar, anexar comprovante, registrar ajuda, registrar adicional e devolver"],"regras":["A visibilidade de abas e ações segue o papel do usuário logado","Os itens entram no Financeiro automaticamente após o deferimento do parecer e o encaminhamento da solicitação","A aba inicial corresponde ao setor do usuário logado (Passagens abre em Passagens, etc.)","O faturamento BPA é feito a partir da própria tabela, após a conferência"],"dependencias":["[[#US-PAS-01|US-PAS-01]], [[#US-PAS-02|US-PAS-02]], [[#US-AJU-01|US-AJU-01]], [[#US-ADI-01|US-ADI-01]]","[[../EPIC-01-Acesso-e-Perfis/F03-Papeis-e-Permissoes|F03 — Papéis e Permissões]]","--"]}]}]},{"folder":"EPIC-07-Relatorios","code":"EPIC-07","title":"Relatórios","pendente":false,"features":[{"file":"F01-Relatorios","code":"F01","title":"F01 — Relatórios","description":"Tela `/relatorios` com 3 abas: Financeiro (acompanhamento quadrimestral), Faturamento (passagens emitidas no mês) e BPA (lançamento no SIA/SUS).","meta":[{"key":"Tela","value":"`/relatorios`"},{"key":"Status","value":"Operacional — 3 abas (Financeiro / Faturamento / BPA)"},{"key":"Componentes","value":"`_RelatorioFinanceiro.tsx`, `_RelatorioFaturamento.tsx`, `_RelatorioRPB.tsx` + shared (`ReportShell`, `ReportTable`, `format.ts`, `sigtap-mapper.ts`)"}],"userStories":[{"id":"US-REL-01","title":"Aba Financeiro — acompanhamento quadrimestral consolidado","story":"**Como** Coordenação / Financeiro, **Quero** ver o desembolso consolidado do quadrimestre, **Para que** eu tenha controle do que foi pago e do que está previsto.","criterios":["Sidebar → \"Relatórios\" → `/relatorios` (default tab `financeiro`)","Filtros: Ano + Quadrimestre (1º / 2º / 3º)","Hero com período em destaque + total efetivo no canto direito","StatsRow com: nº de pacientes, nº de passagens, total bruto, total efetivo (descontando reembolsos)","Tabela por solicitação: paciente, viagens (qtd + total), ajudas de custo (qtd + total), adicionais (qtd + total), reembolsos, total efetivo","Botão de impressão (`PrintButton`) gera versão print-friendly (sem toolbar, sem ações)"],"regras":["Valor efetivo = soma(valor) − soma(valor_reembolso); itens com `ativa = false` são excluídos","Período do quadrimestre: 1º = jan–abr, 2º = mai–ago, 3º = set–dez","Solicitações com tipoSolicitacao = `AJUDA_CUSTO` não exibem coluna de passagens (fix `0eaae0a`)"],"dependencias":["[[F02-Ajudas-de-Custo]]","[[F01-Passagens]]","[[F03-Adicionais]]"],"sections":[{"title":"Componentes do protótipo","body":"- `src/app/relatorios/_RelatorioFinanceiro.tsx` — componente da aba\n- Shared: `ReportToolbar`, `ReportHero`, `StatsRow`, `TableCard`, `ReportTable`, `PrintButton`\n- Format helpers: `fmtBRL`, `fmtDataBR`, `valorPorExtenso`"},{"title":"Schema (banco)","body":"Queries: `viagens`, `ajudas_custo`, `adicionais` join `solicitacoes` join `pacientes` no período. Filtros: `ativa = true`, `data_*` no quadrimestre."},{"title":"Permissões","body":"`relatorios.visualizar`"}]},{"id":"US-REL-02","title":"Aba Faturamento — relatório mensal de passagens","story":"**Como** Financeiro, **Quero** o relatório mensal de passagens emitidas para conciliar com a fatura do fornecedor, **Para que** eu pague o que é devido sem erro.","criterios":["Sidebar → \"Relatórios\" → aba `faturamento`","Filtros: Ano (select) + Mês (pílulas 1–12 + \"Ano inteiro\")","Hero com período + total a pagar no canto direito","StatsRow com: bilhetes emitidos (com breakdown paciente/acomp.), valor bruto, créditos do fornecedor, reembolsos ao TFD","Tabela \"Itens faturados\": doc, processo, data bilhete, passageiro, tipo (IDA/VOLTA), data viagem, trecho, valor, total","Tabela \"Créditos para o fornecedor\" — placeholder (preenchido manualmente pela agência)","Tabela \"Reembolsos concedidos ao TFD\" — placeholder","Bloco de destaque final: \"Total do Faturamento\" + valor por extenso"],"regras":["Itens vêm de `viagens` com `ativa = true` e `created_at` dentro do período","Valor efetivo no relatório = `valor − valor_reembolso` (reembolso parcial deduz)","Coluna \"Data bilhete\" prefere `emitido_em` e cai em `created_at` quando o bilhete ainda não foi formalmente emitido","Bug histórico corrigido em `feat(relatorios): redesign BPA + remove Ajuda de Custo` — query não pode referenciar colunas inexistentes (`beneficiario_tipo`, `beneficiario_id`, `data_retorno_prevista` não existem em `viagens`)"],"dependencias":["[[F01-Passagens]]"],"sections":[{"title":"Componentes do protótipo","body":"- `src/app/relatorios/_RelatorioFaturamento.tsx`\n- Shared: `ReportShell`, `ReportTable`, `TipoBeneficiarioBadge`, `TipoPercursoBadge`"},{"title":"Schema (banco)","body":"Query principal: `viagens` ← `solicitacoes` ← `pacientes`. Campos: `id, numero_bilhete, tipo, data_embarque_prevista, created_at, emitido_em, origem_*, destino_*, valor, valor_reembolso, ativa`."},{"title":"Estados visuais","body":"- **Loading**: spinner centralizado\n- **Empty**: \"Nenhuma viagem registrada em <mês>.\"\n- **Imprimível**: `ReportPrintStyles` ativa CSS print-friendly"}]},{"id":"US-REL-03","title":"Aba BPA — dados para lançamento no SIA/SUS","story":"**Como** Financeiro, **Quero** a lista de lançamentos BPA do mês com código SIGTAP já resolvido, **Para que** eu transcreva direto no sistema do SUS sem precisar consultar tabela auxiliar.","criterios":["Sidebar → \"Relatórios\" → aba `rpb`","Filtros: tipo (Ajuda de Custo / Passagens) + Ano + Mês","StatsRow: total de linhas, lançadas no BPA, pendentes, total de diárias/unidades","Tabela compacta com colunas agrupadas:\n  - **Pessoa** — nome bold + badge de beneficiário (P/A — só em Ajuda de Custo); abaixo CPF/CNS · sexo · nascimento\n  - **Contato** — telefone formatado em cima, e-mail abaixo\n  - **Endereço** — 3 linhas: logradouro · bairro+CEP · município (sem ellipsis)\n  - **Dt. Atend.**\n  - **Rota** (passagens) — trecho + ModalBadge (Terrestre/Aéreo/Fluvial) + distância com unidade\n  - **SIGTAP** — código (mono) + descrição inline (linha 2)\n  - **Qtd** — diárias (ajuda) ou unidades (passagens)\n  - **CID**","Checkbox por linha + bulk select; estado \"lançado no BPA\" persiste em `bpa_lancamentos`","Rodapé com nota: \"O código SIGTAP é derivado automaticamente do contexto da solicitação (beneficiário, modal, CNRAC) com base na tabela auxiliar.\""],"regras":["SIGTAP é resolvido em `_shared/sigtap-mapper.ts` com base em: tipo (paciente/acompanhante), pernoite (ajuda) ou modal terrestre/aéreo/fluvial (passagem), CNRAC","Unidade da quantidade vem da própria tabela SIGTAP: km (terrestre, ÷ 50), milhas (aéreo, ÷ 200), milhas náuticas (fluvial, ÷ 27)","Quantidade SIGTAP = `Math.ceil(distancia / divisor)` — passagens sem `distancia_valor` exibem \"pendente\" (`AlertCircle`)","Para Ajuda de Custo: tipo paciente/acompanhante vem de `ajudas_custo.tipo`; quantidade = `dias_elegiveis` (com pernoite) ou 1 (sem pernoite)","Para passagens: o modelo atual de `viagens` ainda não distingue beneficiário paciente vs. acompanhante; todas as viagens são tratadas como paciente até que o schema seja estendido","Backfill aplicado: 41 viagens aéreas que estavam com `distancia_valor IS NULL` tiveram distância calculada via haversine sobre `aeroportos` (Caxias/Bacabal normalizadas para São Luís, Rio = GIG por padrão)"],"dependencias":["[[../EPIC-01-Cadastros-Fundamentais/F01-Pacientes]]","[[F01-Passagens]]","[[F02-Ajudas-de-Custo]]"],"sections":[{"title":"Componentes do protótipo","body":"- `src/app/relatorios/_RelatorioRPB.tsx` — componente da aba (passagens + ajuda de custo)\n- `src/app/relatorios/_shared/sigtap-mapper.ts` — `resolveSigtapAjudaCusto`, `resolveSigtapPassagem`, `calcularQuantidadePassagem`\n- `ModalBadge` (inline em `_RelatorioRPB.tsx`)\n- `TipoBeneficiarioBadge` (compartilhado em `_shared/ReportTable.tsx`)"},{"title":"Schema (banco)","body":"Queries:\n- Ajuda de Custo: `ajudas_custo` ← `solicitacoes` ← `pacientes` (+ `acompanhantes` quando tipo = ACOMPANHANTE)\n- Passagens: `viagens` ← `solicitacoes` ← `pacientes`\n- Tabela auxiliar `aeroportos` (lat/lon de cada IATA) usada para cálculo de distância no momento da emissão da passagem aérea\n- Estado de lançamento: `bpa_lancamentos (tipo, origem_id, trecho)`"},{"title":"Tabela SIGTAP (referência)","body":"**Ajuda de Custo:**\n- `08.03.01.001-0` — paciente, com pernoite\n- `08.03.01.002-8` — paciente, sem pernoite\n- `08.03.01.003-6` — paciente, com pernoite, CNRAC\n- `08.03.01.004-4` — acompanhante, com pernoite\n- `08.03.01.005-2` — acompanhante, sem pernoite\n- `08.03.01.006-0` — acompanhante, com pernoite, CNRAC\n\n**Passagens (deslocamento):**\n- `08.03.01.012-5` — paciente terrestre (÷ 50 km)\n- `08.03.01.008-7` — paciente aéreo (÷ 200 mi)\n- `08.03.01.014-1` — paciente aéreo CNRAC (÷ 200 mi)\n- `08.03.01.011-7` — paciente fluvial (÷ 27 mn)\n- `08.03.01.010-9` — acompanhante terrestre\n- `08.03.01.007-9` — acompanhante aéreo\n- `08.03.01.013-3` — acompanhante aéreo CNRAC\n- `08.03.01.009-5` — acompanhante fluvial"},{"title":"Pendências conhecidas","body":"- `viagens` precisa de campo `beneficiario_tipo` (paciente | acompanhante) para destravar o SIGTAP correto de passagens de acompanhante. Hoje todas resolvem para o código de paciente.\n- Flag CNRAC não está modelada; quando vier, o resolver `_shared/sigtap-mapper.ts` já aceita o parâmetro."},{"title":"Permissões","body":"`relatorios.visualizar` (ler), `relatorios.lancar_bpa` (marcar lançado)"}]},{"id":"US-REL-04","title":"Relatório de Gestão — visão consolidada por solicitação","story":"**Como** Gestora do TFD **Quero** ver um relatório com uma linha por solicitação consolidando paciente, diagnóstico, origem do laudo, hospital de agendamento e parecer médico **Para que** eu acompanhe estrategicamente o fluxo e gere recortes por regional/município/período.","criterios":["Aba \"Gestão\" disponível em `/relatorios?aba=gestao` ao lado de Financeiro, Faturamento e BPA.","Toolbar com 4 filtros em linha única (sem quebra): Ano (dropdown), Mês (dropdown — \"Ano inteiro\" + 12 meses), Regional e Município (dependente da regional escolhida).","Botões \"Atualizar\" e \"Imprimir / PDF\" na mesma linha à direita da toolbar.","Filtro Município fica desabilitado até uma Regional ser escolhida.","StatsRow exibe: Total no período, Após filtros, Deferidos, Indeferidos e Sem parecer.","Tabela com 6 colunas agrupadas: Paciente (nome + contato + município), Diagnóstico (CID em chip + descrição), Unidade de Origem (nome + cidade/UF), Hospital de Agendamento (nome + cidade/UF), Parecer (badge Deferido/Indeferido/—) e Observação.","Cada linha da tabela representa uma solicitação."],"regras":["Período é controlado por Ano + Mês. Mês = 0 significa \"ano inteiro\". Default é o ano corrente com \"Ano inteiro\".","Filtro Município mostra apenas os municípios vinculados à Regional selecionada (via tabela `regionais_saude_municipios`).","Quando Regional está selecionada e Município = \"Todos\", a filtragem usa o conjunto completo de municípios daquela Regional.","Parecer exibido é sempre o mais recente da solicitação (ordenação por `created_at` desc).","Ícones: estetoscópio (índigo) na coluna Unidade de Origem; hospital (verde) na coluna Hospital de Agendamento."],"dependencias":["US-UNI-06 e US-UNI-07 (vínculos de unidade e tags).","US-PAC-09 (chips de unidades no detalhe do paciente).","Migration 00057 (`solicitacoes.origem_laudo_unidade_id`).","Services `regionais-saude.service.ts::listarRegionaisSaudeAdmin` e `listarMunicipiosPorRegional`.","Tabela `pareceres`."],"sections":[{"title":"Componentes do protótipo","body":"- `src/app/relatorios/_RelatorioGestao.tsx` (novo, ~430 linhas).\n- Aba registrada em `src/app/relatorios/page.tsx` (`'gestao'` adicionado em `TabKey`).\n- Reutiliza `ReportShell` (FilterField, PrintButton, ReportHero, StatsRow, TableCard, ReportPrintStyles).\n- Reutiliza `ReportTable` com 6 `ReportColumn<GestaoRow>`."},{"title":"Layout","body":"- 1ª linha: Hero \"Relatório de Gestão — Solicitações TFD\" com o período logo abaixo.\n- 2ª linha: Toolbar com `flex flex-nowrap overflow-x-auto` — Ano · Mês · Regional · Município · (ml-auto) Atualizar · Imprimir/PDF.\n- 3ª linha: StatsRow com 5 cards.\n- 4ª linha: TableCard com a tabela densa de 6 colunas.\n- Colunas com largura fixa (220px / 260px / 200px / 200px / 110px / 220px) para evitar quebra de layout."},{"title":"Schema (banco)","body":"- `solicitacoes` joina com `pacientes`, `unidades_destino` (via FK `origem_laudo_unidade_id` e via `agendamentos`) e `pareceres`.\n- O select usa FK explícito: `origem_laudo_unidade:unidades_destino!solicitacoes_origem_laudo_unidade_id_fkey(...)` e `agendamentos(unidades_destino!agendamentos_unidade_destino_id_fkey(...))`."},{"title":"Filtros","body":"- Estado local: `ano`, `mes`, `regionalId`, `municipio`, `regionais[]`, `municipios[]`.\n- `useEffect` carrega regionais uma vez via `listarRegionaisSaudeAdmin()`.\n- `useEffect` carrega municípios quando `regionalId` muda via `listarMunicipiosPorRegional(id)` e reseta `municipio` ao trocar a regional."},{"title":"Histórico das mudanças","body":"- Versão 1: filtros incluíam Busca livre e Parecer; tabela tinha 10 colunas (Nome, Contato, Município de Residência separados; CID e Diagnóstico separados; Unidade de Origem e Cidade separados; Hospital e Cidade Destino separados; Observação).\n- Versão atual: removidos os filtros Busca e Parecer; tabela compactada em 6 colunas com agrupamento visual; cidade/UF aparece junto da respectiva unidade."}]}]}]},{"folder":"EPIC-08-Painel-Dashboard-PENDENTE","code":"EPIC-08","title":"Painel / Dashboard","pendente":true,"features":[{"file":"F01-Painel","code":"F01","title":"F01* — Painel / Dashboard","description":"⚠ **AGUARDANDO VALIDAÇÃO PELO SETOR — não incluída em sprints ainda.** Existe um esqueleto no protótipo mas o conjunto de KPIs e gráficos ainda não foi validado pela Coordenação. US com asterisco (`*`).","meta":[{"key":"Tela","value":"`/dashboard`"},{"key":"Status","value":"⚠ Pendente de validação"}],"userStories":[]}]},{"folder":"EPIC-09-Design-System-Padroes","code":"EPIC-09","title":"Design System & Padrões Visuais","pendente":false,"features":[{"file":"F01-FormSection","code":"F01","title":"FormSection — padrão visual para seções de drawer","description":"Padrão visual unificado para seções dentro de drawers do TFD. Substitui o antigo `<hr> + <h3>` por um `<fieldset>` com `<legend>` em uppercase, na cor azul primária. Aplicado em todos os drawers do sistema.","meta":[{"key":"Componente","value":"`src/shared/components/drawer/FormSection.tsx`"},{"key":"Status","value":"✅ Implementado"},{"key":"Drawers afetados","value":"PacienteDrawer · RegionalDrawer · UnidadeDrawer · DadosBancariosDrawer · NewParecerDrawer · NewPassagemDrawer · NewAjudaCustoDrawer · NewAdicionalDrawer · CarimboRegulacaoDrawer · RegistrarAgendamentoDrawer · NewTentativaDrawer · _NewSolicitacaoDrawer · NewEditarSolicitacaoDrawer"}],"userStories":[{"id":"US-DSN-01","title":"Componente FormSection padronizado","story":"**Como** Designer/Dev do TFD, **Quero** que todas as seções de drawer usem o componente `FormSection` (fieldset+legend uppercase azul), **Para que** o visual seja consistente em todo o sistema e novos drawers herdem o padrão sem CSS custom.","sections":[{"title":"Componentes do protótipo","body":"- Componente: `src/shared/components/drawer/FormSection.tsx`\n- Substitui o antigo padrão `<hr><h3>Título</h3>`"},{"title":"Critérios de aceite (visuais)","body":"- [ ] Cada seção é um `<fieldset>` (sem border default do navegador)\n- [ ] `<legend>` em uppercase, font-weight 600, cor azul primária (var(--tfd-primary-600))\n- [ ] Espaçamento vertical consistente entre seções\n- [ ] Os 13 drawers listados estão usando o componente"},{"title":"Regras de negócio","body":"- Toda nova seção de drawer DEVE usar `FormSection`\n- Não criar `<hr>` + `<h3>` ad-hoc — substituir por FormSection\n- Se a seção tiver toggle visual interno (ex.: \"Conta / PIX / Ambos\"), o toggle fica DENTRO do FormSection, não acima"},{"title":"Dependências","body":"- Usado por todos os drawers das épicas EPIC-01, EPIC-02, EPIC-03, EPIC-05, EPIC-06\n\n---"}],"criterios":["Cada seção é um `<fieldset>` (sem border default do navegador)","`<legend>` em uppercase, font-weight 600, cor azul primária (var(--tfd-primary-600))","Espaçamento vertical consistente entre seções","Os 13 drawers listados estão usando o componente"],"regras":["Toda nova seção de drawer DEVE usar `FormSection`","Não criar `<hr>` + `<h3>` ad-hoc — substituir por FormSection","Se a seção tiver toggle visual interno (ex.: \"Conta / PIX / Ambos\"), o toggle fica DENTRO do FormSection, não acima"],"dependencias":["Usado por todos os drawers das épicas EPIC-01, EPIC-02, EPIC-03, EPIC-05, EPIC-06","--"]}]},{"file":"F02-AnexosUploadField","code":"F02","title":"AnexosUploadField — anexos opcionais em todo drawer do fluxo","description":"Campo reutilizável de upload de anexos com carimbo de origem. Cada anexo enviado por um drawer do fluxo recebe automaticamente uma origem (parecer, passagem, ajuda_custo, adicional, carimbo, agendamento, tentativa) e aparece consolidado na aba Anexos da solicitação.","meta":[{"key":"Componente","value":"`src/shared/components/anexos-upload-field/AnexosUploadField.tsx`"},{"key":"Status","value":"✅ Implementado"},{"key":"Drawers afetados","value":"NewParecerDrawer · NewPassagemDrawer · NewAjudaCustoDrawer · NewAdicionalDrawer · CarimboRegulacaoDrawer · RegistrarAgendamentoDrawer · NewTentativaDrawer"}],"userStories":[{"id":"US-DSN-02","title":"Upload de anexos com carimbo de origem em todo drawer do fluxo","story":"**Como** Usuário do fluxo (Atendente/Regulador/Financeiro), **Quero** anexar arquivos diretamente no drawer onde estou registrando a ação (parecer, passagem, ajuda de custo etc.), **Para que** o documento fique vinculado àquele evento e apareça automaticamente na aba Anexos da solicitação com a origem identificada.","sections":[{"title":"Componentes do protótipo","body":"- Componente: `src/shared/components/anexos-upload-field/AnexosUploadField.tsx`\n- Aba consolidada: aba \"Anexos\" do detalhe da solicitação"},{"title":"Critérios de aceite (visuais)","body":"- [ ] Os 7 drawers listados expõem um `AnexosUploadField` ao final do formulário (opcional)\n- [ ] Cada drawer passa uma prop `origem` com um dos valores: `parecer`, `passagem`, `ajuda_custo`, `adicional`, `carimbo`, `agendamento`, `tentativa`\n- [ ] Anexos enviados aparecem automaticamente na aba \"Anexos\" da solicitação com badge da origem"},{"title":"Regras de negócio","body":"- O upload é OPCIONAL em todos os drawers (não bloqueia salvar)\n- O carimbo de origem é o único campo que diferencia os anexos na aba consolidada\n- Excluir o evento que gerou o anexo NÃO apaga o anexo (decisão de produto: histórico fica)"},{"title":"Dependências","body":"- [[../../EPIC-02-Solicitacoes-TFD/F03-Detalhe-e-Edicao-de-Solicitacao|EPIC-02 F03 — Detalhe da Solicitação]] (aba Anexos)\n\n---"}],"criterios":["Os 7 drawers listados expõem um `AnexosUploadField` ao final do formulário (opcional)","Cada drawer passa uma prop `origem` com um dos valores: `parecer`, `passagem`, `ajuda_custo`, `adicional`, `carimbo`, `agendamento`, `tentativa`","Anexos enviados aparecem automaticamente na aba \"Anexos\" da solicitação com badge da origem"],"regras":["O upload é OPCIONAL em todos os drawers (não bloqueia salvar)","O carimbo de origem é o único campo que diferencia os anexos na aba consolidada","Excluir o evento que gerou o anexo NÃO apaga o anexo (decisão de produto: histórico fica)"],"dependencias":["[[../../EPIC-02-Solicitacoes-TFD/F03-Detalhe-e-Edicao-de-Solicitacao|EPIC-02 F03 — Detalhe da Solicitação]] (aba Anexos)","--"]}]},{"file":"F03-Backlog-Page","code":"F03","title":"Página /backlog navegável","description":"Página interna em `/backlog` que renderiza o backlog estruturado (épicos, features, US) com checkboxes persistentes, renderers visuais por seção e canvas Persona/Quer/Para que.","meta":[{"key":"Tela","value":"`/backlog`"},{"key":"Arquivos-chave","value":"`src/app/backlog/page.tsx` · `src/app/backlog/_BacklogClient.tsx` · `src/app/backlog/_data.ts` · `src/app/backlog/_types.ts`"},{"key":"Status","value":"✅ Implementado"}],"userStories":[{"id":"US-DSN-03","title":"Backlog interativo com checkboxes persistentes e renderers visuais","story":"**Como** Dev do TFD, **Quero** consultar o backlog dentro do próprio sistema, marcando o que já entreguei e vendo critérios/regras/dependências com destaque visual, **Para que** eu não precise abrir o Obsidian para entender o que falta numa US.","sections":[{"title":"Componentes do protótipo","body":"- Página: `src/app/backlog/page.tsx`\n- Client: `src/app/backlog/_BacklogClient.tsx`\n- Estrutura JSON inline: `src/app/backlog/_data.ts`\n- Tipos: `src/app/backlog/_types.ts`"},{"title":"Critérios de aceite (visuais)","body":"- [ ] Cada Épico, Feature e US tem um checkbox próprio\n- [ ] O estado dos checkboxes é persistido em `localStorage`\n- [ ] Bloco \"Critérios\" renderiza em verde\n- [ ] Bloco \"Regras\" renderiza em azul, numerado\n- [ ] Bloco \"Side effects\" renderiza como timeline amarela\n- [ ] Bloco \"Estados visuais\" renderiza em âmbar\n- [ ] Bloco \"Dependências\" renderiza como chips\n- [ ] Cada US mostra um canvas com 3 colunas: Persona · Quer · Para que (extraído da `story`)"},{"title":"Regras de negócio","body":"- A estrutura é estática (vive em `_data.ts`) — atualizada manualmente a cada mudança no sistema\n- A página não lê arquivos do disco em runtime\n- Toda mudança de regra/banco/front no TFD deve atualizar `_data.ts`"},{"title":"Dependências","body":"- Nenhuma — feature isolada de Discovery interno\n\n---"}],"criterios":["Cada Épico, Feature e US tem um checkbox próprio","O estado dos checkboxes é persistido em `localStorage`","Bloco \"Critérios\" renderiza em verde","Bloco \"Regras\" renderiza em azul, numerado","Bloco \"Side effects\" renderiza como timeline amarela","Bloco \"Estados visuais\" renderiza em âmbar","Bloco \"Dependências\" renderiza como chips","Cada US mostra um canvas com 3 colunas: Persona · Quer · Para que (extraído da `story`)"],"regras":["A estrutura é estática (vive em `_data.ts`) — atualizada manualmente a cada mudança no sistema","A página não lê arquivos do disco em runtime","Toda mudança de regra/banco/front no TFD deve atualizar `_data.ts`"],"dependencias":["Nenhuma — feature isolada de Discovery interno","--"]}]}]}],"readme":"---\ntags:\n  - cliente/citiesoft\n  - projeto/citiesoft/ses-tfd\n  - tipo/backlog\n---\n\n# Backlog — TFD (Fluxo V2 MVP)\n\n> Backlog organizado em épicos → features → user stories, refletindo o que **já está validado pelos setores** no protótipo `tfd-prototype` (branch `fluxo-v2-mvp`).\n> Cada feature vira PBI no Azure DevOps. Os critérios de aceite são a base dos testes (escritos pelos próprios devs).\n\n---\n\n## Escopo deste backlog\n\n**Validado e pronto para sprint (sem asterisco):**\n\n- Solicitações TFD (listagem + cadastro/edição/detalhe)\n- Pacientes (cadastro completo)\n- Unidades de Saúde\n- Regionais de Saúde\n- Configurações (cadastros mestres / tabelas auxiliares)\n- Administrativo (usuários, papéis, logs)\n- Regulação — **apenas** a feature de Parecer Médico\n\n**Documentado mas aguardando validação (com asterisco `*` e pasta `-PENDENTE`):**\n\n- EPIC-05 — Regulação: Carimbo, Tentativas e Agendamento confirmado\n- EPIC-06 — Financeiro: Passagens, Ajudas de Custo, Adicionais\n- EPIC-07 — Relatórios\n- EPIC-08 — Painel / Dashboard\n\n> Esses épicos têm USs documentadas para revisão, mas **não foram alocados em sprints**. Após validação com os setores, serão repassados (ajustes nas US + alocação) e poderão entrar nas sprints seguintes.\n\n---\n\n## Estrutura\n\n```\nBacklog/\n├── README.md                           ← este arquivo (índice)\n├── cronograma-sprints.md               ← distribuição em sprints de 2 semanas\n├── EPIC-01-Cadastros-Fundamentais/\n│   ├── F01-Pacientes.md\n│   ├── F02-Unidades-Saude.md\n│   └── F03-Regionais-Saude.md\n├── EPIC-02-Solicitacoes-TFD/\n│   ├── F01-Listagem-Solicitacoes.md\n│   ├── F02-Cadastro-Solicitacao.md\n│   ├── F03-Detalhe-e-Edicao-Solicitacao.md\n│   └── F04-Tramitacao-Entre-Setores.md\n├── EPIC-03-Regulacao-Parecer-Medico/\n│   └── F01-Parecer-Medico.md\n├── EPIC-04-Configuracoes-Administrativo/\n│   ├── F01-Cadastros-Mestres.md\n│   ├── F02-Usuarios.md\n│   ├── F03-Papeis-e-Permissoes.md\n│   └── F04-Logs-Auditoria.md\n├── EPIC-05-Regulacao-Carimbo-Agendamento-PENDENTE/   ⚠ aguardando validação\n│   ├── F01-Carimbo-Regulacao.md\n│   ├── F02-Tentativas-Unidade.md\n│   └── F03-Agendamento-Confirmado.md\n├── EPIC-06-Financeiro-PENDENTE/                      ⚠ aguardando validação\n│   ├── F01-Passagens.md\n│   ├── F02-Ajudas-de-Custo.md\n│   └── F03-Adicionais.md\n├── EPIC-07-Relatorios-PENDENTE/                      ⚠ aguardando validação\n│   └── F01-Relatorios.md\n└── EPIC-08-Painel-Dashboard-PENDENTE/                ⚠ aguardando validação\n    └── F01-Painel.md\n```\n\n---\n\n## Épicos\n\n| Épico | Foco | Features | Total de US | Status |\n|-------|------|----------|-------------|--------|\n| EPIC-01 — Cadastros Fundamentais | Bases para o fluxo TFD funcionar | 3 | 16 | ✅ Validado |\n| EPIC-02 — Solicitações TFD | Coração do sistema: ciclo de vida da solicitação | 4 | 22 | ✅ Validado |\n| EPIC-03 — Regulação: Parecer Médico | Decisão clínica do médico regulador (deferir/indeferir) | 1 | 8 | ✅ Validado |\n| EPIC-04 — Configurações & Administrativo | Manutenção do sistema pelo administrador | 4 | 17 | ✅ Validado |\n| EPIC-05* — Regulação: Carimbo, Tentativas, Agendamento | Fluxo operacional pós-parecer | 3 | 11 | ⚠ Pendente |\n| EPIC-06* — Financeiro | Passagens, ajudas de custo, adicionais | 3 | 14 | ⚠ Pendente |\n| EPIC-07* — Relatórios | Visões consolidadas (financeiro, faturamento, recibos) | 1 | 5 | ⚠ Pendente |\n| EPIC-08* — Painel/Dashboard | Tela inicial com KPIs e alertas | 1 | 5 | ⚠ Pendente |\n\n---\n\n## Convenções\n\n- **Códigos de US**: `US-<MODULO>-<NN>` (ex.: `US-PAC-01`, `US-SOL-03`, `US-PAR-02`).\n- **Features**: `F<NN>-<Nome-Curto>.md` dentro do épico.\n- **Critérios de aceite**: redigidos como passo-a-passo do que o dev/QA vai testar olhando a tela — *\"clica em X → abre Y → ao confirmar volta pra Z\"*.\n- **Regras de negócio**: tudo que não é óbvio só de olhar a tela. Validações, perfis, defaults, comportamentos condicionais.\n- **Dependências**: outras US, telas ou serviços que precisam estar prontos antes.\n\n---\n\n## Como o dev usa\n\n1. Abre o épico relacionado ao card que vai pegar.\n2. Abre o arquivo da feature.\n3. Copia a US específica e cria o PBI no Azure DevOps.\n4. Os critérios de aceite viram a checklist de teste do PBI.\n5. Quando todas as US de uma feature estão \"done\", a feature está pronta.\n\n---\n\n## Status\n\n| Estado | Significado |\n|--------|-------------|\n| ✅ Validado | Já implementado no protótipo e aprovado pelo setor |\n| 🚧 Em desenvolvimento | Sendo implementado nesta sprint |\n| ⏸ Aguardando validação | Implementado, aguardando teste do setor |\n| 📋 Backlog | Documentado, ainda não iniciado |\n\nNeste backlog, **todas as US são \"✅ Validado\"** — refletem o estado atual do protótipo aprovado pelo TFD. O trabalho dos devs é implementar essas features no produto final (Citiesoft) seguindo essa especificação.\n","cronograma":"---\ntags:\n  - cliente/citiesoft\n  - projeto/citiesoft/ses-tfd\n  - tipo/cronograma\n---\n\n# Cronograma de Sprints — TFD\n\n> Sprints de **2 semanas (10 dias úteis)**, iniciando **segunda-feira** e terminando **sexta-feira**, conforme padrão Citiesoft (Scrum).\n> Distribuição abaixo é **sugestão** baseada na complexidade e dependências; o time de desenvolvimento ajusta no planning de cada sprint.\n\n---\n\n## Calendário base\n\n| Sprint | Início (seg) | Fim (sex) |\n|--------|--------------|-----------|\n| Sprint 1 | 2026-05-25 | 2026-06-05 |\n| Sprint 2 | 2026-06-08 | 2026-06-19 |\n| Sprint 3 | 2026-06-22 | 2026-07-03 |\n| Sprint 4 | 2026-07-06 | 2026-07-17 |\n\n---\n\n## Distribuição sugerida\n\n### Sprint 1 — Fundação dos cadastros\n**2026-05-25 → 2026-06-05**\n\nObjetivo: ter os cadastros mestres funcionando, sem os quais nenhuma solicitação pode ser criada.\n\n| Feature | Épico |\n|---------|-------|\n| F01 — Pacientes | EPIC-01 |\n| F02 — Unidades de Saúde | EPIC-01 |\n| F03 — Regionais de Saúde | EPIC-01 |\n| F01 — Cadastros Mestres (tabelas auxiliares) | EPIC-04 |\n\n> Cadastros mestres entram nesta sprint porque pacientes/unidades dependem deles (vínculos, tipos de documento, regiões etc.).\n\n---\n\n### Sprint 2 — Solicitações: listagem e cadastro\n**2026-06-08 → 2026-06-19**\n\nObjetivo: o atendente do TFD consegue criar uma solicitação completa e localizá-la na listagem.\n\n| Feature | Épico |\n|---------|-------|\n| F01 — Listagem de Solicitações | EPIC-02 |\n| F02 — Cadastro de Solicitação | EPIC-02 |\n| F02 — Usuários | EPIC-04 |\n\n---\n\n### Sprint 3 — Solicitações: detalhe, tramitação e perfis\n**2026-06-22 → 2026-07-03**\n\nObjetivo: solicitação navega entre setores e o controle de acesso está em pé.\n\n| Feature | Épico |\n|---------|-------|\n| F03 — Detalhe e Edição de Solicitação | EPIC-02 |\n| F04 — Tramitação entre Setores | EPIC-02 |\n| F03 — Papéis e Permissões | EPIC-04 |\n\n---\n\n### Sprint 4 — Regulação e auditoria\n**2026-07-06 → 2026-07-17**\n\nObjetivo: médico regulador emite parecer dentro do sistema; trilha de auditoria visível para administradores.\n\n| Feature | Épico |\n|---------|-------|\n| F01 — Parecer Médico | EPIC-03 |\n| F04 — Logs de Auditoria | EPIC-04 |\n\n---\n\n## Capacidade e estimativa\n\n- **Time padrão Citiesoft**: 1 PO + dev front + dev back + QA (testes pelos próprios devs).\n- **Velocidade alvo**: 1 feature completa por sprint por dupla front+back.\n- **Buffer**: 20% da sprint reservado para refinamento, bug-fix de sprint anterior e imprevistos.\n- **Cerimônias**: Planning (segunda 09h), Daily (10h), Refinement (quarta na 1ª semana), Review + Retro (sexta da 2ª semana).\n\n---\n\n## Dependências críticas entre features\n\n```\nEPIC-01.F01 Pacientes  ──►  EPIC-02.F02 Cadastro Solicitação\nEPIC-01.F02 Unidades   ──►  EPIC-02.F04 Tramitação (destino na regulação — fase posterior)\nEPIC-04.F01 Cadastros mestres ──►  EPIC-01.F01 Pacientes (vínculos, tipos doc)\nEPIC-04.F02 Usuários   ──►  EPIC-04.F03 Papéis (papéis precisam ter usuários para vincular)\nEPIC-02.F03 Detalhe    ──►  EPIC-02.F04 Tramitação (envio entre setores parte do detalhe)\nEPIC-04.F03 Papéis     ──►  EPIC-03.F01 Parecer (médico precisa ter perfil ativo)\n```\n\n> Por isso EPIC-01 e o F01 do EPIC-04 vão juntos na Sprint 1: são pré-requisitos de tudo o mais.\n\n---\n\n## Pós-Sprint 4 — Épicos pendentes de validação\n\n> ⚠ **Não alocados em sprint ainda.** As US estão documentadas (com asterisco `*`) nas pastas `EPIC-XX-*-PENDENTE/` para revisão. Após validação dos setores, ajustamos as US e decidimos a alocação.\n\n| Épico | Pasta | Aguardando validação de |\n|-------|-------|--------------------------|\n| EPIC-05* — Regulação: Carimbo, Tentativas, Agendamento | `EPIC-05-Regulacao-Carimbo-Agendamento-PENDENTE/` | Setor de Regulação |\n| EPIC-06* — Financeiro: Passagens, Ajudas, Adicionais | `EPIC-06-Financeiro-PENDENTE/` | Setor Financeiro |\n| EPIC-07* — Relatórios | `EPIC-07-Relatorios-PENDENTE/` | Coordenação + Financeiro |\n| EPIC-08* — Painel / Dashboard | `EPIC-08-Painel-Dashboard-PENDENTE/` | Coordenação |\n\n### Estimativa preliminar (não comprometida)\n\nQuando validados, esses 4 épicos rendem aproximadamente:\n\n- **EPIC-05:** ~2 sprints (regulação ainda tem fluxos não-óbvios em CNRAC/SETI)\n- **EPIC-06:** ~3 sprints (financeiro é o maior em volume de regras)\n- **EPIC-07:** ~1 sprint (com dependência de dados consolidados)\n- **EPIC-08:** ~1 sprint (em paralelo com EPIC-07 — depende dos mesmos endpoints)\n\n> Total estimado pós-validação: ~7 sprints adicionais (Sprint 5 → Sprint 11), com possibilidade de paralelizar com 2 duplas dev.\n"};
